/**
 * API Tier Definitions for Vreko Licensable API
 *
 * Separate from extension tiers - these define access levels for
 * the public API used by B2B customers, CI/CD integrations, and tool builders.
 *
 * @module api-tiers
 */
import { z } from "zod";
/**
 * API tier identifiers (distinct from extension tiers)
 */
export const ApiTierSchema = z.enum(["api_free", "api_starter", "api_pro", "api_enterprise"]);
/**
 * API feature flags
 */
export const ApiFeatureSchema = z.enum([
    // Core analysis features
    "risk_scoring",
    "ai_detection",
    "session_grouping",
    "rollback_validation",
    // Advanced features
    "batch_analysis",
    "webhook_notifications",
    "custom_thresholds",
    "priority_queue",
    // Enterprise features
    "dedicated_instance",
    "sla_guarantee",
    "audit_logs",
    "sso_integration",
]);
/**
 * Rate limit configuration
 */
export const RateLimitConfigSchema = z.object({
    requestsPerMinute: z.number().int().positive(),
    requestsPerDay: z.number().int().positive(),
    maxBatchSize: z.number().int().positive(),
    maxPayloadBytes: z.number().int().positive(),
});
/**
 * Complete API tier configuration
 */
export const ApiTierConfigSchema = z.object({
    tier: ApiTierSchema,
    name: z.string(),
    description: z.string(),
    features: z.array(ApiFeatureSchema),
    rateLimits: RateLimitConfigSchema,
    priceMonthly: z.number().nonnegative(), // cents, 0 = free
    priceYearly: z.number().nonnegative(), // cents, 0 = free
});
