/**
 * Check if an API tier has access to a specific feature
 */
export function hasApiFeature(tier, feature) {
    return API_TIER_FEATURES[tier].features.includes(feature);
}
/**
 * Get rate limits for an API tier
 */
export function getApiRateLimits(tier) {
    return API_TIER_FEATURES[tier].rateLimits;
}
/**
 * API key schema for validation
 */
export const ApiKeySchema = z.object({
    id: z.string().uuid(),
    key: z.string().regex(/^sb_live_[a-zA-Z0-9]{32}$/, "Invalid API key format"),
    tier: ApiTierSchema,
    organizationId: z.string().uuid().optional(),
    name: z.string().max(100).optional(),
    createdAt: z.coerce.date(),
    expiresAt: z.coerce.date().optional(),
    lastUsedAt: z.coerce.date().optional(),
    isActive: z.boolean().default(true),
});
/**
 * API usage tracking schema
 */
export const ApiUsageSchema = z.object({
    keyId: z.string().uuid(),
    endpoint: z.string(),
    requestCount: z.number().int().nonnegative(),
    bytesProcessed: z.number().int().nonnegative(),
    period: z.enum(["minute", "hour", "day", "month"]),
    timestamp: z.coerce.date(),
});
/**
 * Create API key request schema
 */
export const CreateApiKeyRequestSchema = z.object({
    name: z.string().max(100).optional(),
    expiresAt: z.coerce.date().optional(),
});
/**
 * API endpoints available for each tier
 */
export const API_ENDPOINTS = {
    RISK_SCORING: "/v1/analyze/risk",
    AI_DETECTION: "/v1/analyze/ai-detection",
    SESSION_GROUPING: "/v1/analyze/grouping",
    ROLLBACK_VALIDATION: "/v1/snapshots/validate-rollback",
};
/**
 * Endpoint to required feature mapping
 */
export const ENDPOINT_FEATURES = {
    [API_ENDPOINTS.RISK_SCORING]: "risk_scoring",
    [API_ENDPOINTS.AI_DETECTION]: "ai_detection",
    [API_ENDPOINTS.SESSION_GROUPING]: "session_grouping",
    [API_ENDPOINTS.ROLLBACK_VALIDATION]: "rollback_validation",
};
