import { z } from "zod";
import { RiskScoreDetailSchema } from "../schemas.js";
import { RiskSeveritySchema } from "./analysis.js";
// =============================================================================
// SNAPSHOT TRIGGER & ORIGIN TYPES (ADR-004 Consolidated)
// =============================================================================
/**
 * Snapshot trigger sources - canonical enum for all surfaces
 * Consolidates triggers from VSCode, MCP, CLI, and API
 */
export const SnapshotTriggerSchema = z.enum([
    "manual",
    "auto",
    "auto_save",
    "ai_detected",
    "ai-detected", // Legacy alias
    "pre_save",
    "pre-save", // Legacy alias
    "session_start",
    "session_end",
    "mcp_snap_start",
    "cli_protect",
    "api_request",
    "engine_internal",
    "recovery",
]);
/**
 * Snapshot origin classification for DORA metrics
 * Distinguishes user-initiated vs automated snapshots
 */
export const SnapshotOriginSchema = z.enum(["manual", "auto", "ai-detected", "recovery", "INTERACTIVE", "AUTOMATED"]);
/**
 * Migration map for VSCode-specific snapshot origins
 * Maps granular VSCode origin values to canonical SnapshotOrigin enum
 *
 * Usage:
 * ```typescript
 * const canonical = ORIGIN_MIGRATION_MAP["pre-save"] ?? vscodeOrigin; // "auto"
 * ```
 */
export const ORIGIN_MIGRATION_MAP = {
    "pre-save": "auto",
    scheduled: "auto",
    "pre-restore": "recovery",
};
/**
 * Reason codes for snapshot creation (from VSCode ManifestV2)
 * Used for explainability and debugging
 * Consolidated from VSCode storage and contracts definitions
 */
export const SnapshotReasonCodeSchema = z.enum([
    // AI detection
    "AI_DETECTED",
    // Manual operations
    "MANUAL_CHECKPOINT",
    "MANUAL_SAVE",
    // Risk-based triggers
    "CRITICAL_FILE",
    "HIGH_RISK",
    "RISK_BURST_START",
    "RISK_LARGE_DELETE",
    "RISK_MULTI_FILE",
    // Session lifecycle
    "SESSION_START",
    "SESSION_END",
    "IDLE_FINALIZE",
    // Rollback operations
    "PRE_ROLLBACK",
    // Optimization modes
    "BURST_MODE",
]);
/**
 * Checkpoint type for V2 manifests
 * PRE = pointer-only (marks start of risky operation)
 * POST = contains actual file content
 * PRE_ROLLBACK = pointer before rollback operation
 */
export const CheckpointTypeSchema = z.enum(["PRE", "POST", "PRE_ROLLBACK"]);
/**
 * Base Snapshot interface
 * This is the core data structure for snapshots across all Vreko clients
 *
 * Session Linkage (Non-Breaking Extension):
 * Snapshots can optionally link to a parent session via meta.sessionId.
 * This enables:
 * - Displaying snapshots within session tree view
 * - Understanding snapshot creation context
 * - Grouping snapshots by logical work period
 *
 * Example meta object:
 * {
 *   name: "Pre-refactor checkpoint",
 *   protected: true,
 *   sessionId: "clx1a2b3c4d5e6f7g8h9" // Optional link to session
 * }
 *
 * Version Compatibility:
 * - version: Snapshot format version (default: "1.0")
 * - Compatible versions: ["1.0"]
 */
export const SnapshotSchema = z.object({
    id: z.string(),
    timestamp: z.number(),
    version: z.string().optional().default("1.0"),
    meta: z.record(z.string(), z.any()).optional(),
    files: z.array(z.string()).optional(),
    fileContents: z.record(z.string(), z.string()).optional(),
});
/**
 * File state at a specific snapshot
 * Used for deduplication and change tracking
 * Enhanced per ADR-004 with encryption support
 *
 * Note: `hash` is optional to support:
 * - Files being added before hashing
 * - Encrypted content where hash is computed separately
 */
export const FileStateSchema = z.object({
    path: z.string(),
    content: z.string(),
    /** SHA-256 hash of content (optional, computed for dedup) */
    hash: z.string().optional(),
    /** File size in bytes */
    size: z.number().optional(),
    /** Encrypted data (for sensitive files - VSCode format) */
    encrypted: z
        .object({
        /** Initialization vector */
        iv: z.string(),
        /** Authentication tag */
        tag: z.string(),
        /** Optional: algorithm used (default: aes-256-gcm) */
        algorithm: z.string().optional(),
    })
        .optional(),
});
/**
 * Compression codec for blob storage
 * Used in V2 file references for efficient storage
 */
export const CompressionCodecSchema = z.enum(["zstd", "gzip", "none"]);
/**
 * V2 File reference for content-addressable storage
 * Used in SnapshotManifestV2 - references blobs by hash
 * Enhanced with optional compression codec support
 */
export const SnapshotFileRefV2Schema = z.object({
    /** SHA-256 hash of file content (CAS reference) */
    blobHash: z.string(),
    /** File size in bytes */
    size: z.number(),
    /** Compression codec used (optional, defaults to 'none') */
    codec: CompressionCodecSchema.optional(),
});
/**
 * Complete snapshot state for deduplication
 * Note: This is distinct from SnapshotStatus which tracks lifecycle state
 */
export const SnapshotStateSchema = z.object({
    id: z.string(),
    timestamp: z.number(),
    files: z.array(FileStateSchema),
});
/**
 * Snapshot lifecycle status (state machine states)
 * Renamed from VSCode's SnapshotState to avoid collision with deduplication state
 */
export const SnapshotStatusSchema = z.enum(["pending", "complete", "failed", "deleted"]);
/**
 * Rich Snapshot with UI metadata
 * Used by VS Code extension and other clients with UI
 */
export const RichSnapshotSchema = SnapshotSchema.extend({
    name: z.string(),
    fileStates: z.array(FileStateSchema).optional(),
    isProtected: z.boolean(),
    icon: z.string().optional(),
    iconColor: z.string().optional(),
});
/**
 * Minimal snapshot for list operations and deletion
 * Consolidated from VSCode and contracts definitions
 */
export const MinimalSnapshotSchema = z.object({
    id: z.string(),
    name: z.string(),
    timestamp: z.number(),
    fileCount: z.number(),
    origin: SnapshotOriginSchema.optional(),
    isProtected: z.boolean(),
    label: z.string().optional(),
});
/**
 * File input for snapshot creation
 */
export const FileInputSchema = z.object({
    path: z.string(),
    content: z.string(),
    action: z.enum(["add", "modify", "delete"]),
});
/**
 * Snapshot creation options
 * Enhanced per ADR-004 with DORA metric extensions from VSCode
 */
export const CreateSnapshotOptionsSchema = z.object({
    /** Description/reason for the snapshot */
    description: z.string().optional(),
    /** Whether to protect from auto-deletion */
    protected: z.boolean().optional(),
    /** What triggered the snapshot */
    trigger: SnapshotTriggerSchema.optional(),
    /** Origin classification for DORA metrics */
    origin: SnapshotOriginSchema.optional(),
    /** Time since last file change in ms (DORA lead time metric) */
    timeSinceLastChangeMs: z.number().optional(),
});
/**
 * Snapshot filters for querying
 */
export const SnapshotFiltersSchema = z.object({
    filePath: z.string().optional(),
    before: z.date().optional(),
    after: z.date().optional(),
    protected: z.boolean().optional(),
    limit: z.number().int().positive().optional(),
    offset: z.number().int().nonnegative().optional(),
});
/**
 * File diff for restore preview
 */
export const FileDiffSchema = z.object({
    path: z.string(),
    operation: z.enum(["create", "modify", "delete"]),
    linesAdded: z.number(),
    linesRemoved: z.number(),
    preview: z.string(),
    currentChecksum: z.string().optional(),
    snapshotChecksum: z.string().optional(),
});
/**
 * Diff preview for restore operations
 */
export const DiffPreviewSchema = z.object({
    totalFiles: z.number(),
    filesCreated: z.number(),
    filesModified: z.number(),
    filesDeleted: z.number(),
    totalLinesAdded: z.number(),
    totalLinesRemoved: z.number(),
    diffs: z.array(FileDiffSchema),
});
/**
 * Conflict report for restore operations
 */
export const ConflictReportSchema = z.object({
    path: z.string(),
    reason: z.string(),
    currentChecksum: z.string(),
    snapshotChecksum: z.string(),
});
/**
 * Snapshot restore result (enhanced with diff previews and conflicts)
 */
export const SnapshotRestoreResultSchema = z.object({
    success: z.boolean(),
    restoredFiles: z.array(z.string()),
    errors: z.array(z.string()).optional(),
    diffPreview: DiffPreviewSchema.optional(),
    conflicts: z.array(ConflictReportSchema).optional(),
    verification: z
        .object({
        allVerified: z.boolean(),
        results: z.array(z.object({
            path: z.string(),
            verified: z.boolean(),
            checksum: z.string(),
            expected: z.string(),
        })),
    })
        .optional(),
});
/**
 * Snapshot manager configuration
 */
export const SnapshotManagerConfigSchema = z.object({
    enableDeduplication: z.boolean().default(true),
    namingStrategy: z.enum(["git", "semantic", "timestamp", "custom"]).default("semantic"),
    autoProtect: z.boolean().default(false),
    maxSnapshots: z.number().int().positive().optional(),
});
/**
 * File metadata for analytics and tracking
 *
 * Note: Uses canonical RiskScoreDetailSchema from schemas.ts (0-10 scale)
 */
export const FileMetadataSchema = z.object({
    id: z.string(),
    path: z.string(),
    hash: z.string().optional(),
    size: z.number().optional(),
    language: z.string().optional(),
    risk: RiskScoreDetailSchema.optional(),
    lastModified: z.number().optional(),
    createdAt: z.number().optional(),
});
/**
 * Snapshot metadata for analytics (Enhanced per ADR-004)
 * Includes VSCode ManifestV2 fields for full surface parity
 */
export const SnapshotMetadataSchema = z.object({
    // Core fields (required)
    id: z.string(),
    timestamp: z.number(),
    fileCount: z.number(),
    // Analytics fields (optional)
    totalSize: z.number().optional(),
    riskScore: RiskScoreDetailSchema.optional(),
    tags: z.array(z.string()).optional(),
    // V2 Hierarchy fields (from VSCode ManifestV2)
    /** Sequential snapshot number (1-based, monotonic) */
    seq: z.number().int().positive().optional(),
    /** Parent snapshot seq (null for root) */
    parentSeq: z.number().int().positive().nullable().optional(),
    /** Parent snapshot ID */
    parentId: z.string().nullable().optional(),
    /** Checkpoint type */
    type: CheckpointTypeSchema.optional(),
    /** Main file that triggered this snapshot */
    anchorFile: z.string().optional(),
    // DORA Metrics fields
    /** Time since last file change in ms (for lead time metric) */
    timeSinceLastChangeMs: z.number().optional(),
    /** Compression ratio achieved (for storage efficiency) */
    compressionRatio: z.number().optional(),
    /** Storage size in bytes (after compression) */
    storageSizeBytes: z.number().optional(),
    // Origin & Classification
    /** Origin classification for analytics */
    origin: SnapshotOriginSchema.optional(),
    /** Reason codes for explainability */
    reasons: z.array(SnapshotReasonCodeSchema).optional(),
    // AI Detection
    aiDetection: z
        .object({
        detected: z.boolean(),
        tool: z.string().optional(),
        confidence: z.number().min(0).max(1).optional(),
    })
        .optional(),
    // Session linkage
    /** Vreko session ID */
    sessionId: z.string().optional(),
    /** External task ID (from LLM agent) */
    taskId: z.string().optional(),
    // UI fields
    name: z.string().optional(),
    icon: z.string().optional(),
});
// =============================================================================
// SNAPSHOT MANIFEST V2 (ADR-004 - Canonical Definition)
// =============================================================================
/**
 * V2 Snapshot Manifest - Canonical definition from VSCode extension
 * This is the SINGLE SOURCE OF TRUTH for V2 manifest structure.
 *
 * Features:
 * - Sequential numbering (seq) for ordering
 * - Parent chain (parentSeq, parentId) for history
 * - Checkpoint types (PRE/POST/PRE_ROLLBACK)
 * - Content-addressable file storage via blobHash
 * - Rich metadata for analytics and DORA metrics
 */
export const SnapshotManifestV2Schema = z.object({
    /** Schema version - always 2 for V2 */
    schemaVersion: z.literal(2),
    /** Unique ID: vreko-{timestamp}-{random} */
    id: z.string(),
    /** Sequential snapshot number (1-based, monotonic) */
    seq: z.number().int().positive(),
    /** Parent snapshot seq (null for root) */
    parentSeq: z.number().int().positive().nullable(),
    /** Parent snapshot ID (null for root) */
    parentId: z.string().nullable(),
    /** Unix timestamp (ms) */
    timestamp: z.number(),
    /** Human-readable name */
    name: z.string(),
    /** Checkpoint type */
    type: CheckpointTypeSchema,
    /** The main file that triggered this snapshot */
    anchorFile: z.string(),
    /** Files in snapshot (path → ref). Empty for PRE checkpoints. */
    files: z.record(z.string(), SnapshotFileRefV2Schema),
    /** Optional metadata */
    metadata: z
        .object({
        /** Risk score 0-1 */
        riskScore: z.number().min(0).max(1).optional(),
        /** Origin classification */
        origin: SnapshotOriginSchema.optional(),
        /** Stable reason codes */
        reasons: z.array(SnapshotReasonCodeSchema).optional(),
        /** AI detection info */
        aiDetection: z
            .object({
            detected: z.boolean(),
            tool: z.string().optional(),
            confidence: z.number().optional(),
        })
            .optional(),
        /** Vreko session ID */
        sessionId: z.string().optional(),
        /** External task ID */
        taskId: z.string().optional(),
        /** DORA: Time since last change */
        timeSinceLastChangeMs: z.number().optional(),
    })
        .optional(),
});
/**
 * V1 Snapshot Manifest - Legacy format for backward compatibility
 */
export const SnapshotManifestV1Schema = z.object({
    /** Unique ID */
    id: z.string(),
    /** Unix timestamp (ms) */
    timestamp: z.number(),
    /** Human-readable name */
    name: z.string(),
    /** Trigger reason */
    trigger: z.enum(["auto", "manual", "ai-detected", "pre-save"]),
    /** Main file that triggered snapshot */
    anchorFile: z.string(),
    /** Files in snapshot (path → ref) */
    files: z.record(z.string(), z.object({
        blob: z.string(),
        size: z.number(),
    })),
    /** Optional metadata */
    metadata: z
        .object({
        riskScore: z.number().optional(),
        aiDetection: z
            .object({
            detected: z.boolean(),
            tool: z.string().optional(),
            confidence: z.number().optional(),
        })
            .optional(),
        sessionId: z.string().optional(),
        taskId: z.string().optional(),
    })
        .optional(),
});
/**
 * Type guard for V2 manifests
 */
export function isSnapshotManifestV2(manifest) {
    return (typeof manifest === "object" &&
        manifest !== null &&
        "schemaVersion" in manifest &&
        manifest.schemaVersion === 2);
}
/**
 * Type guard for POST checkpoints (have content)
 */
export function isPostCheckpoint(manifest) {
    if (!isSnapshotManifestV2(manifest)) {
        return true; // V1 manifests always have content
    }
    return manifest.type === "POST";
}
/**
 * Type guard for pointer checkpoints (PRE, PRE_ROLLBACK)
 */
export function isPointerCheckpoint(manifest) {
    if (!isSnapshotManifestV2(manifest)) {
        return false;
    }
    return manifest.type === "PRE" || manifest.type === "PRE_ROLLBACK";
}
// =============================================================================
// STORAGE METRICS (For Deduplication Transparency)
// =============================================================================
/**
 * Storage metrics from snapshot creation
 *
 * Provides transparency into CAS (Content-Addressable Storage) efficiency:
 * - How many files were actually written vs deduplicated
 * - Actual storage impact vs logical file count
 * - Deduplication ratio for user-facing display
 *
 * UI Display Example:
 * "Snapshot created: 847 files (23 new, 824 deduplicated) | 94% storage saved"
 *
 * @example
 * {
 *   totalFiles: 847,
 *   newBlobsWritten: 23,
 *   dedupedFiles: 824,
 *   dedupRatio: 0.97,
 *   bytesWritten: 145920,
 *   originalSize: 4832000,
 *   bytesSaved: 4686080
 * }
 */
export const StorageMetricsSchema = z.object({
    /** Total files in snapshot */
    totalFiles: z.number().int().nonnegative(),
    /** New blobs written to storage (not deduplicated) */
    newBlobsWritten: z.number().int().nonnegative(),
    /** Files that were deduplicated (already existed in CAS) */
    dedupedFiles: z.number().int().nonnegative(),
    /** Deduplication ratio (0-1) - higher means more storage saved */
    dedupRatio: z.number().min(0).max(1),
    /** Actual bytes written to storage */
    bytesWritten: z.number().int().nonnegative(),
    /** Original size of all files (before dedup) */
    originalSize: z.number().int().nonnegative(),
    /** Storage savings in bytes (originalSize - bytesWritten) */
    bytesSaved: z.number().int().nonnegative(),
});
/**
 * Helper to calculate dedup ratio from metrics
 * Returns 0 if no files, avoiding division by zero
 */
export function calculateDedupRatio(newBlobs, totalFiles) {
    if (totalFiles === 0) {
        return 0;
    }
    return 1 - newBlobs / totalFiles;
}
/**
 * Create StorageMetrics from blob store results
 * Aggregates per-file isNew flags into summary metrics
 *
 * @param blobResults - Array of { size, isNew } from blob store operations
 * @returns Complete StorageMetrics object
 */
export function createStorageMetrics(blobResults) {
    const totalFiles = blobResults.length;
    const newBlobsWritten = blobResults.filter((r) => r.isNew).length;
    const dedupedFiles = totalFiles - newBlobsWritten;
    const originalSize = blobResults.reduce((sum, r) => sum + r.size, 0);
    const bytesWritten = blobResults.filter((r) => r.isNew).reduce((sum, r) => sum + r.size, 0);
    const bytesSaved = originalSize - bytesWritten;
    const dedupRatio = calculateDedupRatio(newBlobsWritten, totalFiles);
    return {
        totalFiles,
        newBlobsWritten,
        dedupedFiles,
        dedupRatio,
        bytesWritten,
        originalSize,
        bytesSaved,
    };
}
/**
 * Analytics response structure
 */
export const AnalyticsResponseSchema = z.object({
    workspaceId: z.string(),
    period: z.object({
        start: z.number(),
        end: z.number(),
    }),
    risk: RiskScoreDetailSchema,
    fileStats: z.object({
        total: z.number(),
        byLanguage: z.record(z.string(), z.number()),
        byRisk: z.record(z.string(), z.number()),
    }),
    snapshotStats: z.object({
        total: z.number(),
        frequency: z.number(),
        averageSize: z.number().optional(),
    }),
    snapshotRecommendations: z.object({
        shouldCreateSnapshot: z.boolean(),
        reason: z.string(),
        urgency: RiskSeveritySchema,
        suggestedTiming: z.string(),
    }),
    trends: z.object({
        risk: z.array(z.object({
            timestamp: z.number(),
            score: z.number(),
        })),
        activity: z.array(z.object({
            timestamp: z.number(),
            count: z.number(),
        })),
    }),
});
