/**
 * Claims Ledger Base Schema
 *
 * Core types and schemas for the claims ledger system.
 * All claim families extend BaseClaim with family-specific fields.
 */
import { z } from "zod";
// =============================================================================
// Claim Subject Kinds
// =============================================================================
/**
 * Valid subject kinds for claims.
 * A claim is always about something  -  a PR, a spec, a session, etc.
 */
export const ClaimSubjectKind = z.enum([
    "pr",
    "spec",
    "session",
    "commit",
    "file",
    "phase",
    "workspace",
    "claim", // For correction claims referencing other claims
]);
// =============================================================================
// Claimant Identification
// =============================================================================
/**
 * URN format for claimants.
 * Pattern: urn:claimant:<identifier>
 *
 * Examples:
 * - urn:claimant:subagent-stop-hook
 * - urn:claimant:drift-detector
 * - urn:claimant:spec-writer
 * - urn:claimant:intelligence.risk-scorer
 * - urn:claimant:intelligence.fragility-detector
 */
export const ClaimantUrn = z.string().regex(/^urn:claimant:[a-z0-9.-]+$/);
// =============================================================================
// Outcome Resolution Strategies
// =============================================================================
/**
 * Three permitted outcome resolution strategies.
 *
 * - immediate: Outcome known at claim time (e.g., R-gate execution)
 * - deferred-manual: Outcome written later by specific process (e.g., PR merge)
 * - deferred-observational: Outcome emerges from system observation (e.g., rollback counting)
 */
export const OutcomeResolutionStrategy = z.enum(["immediate", "deferred-manual", "deferred-observational"]);
// =============================================================================
// Base Claim Schema
// =============================================================================
/**
 * Evidence gate  -  a single verification checkpoint.
 */
export const EvidenceGate = z.object({
    name: z.string(),
    passed: z.boolean(),
    output: z.string().optional(),
});
/**
 * Base claim schema.
 * All claim families extend this with family-specific fields.
 */
export const BaseClaim = z.object({
    // Identity
    claimId: z.string().uuid(),
    claimedAt: z.number().int().positive(),
    // Attribution
    claimant: ClaimantUrn,
    claimType: z.string(),
    claimFamily: z.enum(["completion", "verdict", "attribution", "prediction"]),
    // Subject (what the claim is about)
    subject: z.object({
        kind: ClaimSubjectKind,
        ref: z.string().min(1),
    }),
    // Confidence (null for mechanical claims, [0,1] for predictive/attribution)
    confidence: z.number().min(0).max(1).nullable(),
    // Evidence supporting the claim
    evidence: z.object({
        gates: z.array(EvidenceGate).default([]),
        referenced: z.array(z.string()).default([]),
    }),
});
// =============================================================================
// Outcome Schema
// =============================================================================
/**
 * Outcome types for claim resolution.
 *
 * - verified: Claim was correct
 * - refuted: Claim was incorrect
 * - ambiguous: Outcome cannot be determined
 * - expired: TTL passed without resolution
 */
export const OutcomeType = z.enum(["verified", "refuted", "ambiguous", "expired"]);
/**
 * Outcome record  -  the resolution of a claim.
 */
export const Outcome = z.object({
    // Identity
    outcomeId: z.string().uuid(),
    claimId: z.string().uuid(),
    observedAt: z.number().int().positive(),
    // Outcome classification
    outcomeType: OutcomeType,
    // Evidence for the outcome
    evidence: z.record(z.unknown()),
    // For predictive claims: comparison between predicted and actual
    delta: z
        .object({
        predicted: z.unknown(),
        actual: z.unknown(),
    })
        .optional(),
});
// =============================================================================
// Claim with Outcome (resolved claim view)
// =============================================================================
/**
 * A claim with its outcome attached.
 * Used for queries that return resolved claims.
 */
export const ResolvedClaim = BaseClaim.extend({
    outcome: Outcome.optional(),
});
// =============================================================================
// Validation Helpers
// =============================================================================
/**
 * Validate a claim against the base schema.
 */
export function validateBaseClaim(claim) {
    return BaseClaim.safeParse(claim).success;
}
/**
 * Validate an outcome.
 */
export function validateOutcome(outcome) {
    return Outcome.safeParse(outcome).success;
}
/**
 * Get validation errors for a claim.
 */
export function getClaimValidationErrors(claim) {
    const result = BaseClaim.safeParse(claim);
    if (result.success) {
        return null;
    }
    return result.error.message;
}
