/**
 * Sync Payload Schema
 *
 * Zod schema for session data pushed to cloud API.
 * PRIVACY: Only metadata syncs - file content NEVER leaves device.
 *
 * @module @vreko/contracts/sync-payload
 */
import { z } from "zod";
/**
 * SyncPayload schema for cloud sync.
 *
 * Key privacy guarantees:
 * - workspaceId is sha256(gitRemote + userId)  -  never raw path
 * - No file content fields allowed
 * - .strict() rejects unknown fields (prevents content leakage)
 */
export const SyncPayloadSchema = z
    .object({
    sessionId: z.string().uuid(),
    workspaceId: z.string(), // sha256(gitRemote + userId)  -  never raw path
    startedAt: z.number(),
    endedAt: z.number().nullable(),
    durationMs: z.number().nullable(),
    clientType: z.string(),
    snapshotCount: z.number().int().min(0),
    learningCount: z.number().int().min(0),
    touchedFileCount: z.number().int().min(0),
    riskScores: z.array(z.number().min(0).max(1)),
    // Hard limits  -  any string field signals content leakage
})
    .strict(); // reject unknown fields
/**
 * Build a SyncPayload from session data.
 * Validates the payload and throws on invalid data.
 */
export function buildSyncPayload(params) {
    const durationMs = params.endedAt ? params.endedAt - params.startedAt : null;
    return SyncPayloadSchema.parse({
        sessionId: params.sessionId,
        workspaceId: params.workspaceId,
        startedAt: params.startedAt,
        endedAt: params.endedAt,
        durationMs,
        clientType: params.clientType,
        snapshotCount: params.snapshotCount,
        learningCount: params.learningCount,
        touchedFileCount: params.touchedFileCount,
        riskScores: params.riskScores,
    });
}
