/**
 * Completion Claim Family
 *
 * Claims about task completion: "I finished the thing I was asked to do."
 *
 * Examples:
 * - SubagentStop hook claiming a spec phase is complete
 * - CI claiming a deployment is complete
 * - User claiming manual verification is complete
 */
import { z } from "zod";
import { BaseClaim } from "../base.js";
// =============================================================================
// Completion Status
// =============================================================================
/**
 * Completion status values.
 */
export const CompletionStatus = z.enum(["complete", "partial", "failed"]);
// =============================================================================
// Completion Claim Schema
// =============================================================================
/**
 * Completion claim  -  asserts a task or phase is done.
 *
 * Confidence: null (mechanical claim  -  outcome determined by gate results)
 * Resolution: immediate (outcome known at claim time)
 */
export const CompletionClaim = BaseClaim.extend({
    claimFamily: z.literal("completion"),
    // Completion-specific payload
    claim: z.object({
        status: CompletionStatus,
        completedGates: z.number().int().min(0),
        totalGates: z.number().int().positive(),
        phase: z.string().optional(),
    }),
});
// =============================================================================
// Type Guards
// =============================================================================
/**
 * Check if a claim is a completion claim.
 */
export function isCompletionClaim(claim) {
    return CompletionClaim.safeParse(claim).success;
}
/**
 * Validate and parse a completion claim.
 */
export function parseCompletionClaim(claim) {
    const result = CompletionClaim.safeParse(claim);
    return result.success ? result.data : null;
}
