/**
 * Task-First Architecture Contracts
 *
 * Tasks are the first-class entity in Vreko with stable IDs, display names,
 * accumulated state, and ceremonies. Sessions are daemon connections that come
 * and go underneath a Task.
 *
 * Core MCP flow:
 * 1. LLM calls vreko({ task: "refactor auth" }) - Task created or resumed
 * 2. LLM works, calls snap_pulse, vreko_learn - all state accumulates on the Task
 * 3. LLM calls vreko_end({ outcome: "completed" }) - Task closed, ceremony produced
 * 4. Next conversation: LLM calls vreko({ task: "update validation" }) - new Task, previous Task's context in briefing
 *
 * @see /devagents/plans/Task_Connonical_impl.md
 * @module contracts/task
 */
import { z } from "zod";
// =============================================================================
// TASK STATUS ENUM
// =============================================================================
/**
 * TaskStatus - all possible states for a Task
 *
 * State transitions:
 * - created → active
 * - active → completed, abandoned, failed, ceremony_blocked, auto-ended
 * - ceremony_blocked → active (fix issues), completed (force:true)
 * - completed, abandoned, failed, auto-ended → (terminal)
 */
export const TaskStatusSchema = z.enum([
    "created", // Task record exists, initial setup
    "active", // Work in progress, state accumulating
    "completed", // Task finished successfully, ceremony produced (terminal)
    "abandoned", // Task ended without completion (terminal)
    "failed", // Task ended due to error (terminal)
    "auto-ended", // Previous task was auto-ended when a new task started (terminal)
    "ceremony_blocked", // Quality gates failed, ceremony cannot complete
]);
/**
 * Task outcome types for internal task state machine (NOT used for MCP snap_end).
 * Note: task-coordinator.ts has a local TaskOutcome interface with "blocked" instead of "failed".
 * These are intentionally separate: this enum is for the contracts layer task entity;
 * the local interface is for the coordinator's internal state.
 * MCP snap_end uses a free-text outcome string  -  see SessionEndDaemonParams in schemas/session.ts.
 */
export const TaskOutcomeSchema = z.enum(["completed", "abandoned", "failed"]);
// =============================================================================
// TASK ENTITY SCHEMA
// =============================================================================
/**
 * Task entity - the first-class entity in Vreko
 *
 * Design principles:
 * - Stable ID and slug for deterministic matching
 * - Accumulated state survives daemon restarts (SQLite WAL mode)
 * - Derived counters eliminate the ceremony zeros bug by construction
 */
export const TaskSchema = z.object({
    /** Monotonic integer ID for system tracking */
    id: z.number().int().positive(),
    /** Deterministic kebab-case identifier generated from name */
    slug: z.string().min(1).max(64),
    /** Human-readable task name provided by LLM */
    name: z.string().min(1).max(256),
    /** Current status of the task */
    status: TaskStatusSchema,
    /** Outcome when task was closed (null if active) */
    outcome: TaskOutcomeSchema.nullable(),
    /** ISO 8601 timestamp when task was created */
    createdAt: z.string().datetime(),
    /** ISO 8601 timestamp when task was last updated */
    updatedAt: z.string().datetime(),
    /** ISO 8601 timestamp when task was closed (null if active) */
    closedAt: z.string().datetime().nullable(),
    /** JSON-serialized ceremony object (null until task closes) */
    ceremonyJson: z.string().nullable(),
    /** Task ID this task explicitly continues from (lineage) */
    continuesFrom: z.number().int().positive().nullable(),
    /** Source of migration for legacy sessions */
    migrationSource: z.enum(["active_session", "completed_session"]).nullable(),
});
// =============================================================================
// TASK EVENT SCHEMA
// =============================================================================
/**
 * TaskEventType - types of events recorded in the task timeline
 */
export const TaskEventTypeSchema = z.enum([
    "task_created",
    "task_resumed",
    "task_ended",
    "learning_captured",
    "pulse_recorded",
    "file_changed",
    "session_connected",
    "session_disconnected",
    "ceremony_blocked",
    "ceremony_completed",
]);
/**
 * TaskEvent - ordered log of all MCP tool calls and outcomes on this Task
 */
export const TaskEventSchema = z.object({
    /** Monotonic integer ID */
    id: z.number().int().positive(),
    /** Task this event belongs to */
    taskId: z.number().int().positive(),
    /** Sequence number within task (monotonically increasing) */
    seq: z.number().int().nonnegative(),
    /** Type of event */
    type: TaskEventTypeSchema,
    /** JSON-serialized event payload */
    payloadJson: z.string().nullable(),
    /** ISO 8601 timestamp when event occurred */
    timestamp: z.string().datetime(),
});
// =============================================================================
// TASK FILE SCHEMA
// =============================================================================
/**
 * FileAction - types of file operations tracked
 */
export const FileActionSchema = z.enum(["added", "modified", "deleted"]);
/**
 * TaskFile - file change log entry
 *
 * Critical design principle: All writes are append-only.
 * Files are tracked by the daemon autonomously via Git diff.
 */
export const TaskFileSchema = z.object({
    /** Monotonic integer ID */
    id: z.number().int().positive(),
    /** Task this file change belongs to */
    taskId: z.number().int().positive(),
    /** Relative POSIX path from workspace root */
    path: z.string().min(1),
    /** Type of file operation */
    action: FileActionSchema,
    /** SHA-256 hash before change (null for added files) */
    hashBefore: z.string().nullable(),
    /** SHA-256 hash after change (null for deleted files) */
    hashAfter: z.string().nullable(),
    /** ISO 8601 timestamp when change was detected */
    timestamp: z.string().datetime(),
});
// =============================================================================
// TASK LEARNING SCHEMA
// =============================================================================
/**
 * LearningCategory - classification of learning for briefing selection
 */
export const LearningCategorySchema = z.enum([
    "pattern", // Reusable code/workflow patterns
    "gotcha", // Anti-patterns and bugs to avoid
    "decision", // Architectural decisions made
    "convention", // Project-specific conventions
    "discovery", // New capabilities/features found
]);
/**
 * LearningConfidence - confidence level for learning insight
 */
export const LearningConfidenceSchema = z.enum(["low", "medium", "high"]);
/**
 * TaskLearning - captured insight attached to a task
 *
 * Deduplicated by content hash and dual-written to:
 * 1. Task-scoped (task_learnings table)
 * 2. Global knowledge store (project-scoped, available to future tasks)
 */
export const TaskLearningSchema = z.object({
    /** Monotonic integer ID */
    id: z.number().int().positive(),
    /** Task this learning belongs to */
    taskId: z.number().int().positive(),
    /** SHA-256 hash of content for deduplication */
    contentHash: z.string().min(1),
    /** The actual learning content */
    content: z.string().min(1),
    /** Where this learning came from */
    source: z.string().nullable(),
    /** Confidence level of the insight */
    confidence: LearningConfidenceSchema,
    /** ISO 8601 timestamp when learning was captured */
    timestamp: z.string().datetime(),
});
// =============================================================================
// TASK SESSION SCHEMA
// =============================================================================
/**
 * TaskSession - record of each daemon connection to a Task
 *
 * Sessions are transient connections that come and go underneath a Task.
 * When a session disconnects, the Task remains in its current state.
 */
export const TaskSessionSchema = z.object({
    /** Monotonic integer ID */
    id: z.number().int().positive(),
    /** Task this session belongs to */
    taskId: z.number().int().positive(),
    /** Unique session identifier (UUID) */
    sessionId: z.string().min(1),
    /** ISO 8601 timestamp when session connected */
    connectedAt: z.string().datetime(),
    /** ISO 8601 timestamp when session disconnected (null if active) */
    disconnectedAt: z.string().datetime().nullable(),
});
// =============================================================================
// CEREMONY SCHEMA (Derived from accumulated state)
// =============================================================================
/**
 * CeremonyMetrics - all derived counters computed from Task accumulated state
 *
 * CRITICAL: These are NEVER stored independently.
 * They are always computed from the accumulated state.
 * This eliminates the ceremony zeros bug by construction.
 */
export const CeremonyMetricsSchema = z.object({
    /** Number of unique files modified */
    filesModified: z.number().int().nonnegative(),
    /** Number of unique files created */
    filesCreated: z.number().int().nonnegative(),
    /** Number of files deleted */
    filesDeleted: z.number().int().nonnegative(),
    /** Number of learnings captured */
    learningsCaptured: z.number().int().nonnegative(),
    /** Number of pulse snapshots recorded */
    pulsesRecorded: z.number().int().nonnegative(),
    /** Number of sessions that connected to this task */
    sessionsCount: z.number().int().nonnegative(),
    /** Total file operations (sum of all actions) */
    totalFileOperations: z.number().int().nonnegative(),
});
/**
 * CeremonyDuration - timing information for the ceremony
 */
export const CeremonyDurationSchema = z.object({
    /** ISO 8601 timestamp of first session start */
    firstSessionStart: z.string().datetime(),
    /** ISO 8601 timestamp of last session end */
    lastSessionEnd: z.string().datetime().nullable(),
    /** Total active time in milliseconds */
    totalActiveTimeMs: z.number().int().nonnegative(),
});
/**
 * QualityGateStatus - results from quality gate checks
 */
export const QualityGateStatusSchema = z.object({
    /** Whether all required gates passed */
    allPassed: z.boolean(),
    /** Whether audit passed */
    auditPassed: z.boolean().nullable(),
    /** Whether lint is clean */
    lintClean: z.boolean().nullable(),
    /** Whether tests pass */
    testsPass: z.boolean().nullable(),
});
/**
 * Ceremony - structured completion report produced from accumulated Task state
 *
 * The ceremony reads from the Task's accumulated state (not session state).
 * This ensures correct metrics regardless of which session triggers vreko_end.
 */
export const CeremonySchema = z.object({
    /** Task ID */
    taskId: z.number().int().positive(),
    /** Human-readable task name */
    taskName: z.string().min(1),
    /** Deterministic slug */
    slug: z.string().min(1),
    /** How the task ended */
    outcome: TaskOutcomeSchema,
    /** Duration information */
    duration: CeremonyDurationSchema,
    /** Derived metrics from accumulated state */
    metrics: CeremonyMetricsSchema,
    /** All learnings captured during this task */
    learnings: z.array(TaskLearningSchema),
    /** Complete file change log */
    fileChanges: z.array(TaskFileSchema),
    /** Quality gate results from most recent pulse */
    qualityGates: QualityGateStatusSchema,
    /** LLM-generated summary for context injection into future tasks */
    briefingForNextTask: z.string().nullable(),
});
// =============================================================================
// BRIEFING SCHEMA
// =============================================================================
/**
 * BriefingMode - level of context to include
 */
export const BriefingModeSchema = z.enum(["standard", "comprehensive"]);
/**
 * Briefing - context injected at Task start
 *
 * Push-based context briefing (under 500 tokens for standard mode).
 * The daemon produces this autonomously, not the LLM.
 */
export const BriefingSchema = z.object({
    /** Summary of most recent completed task's ceremony (1-2 paragraphs) */
    recentCeremonySummary: z.string().nullable(),
    /** Top 5 most recent learnings from across all tasks */
    recentLearnings: z.array(TaskLearningSchema).max(5),
    /** Any active warnings or known issues from the project */
    activeWarnings: z.array(z.string()),
    /** Full ceremony from continued task (if continues parameter provided) */
    continuedCeremony: CeremonySchema.nullable(),
    /** Lineage chain (task IDs this task continues from) */
    lineageChain: z.array(z.number().int().positive()),
});
// =============================================================================
// SLUG GENERATION SCHEMAS
// =============================================================================
/**
 * SlugGenerationInput - input for slug generation
 */
export const SlugGenerationInputSchema = z.object({
    /** Human-readable task name from LLM */
    taskName: z.string().min(1).max(256),
});
/**
 * SlugGenerationOutput - result of slug generation
 */
export const SlugGenerationOutputSchema = z.object({
    /** Generated kebab-case slug */
    slug: z.string().min(1).max(64),
    /** Whether a counter suffix was added for uniqueness */
    hasCounterSuffix: z.boolean(),
    /** Counter value if suffix was added (null otherwise) */
    counterValue: z.number().int().positive().nullable(),
});
// =============================================================================
// MCP TOOL INPUT SCHEMAS
// =============================================================================
/**
 * VrekoInput - input for vreko() MCP tool
 *
 * Description: "Begin or resume a Vreko task. If a task with this name exists
 * and is active, resume it with a new session. If not, create a new task.
 * The previous active task (if any) is auto-ended with a ceremony."
 */
export const VrekoInputSchema = z.object({
    /** Human-readable task name. Vreko generates a deterministic slug for matching. */
    task: z.string().min(1).max(256),
    /** Task ID or slug of a completed task that this new task continues. */
    continues: z.string().optional(),
    /** Level of context to include in the briefing. Default "standard". */
    mode: BriefingModeSchema.default("standard"),
});
/**
 * VrekoOutput - output from vreko() MCP tool
 */
export const VrekoOutputSchema = z.object({
    /** Task ID */
    taskId: z.number().int().positive(),
    /** Deterministic slug */
    slug: z.string().min(1),
    /** Human-readable task name */
    name: z.string().min(1),
    /** Current status */
    status: TaskStatusSchema,
    /** Whether this was a resume of an existing task */
    resumed: z.boolean(),
    /** Slug of auto-ended task (if any) */
    autoEnded: z.string().nullable(),
    /** Contextual briefing from recent work history */
    briefing: BriefingSchema,
    /** Number of sessions that have connected to this task */
    sessionsCount: z.number().int().nonnegative(),
});
// -----------------------------------------------------------------------------
// snap_pulse MCP tool
// -----------------------------------------------------------------------------
/**
 * PulseFocus - what to focus on in the pulse
 */
export const PulseFocusSchema = z.enum(["vitals", "advice"]);
/**
 * PulseEnrichment - LLM-observed context to attach
 */
export const PulseEnrichmentSchema = z.object({
    /** Patterns, concerns the LLM noticed */
    observations: z.array(z.string()).optional(),
    /** Confidence in observations */
    confidence: LearningConfidenceSchema.optional(),
});
/**
 * SnapPulseInput - input for snap_pulse() MCP tool
 *
 * Description: "Check the pulse of the current workspace and active task.
 * Vreko autonomously reads workspace vitals - test status, lint health,
 * git state, file changes - and returns a diagnostic snapshot."
 */
export const SnapPulseInputSchema = z.object({
    /** What to focus on. "vitals" returns workspace health diagnostics.
     * "advice" returns proactive recommendations based on current task context. */
    focus: PulseFocusSchema.default("vitals"),
    /** When focus is "advice", a specific question or area.
     * When focus is "vitals", optional hint about what to prioritize. */
    query: z.string().optional(),
    /** LLM-observed context to attach. Additive, not replacing. */
    enrichment: PulseEnrichmentSchema.optional(),
});
/**
 * WorkspaceVitals - daemon-collected workspace health diagnostics
 */
export const WorkspaceVitalsSchema = z.object({
    /** Whether configured tests pass */
    testsPass: z.boolean().nullable(),
    /** Whether lint is clean */
    lintClean: z.boolean().nullable(),
    /** Whether typecheck passes */
    typecheckPass: z.boolean().nullable(),
    /** Git branch name */
    gitBranch: z.string().nullable(),
    /** Whether there are uncommitted changes */
    hasUncommittedChanges: z.boolean(),
    /** Number of modified files (from git status) */
    modifiedFilesCount: z.number().int().nonnegative(),
    /** Error details if any check failed */
    errorDetails: z.string().nullable(),
});
/**
 * SnapPulseOutput - output from snap_pulse() MCP tool
 */
export const SnapPulseOutputSchema = z.object({
    /** Whether there is an active task */
    hasActiveTask: z.boolean(),
    /** Task ID if active */
    taskId: z.number().int().positive().nullable(),
    /** Daemon-collected workspace vitals */
    vitals: WorkspaceVitalsSchema,
    /** Whether task is flagged as stale (inactivity timeout exceeded) */
    isStale: z.boolean(),
    /** Proactive recommendations (when focus is "advice") */
    recommendations: z.array(z.string()).optional(),
    /** Pulse sequence number for this task */
    pulseSeq: z.number().int().nonnegative(),
});
// -----------------------------------------------------------------------------
// vreko_learn MCP tool
// -----------------------------------------------------------------------------
/**
 * VrekoLearnInput - input for vreko_learn() MCP tool
 *
 * Description: "Capture a learning or insight and attach it to the active task.
 * Learnings are deduplicated by content hash and dual-written to both the Task
 * and the global knowledge store."
 */
export const VrekoLearnInputSchema = z.object({
    /** The learning to capture. Should be a concrete, actionable insight. */
    insight: z.string().min(1),
    /** Classification of the learning. Default: inferred by the daemon. */
    category: LearningCategorySchema.optional(),
    /** Where this learning came from. Default: "llm-observation". */
    source: z.string().optional(),
    /** How confident the LLM is in this insight. Default: "medium". */
    confidence: LearningConfidenceSchema.default("medium"),
});
/**
 * VrekoLearnOutput - output from vreko_learn() MCP tool
 */
export const VrekoLearnOutputSchema = z.object({
    /** Learning ID */
    learningId: z.number().int().positive(),
    /** Content hash for deduplication */
    contentHash: z.string().min(1),
    /** Whether this was a new learning or duplicate */
    isNew: z.boolean(),
    /** Total learnings count for this task */
    taskLearningsCount: z.number().int().nonnegative(),
});
// -----------------------------------------------------------------------------
// vreko_end MCP tool
// -----------------------------------------------------------------------------
/**
 * VrekoEndFeedback - user/LLM feedback on task experience
 */
export const VrekoEndFeedbackSchema = z.object({
    /** Rating 1-5 */
    rating: z.number().int().min(1).max(5),
    /** Optional notes */
    notes: z.string().optional(),
});
/**
 * VrekoEndInput - input for vreko_end() MCP tool
 *
 * Description: "Close the active task with a ceremony. The ceremony reads from
 * the Task's accumulated state - file changes, learnings, pulses, and sessions -
 * to produce a completion report. If quality gates are configured and fail,
 * the ceremony is blocked until issues are resolved or force is used."
 */
export const VrekoEndInputSchema = z.object({
    /** How the task ended */
    outcome: TaskOutcomeSchema,
    /** LLM's summary of what was accomplished. Included in ceremony. */
    summary: z.string().optional(),
    /** Bypass quality gate blocks. Not recommended. */
    force: z.boolean().default(false),
    /** User/LLM feedback on the task experience */
    feedback: VrekoEndFeedbackSchema.optional(),
});
/**
 * VrekoEndOutput - output from vreko_end() MCP tool
 */
export const VrekoEndOutputSchema = z.object({
    /** Whether the ceremony was blocked by quality gates */
    blocked: z.boolean(),
    /** The produced ceremony (null if blocked and force=false) */
    ceremony: CeremonySchema.nullable(),
    /** Quality gate failures if blocked */
    gateFailures: z
        .object({
        testsPass: z.boolean().optional(),
        lintClean: z.boolean().optional(),
        auditPassed: z.boolean().optional(),
    })
        .nullable(),
    /** Instructions to resolve blockage */
    resolution: z.string().nullable(),
});
// =============================================================================
// UTILITY FUNCTIONS
// =============================================================================
/**
 * Generate a deterministic slug from a task name
 *
 * Rules:
 * 1. Transliterate Unicode to ASCII (via latinize)
 * 2. Lowercase all characters
 * 3. Replace spaces and special characters with hyphens
 * 4. Collapse multiple hyphens
 * 5. Strip leading/trailing hyphens
 * 6. Truncate to 64 characters max; if truncation, append 4-char hash
 *
 * @param taskName - Human-readable task name
 * @returns Generated slug
 */
export function generateSlug(taskName) {
    // Basic slug generation (full transliteration would use latinize library)
    let slug = taskName
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-") // Replace non-alphanumeric with hyphens
        .replace(/^-+|-+$/g, "") // Strip leading/trailing hyphens
        .replace(/-{2,}/g, "-"); // Collapse multiple hyphens
    // Truncate to 64 chars, add hash suffix if needed
    if (slug.length > 64) {
        const hashSuffix = simpleHash(taskName).slice(0, 4);
        slug = `${slug.slice(0, 60)}-${hashSuffix}`;
    }
    return slug || "untitled-task";
}
/**
 * Simple hash function for generating uniqueness suffixes
 */
function simpleHash(input) {
    let hash = 0;
    for (let i = 0; i < input.length; i++) {
        const char = input.charCodeAt(i);
        hash = (hash << 5) - hash + char;
        hash = hash & hash; // Convert to 32-bit integer
    }
    return Math.abs(hash).toString(36);
}
/**
 * Check if a task status is terminal (cannot transition further)
 */
export function isTerminalStatus(status) {
    return ["completed", "abandoned", "failed", "auto-ended"].includes(status);
}
/**
 * Check if a task status allows modifications
 */
export function isActiveStatus(status) {
    return ["created", "active", "ceremony_blocked"].includes(status);
}
// Types are automatically exported via z.infer<typeof ...Schema> declarations above.
