/**
 * Risk Domain Spine Events - ADR-007 §3
 *
 * Spine events for risk detection and scoring.
 * Event types use three-part naming: risk.<entity>.<action>
 *
 * @module @vreko/contracts/events/spine/domains/risk
 * @see ADR-007 Runtime Tier Boundaries and Export Spine Contract
 */
import { z } from "zod";
import { createSpineEventSchema } from "../envelope.js";
// =============================================================================
// Shared Risk Schemas
// =============================================================================
/**
 * Risk level enumeration
 */
export const riskLevelSchema = z.enum(["low", "medium", "high", "critical"]);
/**
 * Risk score with bounds
 */
export const riskScoreSchema = z.number().min(0);
// =============================================================================
// risk.signal.fatigue-detected
// =============================================================================
/**
 * Data payload for risk.signal.fatigue-detected event
 */
export const riskSignalFatigueDetectedDataSchema = z.object({
    /** Workspace hash (from envelope, but also referenced in data for clarity) */
    workspaceHash: z.string().regex(/^[0-9a-f]{64}$/i),
    /** Fatigue level assessment */
    level: z.enum(["rested", "normal", "elevated", "fatigued"]),
    /** Risk score boost factor from fatigue */
    riskBoost: z.number().min(0),
    /** Ratio of rapid accepts to total suggestions */
    rapidAcceptRatio: z.number().min(0).max(1),
    /** Time window for fatigue detection in milliseconds */
    windowMs: z.number().int().positive(),
    /** Number of suggestions in detection window */
    suggestionCount: z.number().int().nonnegative(),
    /** Session ID if part of tracked session */
    sessionId: z.string().uuid().optional(),
});
/**
 * Spine event schema for risk.signal.fatigue-detected
 *
 * Emitted when fatigue patterns are detected in user behavior.
 */
export const riskSignalFatigueDetectedSchema = createSpineEventSchema(riskSignalFatigueDetectedDataSchema);
/**
 * Event type constant
 */
export const RISK_SIGNAL_FATIGUE_DETECTED = "risk.signal.fatigue-detected";
// =============================================================================
// risk.signal.fragile-detected
// =============================================================================
/**
 * Data payload for risk.signal.fragile-detected event
 */
export const riskSignalFragileDetectedDataSchema = z.object({
    /** Fragility score 0.0-1.0 */
    fragilityScore: z.number().min(0).max(1),
    /** Severity assessment */
    severity: z.enum(["moderate", "high", "critical"]),
    /** Detection reason code */
    reason: z.enum([
        "rapid-changes", // Too many changes in short time
        "incomplete-pattern", // Pattern detected but incomplete
        "dependency-risk", // Changes to critical dependencies
        "complexity-spike", // Sudden complexity increase
        "unknown-tool", // Attribution to unknown tool
    ]),
    /** Confidence in fragility assessment */
    confidence: z.number().min(0).max(1),
    /** Related snapshot hash if applicable */
    snapshotHash: z
        .string()
        .regex(/^[0-9a-f]{64}$/i)
        .optional(),
});
/**
 * Spine event schema for risk.signal.fragile-detected
 *
 * Emitted when fragile change patterns are detected.
 */
export const riskSignalFragileDetectedSchema = createSpineEventSchema(riskSignalFragileDetectedDataSchema);
/**
 * Event type constant
 */
export const RISK_SIGNAL_FRAGILE_DETECTED = "risk.signal.fragile-detected";
// =============================================================================
// risk.signal.poisoning-detected
// =============================================================================
/**
 * Data payload for risk.signal.poisoning-detected event
 */
export const riskSignalPoisoningDetectedDataSchema = z.object({
    /** Unique fingerprint of poisoning pattern */
    fingerprint: z.string().regex(/^[0-9a-f]{64}$/i),
    /** Number of distinct sessions showing this pattern */
    distinctSessions: z.number().int().positive(),
    /** Tools involved in poisoning pattern */
    toolFingerprints: z.array(z.string().regex(/^[0-9a-f]{64}$/i)).max(10),
    /** Detection confidence */
    confidence: z.number().min(0).max(1),
    /** Pattern category */
    category: z.enum([
        "repeated-error", // Same error pattern across sessions
        "anti-pattern", // Known problematic pattern
        "degraded-quality", // Measurable quality degradation
        "attribution-drift", // Tool attribution inconsistencies
    ]),
});
/**
 * Spine event schema for risk.signal.poisoning-detected
 *
 * Emitted when AI poisoning patterns are detected.
 */
export const riskSignalPoisoningDetectedSchema = createSpineEventSchema(riskSignalPoisoningDetectedDataSchema);
/**
 * Event type constant
 */
export const RISK_SIGNAL_POISONING_DETECTED = "risk.signal.poisoning-detected";
// =============================================================================
// risk.score.updated
// =============================================================================
/**
 * Data payload for risk.score.updated event
 */
export const riskScoreUpdatedDataSchema = z.object({
    /** New risk score */
    score: riskScoreSchema,
    /** New risk level */
    level: riskLevelSchema,
    /** Previous score */
    previousScore: riskScoreSchema,
    /** Previous level */
    previousLevel: riskLevelSchema,
    /** Contributing factors to score change */
    factors: z
        .array(z.object({
        name: z.string().min(1).max(100),
        impact: z.enum(["positive", "negative", "neutral"]),
        weight: z.number().min(0).max(1),
    }))
        .max(10),
    /** Risk change trigger */
    trigger: z.enum([
        "snapshot-created",
        "snapshot-restored",
        "session-changed",
        "manual-adjustment",
        "auto-recalculation",
    ]),
});
/**
 * Spine event schema for risk.score.updated
 *
 * Emitted when overall risk score is recalculated.
 */
export const riskScoreUpdatedSchema = createSpineEventSchema(riskScoreUpdatedDataSchema);
/**
 * Event type constant
 */
export const RISK_SCORE_UPDATED = "risk.score.updated";
/**
 * All risk event type constants
 */
export const RISK_EVENT_TYPES = [
    RISK_SIGNAL_FATIGUE_DETECTED,
    RISK_SIGNAL_FRAGILE_DETECTED,
    RISK_SIGNAL_POISONING_DETECTED,
    RISK_SCORE_UPDATED,
];
/**
 * Map of event types to their schemas for validation
 */
export const RISK_EVENT_SCHEMAS = {
    [RISK_SIGNAL_FATIGUE_DETECTED]: riskSignalFatigueDetectedSchema,
    [RISK_SIGNAL_FRAGILE_DETECTED]: riskSignalFragileDetectedSchema,
    [RISK_SIGNAL_POISONING_DETECTED]: riskSignalPoisoningDetectedSchema,
    [RISK_SCORE_UPDATED]: riskScoreUpdatedSchema,
};
