// ESM imports fixed for Node.js v22+
/**
 * ExecutionPipeline - 12-Step Tool Execution Engine
 *
 * Orchestrates tool invocations through a series of security, validation,
 * and execution steps. Emits CloudEvents at key lifecycle points for
 * observability and audit logging.
 *
 * Pipeline Steps:
 * 1. VALIDATE - Schema validation of invocation envelope
 * 2. AUTHENTICATE - Identity verification
 * 3. AUTHORIZE - Permission and entitlement checks (PDP/PEP)
 * 4. RATE_LIMIT - Rate limiting and quota checks
 * 5. PRE_SCAN - Security pre-scanning (secrets, threats)
 * 6. LEASE - File lease acquisition (multi-agent safety)
 * 7. SNAPSHOT - Pre-execution snapshot (if configured)
 * 8. EXECUTE - Tool execution
 * 9. POST_SCAN - Output validation and sanitization
 * 10. EGRESS - Privacy attestation and data filtering
 * 11. AUDIT - Audit log creation
 * 12. FINALIZE - Cleanup and lease release
 *
 * @module primitives/execution-pipeline
 */
import { z } from "zod";
import { createToolInvocationEvent, VrekoEventTypes } from "./cloud-event.js";
import { ExecutionResultSchema, extractInvocationIds, } from "./tool-invocation.js";
/**
 * Pipeline step names in execution order
 */
export const PIPELINE_STEPS = [
    "validate",
    "authenticate",
    "authorize",
    "rate_limit",
    "pre_scan",
    "lease",
    "snapshot",
    "execute",
    "post_scan",
    "egress",
    "audit",
    "finalize",
];
/**
 * Default step handlers (placeholder implementations)
 * Real implementations would be injected via dependencies
 */
const defaultStepHandlers = {
    validate: async (invocation, _context) => {
        // Validate invocation structure (already validated by Zod on creation)
        const ids = extractInvocationIds(invocation);
        return {
            passed: true,
            data: { validated: true, ids },
        };
    },
    authenticate: async (invocation, _context) => {
        // Check if identity is present
        const hasIdentity = invocation.identity.userId || invocation.identity.anonymousId;
        if (!hasIdentity) {
            return {
                passed: false,
                error: {
                    code: "AUTH_REQUIRED",
                    message: "Authentication required: no userId or anonymousId provided",
                },
            };
        }
        return { passed: true, data: { authenticated: true } };
    },
    authorize: async (invocation, context) => {
        // Use injected policy evaluator if available
        if (context.dependencies?.evaluatePolicyFn) {
            const decision = await context.dependencies.evaluatePolicyFn(invocation);
            if (!decision.allowed) {
                return {
                    passed: false,
                    error: {
                        code: "POLICY_DENIED",
                        message: decision.reason || "Policy evaluation denied access",
                    },
                };
            }
        }
        // Default: check tier against tool requirements
        const requiredTier = invocation.tool.minTier;
        const userTier = invocation.identity.tier;
        const tierOrder = ["free", "pro", "team", "enterprise"];
        if (requiredTier) {
            const userTierIndex = tierOrder.indexOf(userTier);
            const requiredTierIndex = tierOrder.indexOf(requiredTier);
            if (userTierIndex < requiredTierIndex) {
                return {
                    passed: false,
                    error: {
                        code: "TIER_REQUIRED",
                        message: `Tool requires ${requiredTier} tier, user has ${userTier}`,
                    },
                };
            }
        }
        return { passed: true, data: { authorized: true } };
    },
    rate_limit: async (invocation, context) => {
        if (context.dependencies?.checkRateLimitFn) {
            const key = `${invocation.session.workspaceId}:${invocation.tool.urn}`;
            const result = await context.dependencies.checkRateLimitFn(key, 100, 60000);
            if (!result.allowed) {
                return {
                    passed: false,
                    error: {
                        code: "RATE_LIMITED",
                        message: `Rate limit exceeded. Resets in ${result.resetMs}ms`,
                        details: { remaining: result.remaining, resetMs: result.resetMs },
                    },
                };
            }
            return { passed: true, data: { remaining: result.remaining } };
        }
        return { passed: true, data: { skipped: true } };
    },
    pre_scan: async (invocation, context) => {
        if (context.dependencies?.preScanFn) {
            const result = await context.dependencies.preScanFn(invocation.args);
            if (!result.passed) {
                return {
                    passed: false,
                    error: {
                        code: "PRE_SCAN_FAILED",
                        message: "Security pre-scan detected threats",
                        details: { threats: result.threats },
                    },
                };
            }
            return { passed: true, data: { scanned: true, threats: [] } };
        }
        return { passed: true, data: { skipped: true } };
    },
    lease: async (invocation, context) => {
        // Only acquire lease if files are being modified
        const files = invocation.args.files;
        if (!files?.length || !context.dependencies?.acquireLeaseFn) {
            return { passed: true, data: { skipped: true, leaseId: null } };
        }
        const result = await context.dependencies.acquireLeaseFn(invocation.session.workspaceId, files, invocation.context.timeoutMs);
        if (!result.acquired) {
            return {
                passed: false,
                error: {
                    code: "LEASE_CONFLICT",
                    message: "Failed to acquire file lease - files may be locked by another agent",
                    details: { files },
                },
            };
        }
        return { passed: true, data: { leaseId: result.leaseId } };
    },
    snapshot: async (invocation, context) => {
        if (!invocation.context.snapshotBefore || !context.dependencies?.createSnapshotFn) {
            return { passed: true, data: { skipped: true, snapshotId: undefined } };
        }
        try {
            const snapshotId = await context.dependencies.createSnapshotFn(invocation.session.workspaceId, `Pre-execution snapshot for ${invocation.tool.urn}`);
            return { passed: true, data: { snapshotId } };
        }
        catch (error) {
            // Snapshot failure is non-critical
            return {
                passed: true,
                data: { snapshotId: undefined, error: String(error) },
            };
        }
    },
    execute: async (invocation, context) => {
        if (!context.dependencies?.executeToolFn) {
            return {
                passed: false,
                error: {
                    code: "NO_EXECUTOR",
                    message: "No tool executor configured",
                },
            };
        }
        try {
            const result = await context.dependencies.executeToolFn(invocation.tool.urn, invocation.args);
            return { passed: true, data: { result } };
        }
        catch (error) {
            return {
                passed: false,
                error: {
                    code: "EXECUTION_FAILED",
                    message: error instanceof Error ? error.message : String(error),
                    details: { error },
                },
            };
        }
    },
    post_scan: async (_invocation, context) => {
        const executeData = context.stepData.get("execute");
        if (!executeData?.result || !context.dependencies?.postScanFn) {
            return { passed: true, data: { skipped: true } };
        }
        const scanResult = await context.dependencies.postScanFn(executeData.result);
        if (!scanResult.passed) {
            return {
                passed: false,
                error: {
                    code: "POST_SCAN_FAILED",
                    message: "Output validation failed",
                },
            };
        }
        // Update execute data with sanitized result
        context.stepData.set("execute", { result: scanResult.sanitized });
        return { passed: true, data: { sanitized: true } };
    },
    egress: async (_invocation, _context) => {
        // Placeholder for privacy attestation and data filtering
        // Will be implemented in Phase 4
        return { passed: true, data: { attested: true } };
    },
    audit: async (invocation, context) => {
        if (!context.dependencies?.createAuditLogFn) {
            return { passed: true, data: { skipped: true, auditId: undefined } };
        }
        try {
            const executeData = context.stepData.get("execute");
            const auditId = await context.dependencies.createAuditLogFn(invocation, executeData?.result);
            return { passed: true, data: { auditId } };
        }
        catch (error) {
            // Audit failure is logged but non-critical
            return {
                passed: true,
                data: { auditId: undefined, error: String(error) },
            };
        }
    },
    finalize: async (_invocation, context) => {
        // Release any acquired leases
        const leaseData = context.stepData.get("lease");
        if (leaseData?.leaseId && context.dependencies?.releaseLeaseFn) {
            try {
                await context.dependencies.releaseLeaseFn(leaseData.leaseId);
            }
            catch (_error) {
                // Lease release failure is logged but non-critical
            }
        }
        return { passed: true, data: { finalized: true } };
    },
};
/**
 * Critical steps that must pass for pipeline to continue
 */
const CRITICAL_STEPS = new Set([
    "validate",
    "authenticate",
    "authorize",
    "rate_limit",
    "pre_scan",
    "lease",
    "execute",
]);
/**
 * ExecutionPipeline - Main pipeline orchestrator
 *
 * Executes tool invocations through a 12-step security and execution pipeline,
 * emitting CloudEvents at key lifecycle points.
 */
export class ExecutionPipeline {
    config;
    stepHandlers;
    constructor(config = {}) {
        this.config = {
            skipSteps: config.skipSteps ?? [],
            stepHandlers: config.stepHandlers ?? {},
            timeoutMs: config.timeoutMs ?? 60000,
            continueOnNonCriticalFailure: config.continueOnNonCriticalFailure ?? true,
            eventEmitter: config.eventEmitter ?? undefined,
        };
        // Merge custom handlers with defaults
        this.stepHandlers = {
            ...defaultStepHandlers,
            ...config.stepHandlers,
        };
    }
    /**
     * Execute a tool invocation through the pipeline
     */
    async execute(invocation, dependencies) {
        const startTime = performance.now();
        const context = {
            startTime,
            stepResults: new Map(),
            stepData: new Map(),
            eventEmitter: this.config.eventEmitter,
            dependencies,
        };
        // Emit invocation started event
        await this.emitEvent(VrekoEventTypes.TOOL_INVOCATION_STARTED, invocation, {
            urn: invocation.tool.urn,
            riskClass: invocation.tool.riskClass,
            channel: invocation.session.channel,
        });
        const steps = [];
        let currentInvocation = invocation;
        let pipelinePassed = true;
        let failedStep;
        let failureError;
        // Execute each step
        for (const stepName of PIPELINE_STEPS) {
            // Skip if configured to skip
            if (this.config.skipSteps.includes(stepName)) {
                steps.push({
                    step: stepName,
                    passed: true,
                    durationMs: 0,
                    data: { skipped: true },
                });
                continue;
            }
            const stepStart = performance.now();
            const handler = this.stepHandlers[stepName];
            try {
                const result = await handler(currentInvocation, context);
                const stepDuration = performance.now() - stepStart;
                const stepResult = {
                    step: stepName,
                    passed: result.passed,
                    durationMs: stepDuration,
                    error: result.error,
                    data: result.data,
                };
                steps.push(stepResult);
                context.stepResults.set(stepName, stepResult);
                if (result.data) {
                    context.stepData.set(stepName, result.data);
                }
                if (result.modifiedInvocation) {
                    currentInvocation = result.modifiedInvocation;
                }
                if (!result.passed) {
                    const isCritical = CRITICAL_STEPS.has(stepName);
                    if (isCritical || !this.config.continueOnNonCriticalFailure) {
                        pipelinePassed = false;
                        failedStep = stepName;
                        failureError = result.error;
                        // Emit appropriate failure event
                        if (stepName === "authorize" || stepName === "rate_limit") {
                            await this.emitEvent(VrekoEventTypes.TOOL_INVOCATION_DENIED, invocation, {
                                reason: result.error?.code ?? "DENIED",
                                step: stepName,
                                policyDecision: result.error,
                            });
                        }
                        else {
                            await this.emitEvent(VrekoEventTypes.TOOL_INVOCATION_FAILED, invocation, {
                                step: stepName,
                                error: result.error,
                            });
                        }
                        break;
                    }
                }
            }
            catch (error) {
                const stepDuration = performance.now() - stepStart;
                const errorObj = {
                    code: "STEP_ERROR",
                    message: error instanceof Error ? error.message : String(error),
                    details: { error },
                };
                steps.push({
                    step: stepName,
                    passed: false,
                    durationMs: stepDuration,
                    error: errorObj,
                });
                if (CRITICAL_STEPS.has(stepName)) {
                    pipelinePassed = false;
                    failedStep = stepName;
                    failureError = errorObj;
                    await this.emitEvent(VrekoEventTypes.TOOL_INVOCATION_FAILED, invocation, {
                        step: stepName,
                        error: errorObj,
                    });
                    break;
                }
            }
        }
        const totalDuration = performance.now() - startTime;
        // Build execution result
        const executeData = context.stepData.get("execute");
        const snapshotData = context.stepData.get("snapshot");
        const auditData = context.stepData.get("audit");
        const executionResult = {
            traceId: invocation.traceId,
            success: pipelinePassed,
            result: pipelinePassed ? executeData?.result : undefined,
            error: pipelinePassed
                ? undefined
                : {
                    code: failureError?.code ?? "PIPELINE_FAILED",
                    message: failureError?.message ?? "Pipeline execution failed",
                    step: failedStep,
                    details: failureError?.details,
                },
            steps,
            durationMs: totalDuration,
            snapshotId: snapshotData?.snapshotId,
            auditId: auditData?.auditId,
        };
        // Emit completion event
        if (pipelinePassed) {
            await this.emitEvent(VrekoEventTypes.TOOL_INVOCATION_COMPLETED, invocation, {
                durationMs: totalDuration,
                result: executeData?.result,
            });
        }
        return ExecutionResultSchema.parse(executionResult);
    }
    /**
     * Emit a CloudEvent
     */
    async emitEvent(type, invocation, data) {
        if (!this.config.eventEmitter) {
            return;
        }
        const event = createToolInvocationEvent({
            traceId: invocation.traceId,
            source: "vreko:execution-pipeline",
            type: type,
            toolUrn: invocation.tool.urn,
            workspaceId: invocation.session.workspaceId,
            sessionId: invocation.session.sessionId,
            userId: invocation.identity.userId,
            riskClass: invocation.tool.riskClass,
            sandboxed: invocation.context.sandboxLevel !== "none",
            data,
        });
        await this.config.eventEmitter.emit(event);
    }
}
/**
 * Create a new ExecutionPipeline instance
 */
export function createExecutionPipeline(config) {
    return new ExecutionPipeline(config);
}
/**
 * Schema for pipeline configuration (for API validation)
 */
export const PipelineConfigSchema = z.object({
    skipSteps: z.array(z.enum(PIPELINE_STEPS)).optional(),
    timeoutMs: z.number().positive().optional(),
    continueOnNonCriticalFailure: z.boolean().optional(),
});
