/**
 * Flywheel Queue Job Contracts
 *
 * Defines job data types for BullMQ workers processing:
 * - Session reflection (LLM-based)
 * - Outcome labeling (user feedback)
 *
 * @module flywheel/queue
 */
import { z } from "zod";
// =============================================================================
// REFLECTION JOB
// =============================================================================
/**
 * Zod schema for reflection job data
 */
export const ReflectionJobDataSchema = z.object({
    /** Internal ingest record ID */
    ingestId: z.string().uuid(),
    /** User ID (for scope resolution) */
    userId: z.string(),
    /** Organization ID (null for personal sessions) */
    organizationId: z.string().uuid().nullable(),
    /** Session payload (JSONB content) */
    payload: z.record(z.unknown()),
    /** Feature flag state for this session */
    enabledFeatures: z.array(z.string()),
    /** Tier-based limits */
    maxReflectionTokens: z.number().int().positive(),
});
// =============================================================================
// OUTCOME LABELING JOB
// =============================================================================
/**
 * Zod schema for outcome labeling job data
 */
export const OutcomeLabelJobDataSchema = z.object({
    /** Internal ingest record ID */
    ingestId: z.string().uuid(),
    /** User ID */
    userId: z.string(),
    /** Organization ID */
    organizationId: z.string().uuid().nullable(),
    /** Session payload (for pattern analysis) */
    payload: z.record(z.unknown()),
    /** User's outcome assessment (optional - can be computed) */
    userOutcome: z
        .object({
        /** Was the session successful? */
        success: z.boolean(),
        /** User's description of outcome */
        description: z.string().max(500).optional(),
    })
        .optional(),
});
// =============================================================================
// QUEUE NAMES
// =============================================================================
/**
 * BullMQ queue names for flywheel jobs
 */
export const FLYWHEEL_QUEUE_NAMES = {
    /** Queue for LLM-based session reflection */
    REFLECTION: "flywheel-reflection",
    /** Queue for outcome labeling and pattern analysis */
    OUTCOME: "flywheel-outcome",
};
// =============================================================================
// JOB OPTIONS
// =============================================================================
/**
 * Default job options for flywheel queues
 */
export const FLYWHEEL_JOB_OPTIONS = {
    /** Reflection jobs: retry 3 times, 30s delay, 5 minute timeout */
    REFLECTION: {
        attempts: 3,
        backoff: {
            type: "exponential",
            delay: 30000,
        },
        removeOnComplete: { count: 100 },
        removeOnFail: { count: 50 },
    },
    /** Outcome jobs: retry 2 times, 10s delay, 1 minute timeout */
    OUTCOME: {
        attempts: 2,
        backoff: {
            type: "fixed",
            delay: 10000,
        },
        removeOnComplete: { count: 200 },
        removeOnFail: { count: 100 },
    },
};
