/**
 * Attribution API Contract (Gap 4 - High Priority)
 *
 * Defines the API contract for marketing attribution transfer from web to platform.
 * Enables tracking of user acquisition sources (UTM params, referral codes) across
 * the authentication boundary.
 *
 * @module attribution-api
 */
/**
 * Helper: Generate device fingerprint
 * Uses combination of user agent, screen resolution, and timezone
 */
export function generateFingerprint(data) {
    const raw = `${data.userAgent}_${data.screenWidth}x${data.screenHeight}_${data.timezone}`;
    // Simple hash (in production, use crypto.subtle.digest)
    let hash = 0;
    for (let i = 0; i < raw.length; i++) {
        const char = raw.charCodeAt(i);
        hash = (hash << 5) - hash + char;
        hash = hash & hash; // Convert to 32bit integer
    }
    return `fp_${Math.abs(hash).toString(36)}`;
}
/**
 * Helper: Parse attribution source from URL
 */
export function parseAttributionSource(url) {
    const urlObj = new URL(url);
    const utmSource = urlObj.searchParams.get("utm_source")?.toLowerCase();
    if (!utmSource) {
        return "direct";
    }
    if (utmSource.includes("facebook") || utmSource.includes("fb")) {
        return "facebook";
    }
    if (utmSource.includes("google")) {
        return "google";
    }
    if (utmSource.includes("twitter") || utmSource.includes("x.com")) {
        return "twitter";
    }
    if (utmSource.includes("linkedin")) {
        return "linkedin";
    }
    if (utmSource.includes("reddit")) {
        return "reddit";
    }
    // Check if it's a referral
    const ref = urlObj.searchParams.get("ref");
    if (ref) {
        return "referral";
    }
    return "organic";
}
/**
 * Helper: Extract UTM parameters from URL
 */
export function extractUtmParams(url) {
    const urlObj = new URL(url);
    return {
        utm_source: urlObj.searchParams.get("utm_source") || undefined,
        utm_medium: urlObj.searchParams.get("utm_medium") || undefined,
        utm_campaign: urlObj.searchParams.get("utm_campaign") || undefined,
        utm_content: urlObj.searchParams.get("utm_content") || undefined,
        utm_term: urlObj.searchParams.get("utm_term") || undefined,
    };
}
/**
 * Helper: Check if attribution should be merged or ignored
 * Returns true if attributions are from the same campaign/source
 */
export function shouldMergeAttribution(existing, incoming) {
    // Same source and campaign = merge
    if (existing.source === incoming.source && existing.campaignId === incoming.campaignId) {
        return true;
    }
    return false;
}
