/**
 * Shared contracts for both Pioneer entry points.
 *
 * Two legitimately distinct flows, ONE schema module so marketing capture and
 * authenticated redemption can never drift in field names or validation rules:
 *
 *   1. Waitlist / email capture  - unauthenticated, homepage (vreko.dev)
 *   2. Invite redemption         - authenticated, console.vreko.dev/pioneer?code=
 */
import { z } from "zod";
// ---------------------------------------------------------------------------
// Option vocabularies (single source - UI dropdowns and server validation
// both import these, so the form can never offer a value the server rejects)
// ---------------------------------------------------------------------------
export const IDE_VALUES = ["vscode", "cursor", "windsurf", "qoder", "jetbrains", "neovim", "other"];
export const AI_TOOL_VALUES = [
    "github-copilot",
    "cursor-ai",
    "claude-code",
    "claude-chat",
    "chatgpt",
    "codeium",
    "amazon-q",
    "gemini",
    "morph",
    "other",
];
export const IDE_OPTIONS = [
    { value: "vscode", label: "VS Code" },
    { value: "cursor", label: "Cursor" },
    { value: "windsurf", label: "Windsurf" },
    { value: "qoder", label: "Qoder" },
    { value: "jetbrains", label: "JetBrains (IntelliJ, WebStorm, etc.)" },
    { value: "neovim", label: "Neovim" },
    { value: "other", label: "Other" },
];
export const AI_TOOL_OPTIONS = [
    { value: "github-copilot", label: "GitHub Copilot" },
    { value: "cursor-ai", label: "Cursor AI" },
    { value: "claude-code", label: "Claude Code" },
    { value: "claude-chat", label: "Claude (chat)" },
    { value: "chatgpt", label: "ChatGPT" },
    { value: "codeium", label: "Codeium / Windsurf AI" },
    { value: "amazon-q", label: "Amazon Q" },
    { value: "gemini", label: "Gemini Code Assist" },
    { value: "morph", label: "Morph" },
    { value: "other", label: "Other" },
];
// ---------------------------------------------------------------------------
// Flow 1: Waitlist / email capture (unauthenticated)
// ---------------------------------------------------------------------------
export const waitlistCaptureSchema = z.object({
    email: z
        .string()
        .email()
        .max(254)
        .transform((e) => e.toLowerCase().trim()),
    // Optional enrichment branches downstream sequences without gating the capture.
    intent: z.enum(["solo", "team"]).optional(),
    referralCode: z.string().max(64).optional(),
    // Turnstile token is OPTIONAL at the schema level. Whether it is REQUIRED is
    // decided at runtime by whether a server secret is configured (see route).
    turnstileToken: z.string().optional(),
});
// ---------------------------------------------------------------------------
// Flow 2: Invite redemption (authenticated)
// ---------------------------------------------------------------------------
const codeRegex = /^[23456789A-HJ-NP-Z]{8}$/;
export const redeemSchema = z.object({
    code: z.string().regex(codeRegex, "invalid_format"),
    primaryIde: z.enum(IDE_VALUES),
    aiTools: z.array(z.enum(AI_TOOL_VALUES)).min(1).max(AI_TOOL_VALUES.length),
});
export function isValidCodeFormat(code) {
    return codeRegex.test(code);
}
