import { z } from "zod";
import { RiskLevelSchema } from "./risk.js";
// =============================================================================
// SESSION STATE CONTRACTS (Phase 1  -  Contracts Compliance)
// =============================================================================
/**
 * Lifecycle state of a Vreko session.
 *
 * Note: The local-service/schemas/primitives.ts SessionState has only 3 values
 * (active | idle | ended). This extended version adds "paused" for surfaces that
 * support explicit session pause (e.g. MCP server pause/resume).
 */
export const SessionStateSchema = z.enum(["active", "ended", "idle", "paused"]);
/**
 * Health snapshot of an active session.
 *
 * Surfaced to MCP tools (snap_pulse) and the dashboard to communicate the
 * current session's risk posture and recommendations without exposing raw
 * file content.
 *
 * Field notes:
 * - recommendations: action prompts for the developer (never suggestions  -  that
 *   name was a v0 mistake caught by the compliance suite).
 * - riskLevel: current peak risk observed in the session.
 */
export const SessionHealthSchema = z.object({
    sessionId: z.string(),
    state: SessionStateSchema,
    workspaceId: z.string(),
    startedAt: z.date(),
    recommendations: z.array(z.string()),
    riskLevel: RiskLevelSchema,
});
