/**
 * Canonical Sensitive File Patterns
 *
 * Single source of truth for sensitive-file detection across all Vreko packages.
 * Previously split across:
 *   - packages/engine/src/signals/risk-score.ts  (RegExp[])
 *   - packages/mcp/src/facades/handlers/snapshot-handlers.ts (string[], inline)
 *
 * Consumers: @vreko/engine, @vreko/mcp
 */
/**
 * Patterns that indicate a file is sensitive or security-critical.
 * Matched case-insensitively against the full file path.
 */
export const SENSITIVE_PATTERNS = [
    // Environment / secrets
    /\.env$/i,
    /\.pem$/i,
    /\.key$/i,
    /secret/i,
    /password/i,
    /credential/i,
    /private/i,
    // Auth / access control
    /auth/i,
    // Configuration files
    /config\.json$/i,
    /package\.json$/i,
    // Financial / business-critical (from MCP)
    /payment/i,
    // Infrastructure / data (from MCP)
    /security/i,
    /database/i,
];
