/**
 * Session Domain Spine Events - ADR-007 §3
 *
 * Spine events for session lifecycle and coherence tracking.
 * Event types use three-part naming: session.<entity>.<action>
 *
 * @module @vreko/contracts/events/spine/domains/session
 * @see ADR-007 Runtime Tier Boundaries and Export Spine Contract
 */
import { z } from "zod";
import { createSpineEventSchema } from "../envelope.js";
// =============================================================================
// Shared Session Schemas
// =============================================================================
/**
 * Session coherence assessment levels
 */
export const coherenceAssessmentSchema = z.enum([
    "focused", // Single task, clear intent
    "moderate", // Related tasks, some context switching
    "scattered", // Unrelated tasks, frequent switching
    "chaotic", // No clear focus, high fragmentation
]);
/**
 * Session outcome categories
 */
export const sessionOutcomeSchema = z.enum([
    "completed", // Task successfully completed
    "interrupted", // External interruption
    "abandoned", // User abandoned session
    "timeout", // Session timed out
    "rolled-back", // Changes were rolled back
]);
// =============================================================================
// session.lifecycle.started
// =============================================================================
/**
 * Data payload for session.lifecycle.started event
 */
export const sessionLifecycleStartedDataSchema = z.object({
    /** Session identifier */
    sessionId: z.string().uuid(),
    /** Task description provided by user or inferred */
    task: z.string().min(1).max(500),
    /** Session start timestamp */
    startedAt: z.number().int().positive(),
    /** Initial coherence score */
    initialCoherence: z.number().min(0).max(1).optional(),
    /** Client that initiated the session */
    clientType: z.enum(["vscode", "jetbrains", "cli", "mcp", "unknown"]),
});
/**
 * Spine event schema for session.lifecycle.started
 *
 * Emitted when a new session begins.
 */
export const sessionLifecycleStartedSchema = createSpineEventSchema(sessionLifecycleStartedDataSchema);
/**
 * Event type constant
 */
export const SESSION_LIFECYCLE_STARTED = "session.lifecycle.started";
// =============================================================================
// session.lifecycle.ended
// =============================================================================
/**
 * Data payload for session.lifecycle.ended event
 */
export const sessionLifecycleEndedDataSchema = z.object({
    /** Session identifier */
    sessionId: z.string().uuid(),
    /** Session end timestamp */
    endedAt: z.number().int().positive(),
    /** Duration in milliseconds */
    durationMs: z.number().int().nonnegative(),
    /** Session outcome */
    outcome: sessionOutcomeSchema,
    /** Final coherence score */
    finalCoherence: z.number().min(0).max(1),
    /** Number of snapshots created during session */
    snapshotCount: z.number().int().nonnegative(),
    /** Number of rollbacks performed */
    rollbackCount: z.number().int().nonnegative(),
});
/**
 * Spine event schema for session.lifecycle.ended
 *
 * Emitted when a session ends.
 */
export const sessionLifecycleEndedSchema = createSpineEventSchema(sessionLifecycleEndedDataSchema);
/**
 * Event type constant
 */
export const SESSION_LIFECYCLE_ENDED = "session.lifecycle.ended";
// =============================================================================
// session.coherence.updated
// =============================================================================
/**
 * Data payload for session.coherence.updated event
 */
export const sessionCoherenceUpdatedDataSchema = z.object({
    /** Session identifier */
    sessionId: z.string().uuid(),
    /** Updated coherence score 0.0-1.0 */
    score: z.number().min(0).max(1),
    /** Assessment category */
    assessment: coherenceAssessmentSchema,
    /** Number of detected context clusters */
    clusterCount: z.number().int().nonnegative(),
    /** Time since session start in milliseconds */
    elapsedMs: z.number().int().nonnegative(),
});
/**
 * Spine event schema for session.coherence.updated
 *
 * Emitted when session coherence is recalculated.
 */
export const sessionCoherenceUpdatedSchema = createSpineEventSchema(sessionCoherenceUpdatedDataSchema);
/**
 * Event type constant
 */
export const SESSION_COHERENCE_UPDATED = "session.coherence.updated";
// =============================================================================
// session.checkpoint.created
// =============================================================================
/**
 * Data payload for session.checkpoint.created event
 */
export const sessionCheckpointCreatedDataSchema = z.object({
    /** Session identifier */
    sessionId: z.string().uuid(),
    /** Checkpoint identifier */
    checkpointId: z.string().uuid(),
    /** Description of checkpoint state */
    description: z.string().min(1).max(500),
    /** Coherence score at checkpoint time */
    coherenceAtCheckpoint: z.number().min(0).max(1),
    /** Number of changes since session start */
    changeCount: z.number().int().nonnegative(),
});
/**
 * Spine event schema for session.checkpoint.created
 *
 * Emitted when a session checkpoint is created.
 */
export const sessionCheckpointCreatedSchema = createSpineEventSchema(sessionCheckpointCreatedDataSchema);
/**
 * Event type constant
 */
export const SESSION_CHECKPOINT_CREATED = "session.checkpoint.created";
/**
 * All session event type constants
 */
export const SESSION_EVENT_TYPES = [
    SESSION_LIFECYCLE_STARTED,
    SESSION_LIFECYCLE_ENDED,
    SESSION_COHERENCE_UPDATED,
    SESSION_CHECKPOINT_CREATED,
];
/**
 * Map of event types to their schemas for validation
 */
export const SESSION_EVENT_SCHEMAS = {
    [SESSION_LIFECYCLE_STARTED]: sessionLifecycleStartedSchema,
    [SESSION_LIFECYCLE_ENDED]: sessionLifecycleEndedSchema,
    [SESSION_COHERENCE_UPDATED]: sessionCoherenceUpdatedSchema,
    [SESSION_CHECKPOINT_CREATED]: sessionCheckpointCreatedSchema,
};
