import { z } from "zod";
/**
 * Purchase types for billing and subscription management
 *
 * These represent the contract interface for purchases across the application.
 * For database operations, use the Drizzle schema types from @vreko/platform.
 */
export const PurchaseTypeEnum = z.enum(["ONE_TIME", "SUBSCRIPTION", "addon"]);
export const PurchaseSchema = z.object({
    id: z.string(),
    organizationId: z.string().nullable().optional(),
    userId: z.string().nullable().optional(),
    type: PurchaseTypeEnum,
    customerId: z.string(),
    subscriptionId: z.string().nullable().optional(),
    productId: z.string(),
    status: z.string().nullable().optional(),
    createdAt: z.date(),
    updatedAt: z.date().nullable().optional(),
});
