import { z } from "zod";
/**
 * Dashboard Data Contracts
 *
 * Type definitions for the unified dashboard page.
 * This is the contract between the dashboard API procedure and the web UI.
 */
/**
 * Snapshot for the sessions view
 */
export const DashboardSnapshotSchema = z.object({
    id: z.string(),
    file: z.string(),
    message: z.string(),
    time: z.string(),
    risk: z.enum(["Low", "Medium", "High", "Critical"]),
    ai: z.string(),
});
/**
 * Learning velocity data point
 */
export const LearningDataSchema = z.object({
    day: z.string(),
    learned: z.number(),
});
/**
 * AI attribution data point
 */
export const AttributionDataSchema = z.object({
    name: z.string(),
    value: z.number(),
    color: z.string(),
});
/**
 * Complete dashboard data response
 */
export const DashboardDataSchema = z.object({
    // Pulse view
    trustScore: z.number().min(0).max(100),
    patternsCaught: z.number().int().nonnegative(),
    activeSessions: z.number().int().nonnegative(),
    // User context
    userName: z.string(),
    userInitials: z.string(),
    tier: z.string(),
    // Sessions view
    snapshots: z.array(DashboardSnapshotSchema),
    // Intelligence view
    learningVelocity: z.array(LearningDataSchema),
    aiAttribution: z.array(AttributionDataSchema),
    totalLearned: z.number().int().nonnegative(),
    growthPercentage: z.number().int().nonnegative(),
});
/**
 * Dashboard data error response
 */
export const DashboardDataErrorSchema = z.object({
    error: z.literal(true),
    code: z.enum(["UNAUTHORIZED", "NOT_FOUND", "INTERNAL_ERROR"]),
    message: z.string(),
});
/**
 * Dashboard data API response (success | error)
 */
export const DashboardDataResponseSchema = z.union([DashboardDataSchema, DashboardDataErrorSchema]);
/**
 * Type guards
 */
export function isDashboardDataSuccess(response) {
    return !("error" in response) || response.error !== true;
}
export function isDashboardDataError(response) {
    return "error" in response && response.error === true;
}
