// =============================================================================
// MOCK GENERATOR - For testing different states
// =============================================================================
export function generateMockDashboard(overrides) {
    return {
        ...MOCK_PIONEER_DASHBOARD,
        ...overrides,
        computedAt: Date.now(),
    };
}
export function generateEmptyDashboard() {
    return {
        version: 1,
        computedAt: Date.now(),
        user: {
            name: null,
            email: "new@vreko.dev",
        },
        sessionMetrics: {
            activeSessionCount: 0,
            lastActivityTime: new Date().toISOString(),
        },
        protection: {
            score: 0,
            risksPrevented: 0,
            context: "Start coding to see your protection score",
            weekLabel: "this week",
        },
        timeline: [],
        heatmap: [],
        ai: { cursor: 0, copilot: 0, claude: 0 },
        weekly: DAYS_OF_WEEK.map((day) => ({ day, ai: 0, human: 0, prevented: 0 })),
        velocity: [{ week: "W1", learnings: 0, accuracy: 0 }],
        pioneer: {
            tier: "Pioneer",
            tierIndex: 0,
            impact: "Your journey is just beginning",
        },
        insights: {
            sessionsThisWeek: 0,
            avgSessionMinutes: 0,
            coherencePercent: 0,
            preventedToRecoveredRatio: "0 : 0",
            fragileFileCount: 0,
            fragileHotspots: "No hotspots detected yet",
        },
    };
}
export function generateLowActivityDashboard() {
    return generateMockDashboard({
        protection: {
            score: 34,
            risksPrevented: 0,
            context: "Low activity this week",
            weekLabel: "this week",
        },
        timeline: [{ hour: 14, type: "snapshot", file: "README.md", risk: "low", action: "routine protection" }],
        heatmap: [{ file: "README.md", risk: 0.12, changes: 1, aiRatio: 0, cat: "util" }],
    });
}
export function generateHighRiskDashboard() {
    return generateMockDashboard({
        protection: {
            score: 92,
            risksPrevented: 12,
            context: "Multiple high-risk AI edits detected and protected",
            weekLabel: "this week",
        },
        timeline: Array.from({ length: 12 }, (_, i) => ({
            hour: 2 + i * 2,
            type: i % 3 === 0 ? "recovery" : "ai_detected",
            tool: ["cursor", "copilot", "claude"][i % 3],
            file: `src/components/File${i}.tsx`,
            risk: ["high", "medium", "low"][i % 3],
            action: i % 3 === 0 ? "recovered" : "auto-protected",
            blast: Math.floor(Math.random() * 15) + 1,
        })),
    });
}
