/**
 * Claims Ledger Events
 *
 * Spine event domain for claim.recorded, claim.resolved, claim.expired.
 * These events flow through the DaemonEventBus per ADR-007 V2.
 */
import { extendZodWithOpenApi } from "@asteasolutions/zod-to-openapi";
import { z } from "zod";
import { BaseClaim, Outcome } from "../claims/index.js";
extendZodWithOpenApi(z);
// =============================================================================
// Event Version
// =============================================================================
export const CLAIMS_EVENT_VERSION = "1.0.0";
// =============================================================================
// Claim Made Event
// =============================================================================
/**
 * claim.recorded  -  fired when a claim is written to the ledger.
 */
export const ClaimMadeEventSchema = z.object({
    event_version: z.string().default(CLAIMS_EVENT_VERSION).openapi({ example: "1.0.0" }),
    timestamp: z
        .number()
        .default(() => Date.now())
        .openapi({ example: 1620000000000 }),
    event: z.literal("claim.recorded"),
    payload: z.object({
        claim: BaseClaim.openapi({ description: "The claim that was recorded" }),
        workspaceHash: z.string().openapi({
            description: "SHA-256 hash of workspace path",
            example: "a1b2c3d4...",
        }),
    }),
});
// =============================================================================
// Claim Resolved Event
// =============================================================================
/**
 * claim.resolved  -  fired when an outcome is written for a claim.
 */
export const ClaimResolvedEventSchema = z.object({
    event_version: z.string().default(CLAIMS_EVENT_VERSION).openapi({ example: "1.0.0" }),
    timestamp: z
        .number()
        .default(() => Date.now())
        .openapi({ example: 1620000000000 }),
    event: z.literal("claim.resolved"),
    payload: z.object({
        claimId: z.string().uuid().openapi({ description: "ID of the resolved claim" }),
        outcome: Outcome.openapi({ description: "The outcome record" }),
        workspaceHash: z.string().openapi({
            description: "SHA-256 hash of workspace path",
            example: "a1b2c3d4...",
        }),
    }),
});
// =============================================================================
// Claim Expired Event
// =============================================================================
/**
 * claim.expired  -  fired when a deferred claim passes its TTL.
 */
export const ClaimExpiredEventSchema = z.object({
    event_version: z.string().default(CLAIMS_EVENT_VERSION).openapi({ example: "1.0.0" }),
    timestamp: z
        .number()
        .default(() => Date.now())
        .openapi({ example: 1620000000000 }),
    event: z.literal("claim.expired"),
    payload: z.object({
        claimId: z.string().uuid().openapi({ description: "ID of the expired claim" }),
        outcomeId: z.string().uuid().openapi({ description: "ID of the expiration outcome" }),
        expiredAt: z.number().openapi({ description: "Timestamp when expiry was recorded" }),
        workspaceHash: z.string().openapi({
            description: "SHA-256 hash of workspace path",
            example: "a1b2c3d4...",
        }),
    }),
});
// =============================================================================
// Validation Helpers
// =============================================================================
export function isClaimMadeEvent(event) {
    return ClaimMadeEventSchema.safeParse(event).success;
}
export function isClaimResolvedEvent(event) {
    return ClaimResolvedEventSchema.safeParse(event).success;
}
export function isClaimExpiredEvent(event) {
    return ClaimExpiredEventSchema.safeParse(event).success;
}
