/**
 * Capability Taxonomy TypeScript Interface
 *
 * Type-safe interface for the capability-taxonomy.yaml configuration.
 * Use loadCapabilityTaxonomy() to load and validate the YAML config.
 *
 * @module config/capability-taxonomy
 */
import { z } from "zod";
/**
 * Zod schema for validation
 */
export const CapabilityTaxonomySchema = z.object({
    version: z.string(),
    riskClasses: z.record(z.enum(["safe", "low", "medium", "high", "critical"]), z.object({
        description: z.string(),
        defaultSandbox: z.enum(["none", "basic", "strict", "isolated"]),
        requiresAuth: z.boolean(),
        requiresSnapshot: z.boolean(),
        maxConcurrent: z.number().positive(),
        timeoutMs: z.number().positive(),
        requiresApproval: z.boolean().optional(),
    })),
    categories: z.record(z.string(), z.object({
        description: z.string(),
        namespace: z.string(),
        defaultRiskClass: z.enum(["safe", "low", "medium", "high", "critical"]),
    })),
    tools: z.array(z.object({
        urn: z.string(),
        name: z.string(),
        description: z.string(),
        category: z.string(),
        riskClass: z.enum(["safe", "low", "medium", "high", "critical"]),
        caps: z.array(z.string()),
        requiredPermissions: z.array(z.string()),
        requiredFeatures: z.array(z.string()),
        minTier: z.enum(["free", "pro", "team", "enterprise"]).optional(),
        inputSchema: z.object({
            type: z.literal("object"),
            properties: z.record(z.string(), z.any()).optional(),
            required: z.array(z.string()).optional(),
        }),
    })),
    permissions: z.array(z.object({
        id: z.string(),
        description: z.string(),
        scope: z.enum(["workspace", "channel", "admin"]),
        requiresTier: z.enum(["free", "pro", "team", "enterprise"]).optional(),
    })),
    sandboxes: z.record(z.enum(["none", "basic", "strict", "isolated"]), z.object({
        description: z.string(),
        capabilities: z.array(z.string()),
        restrictions: z.array(z.string()),
        implementation: z.enum(["container", "vm", "process"]).optional(),
    })),
});
/**
 * Tool registry for fast URN lookups
 */
export class ToolRegistry {
    taxonomy;
    toolsByUrn;
    toolsByCategory;
    constructor(taxonomy) {
        this.taxonomy = taxonomy;
        this.toolsByUrn = new Map();
        this.toolsByCategory = new Map();
        for (const tool of taxonomy.tools) {
            this.toolsByUrn.set(tool.urn, tool);
            const categoryTools = this.toolsByCategory.get(tool.category) ?? [];
            categoryTools.push(tool);
            this.toolsByCategory.set(tool.category, categoryTools);
        }
    }
    /**
     * Get tool by URN
     */
    getTool(urn) {
        return this.toolsByUrn.get(urn);
    }
    /**
     * Get tools by category
     */
    getToolsByCategory(category) {
        return this.toolsByCategory.get(category) ?? [];
    }
    /**
     * Get risk class config
     */
    getRiskClassConfig(riskClass) {
        return this.taxonomy.riskClasses[riskClass];
    }
    /**
     * Get sandbox config
     */
    getSandboxConfig(sandbox) {
        return this.taxonomy.sandboxes[sandbox];
    }
    /**
     * Get all available URNs
     */
    getAllUrns() {
        return Array.from(this.toolsByUrn.keys());
    }
    /**
     * Check if tool requires specific tier
     */
    checkTierRequirement(urn, userTier) {
        const tool = this.getTool(urn);
        if (!tool?.minTier) {
            return true;
        }
        const tierOrder = {
            free: 0,
            pro: 1,
            team: 2,
            enterprise: 3,
        };
        return tierOrder[userTier] >= tierOrder[tool.minTier];
    }
    /**
     * Get required permissions for tool
     */
    getRequiredPermissions(urn) {
        return this.getTool(urn)?.requiredPermissions ?? [];
    }
    /**
     * Get required features for tool
     */
    getRequiredFeatures(urn) {
        return this.getTool(urn)?.requiredFeatures ?? [];
    }
}
/**
 * Parse and validate taxonomy from object (loaded YAML)
 */
export function parseCapabilityTaxonomy(data) {
    return CapabilityTaxonomySchema.parse(data);
}
/**
 * Create a ToolRegistry from taxonomy data
 */
export function createToolRegistry(data) {
    const taxonomy = parseCapabilityTaxonomy(data);
    return new ToolRegistry(taxonomy);
}
