/**
 * Claims Ledger Registry
 *
 * Known claimants and claim-type to resolution strategy mapping.
 * All claimants must be registered here before writing claims.
 */
import { z } from "zod";
// =============================================================================
// Registered Claimants
// =============================================================================
/**
 * Finite, named claimants allowed to write to the ledger.
 *
 * To add a new claimant:
 * 1. Add URN to this array
 * 2. Update CLAIM_TYPE_RESOLUTION with their claim types
 * 3. Deploy claimant code
 *
 * Format: urn:claimant:<identifier>
 */
export const REGISTERED_CLAIMANTS = [
    "urn:claimant:subagent-stop-hook",
    "urn:claimant:drift-detector",
    "urn:claimant:tool-identity",
    "urn:claimant:spec-writer",
    "urn:claimant:intelligence.risk-scorer",
    "urn:claimant:intelligence.fragility-detector",
    "urn:claimant:intelligence.pattern-detector",
];
/**
 * Zod schema for registered claimant validation.
 */
export const RegisteredClaimant = z.enum(REGISTERED_CLAIMANTS);
/**
 * Check if a claimant URN is registered.
 */
export function isRegisteredClaimant(claimant) {
    return REGISTERED_CLAIMANTS.includes(claimant);
}
// =============================================================================
// Claim Type Registry
// =============================================================================
/**
 * Claim types and their outcome resolution strategies.
 *
 * Rule: No claim type may be added without a defined resolution strategy.
 * If there is no mechanism to determine whether the claim was right or wrong,
 * the signal belongs in logs, not the ledger.
 */
export const CLAIM_TYPE_RESOLUTION = {
    // Completion claims (immediate resolution)
    "completion.spec-phase": "immediate",
    "completion.session": "immediate",
    "completion.deployment": "immediate",
    // Verdict claims (deferred-manual resolution)
    "verdict.drift-detected": "deferred-manual",
    "verdict.risk-assessment": "deferred-manual",
    "verdict.code-review": "deferred-manual",
    // Attribution claims (deferred-observational resolution)
    "attribution.tool-change": "deferred-observational",
    "attribution.ai-authored": "deferred-observational",
    "attribution.automation": "deferred-observational",
    // Prediction claims (deferred-observational resolution)
    "prediction.fragility": "deferred-observational",
    "prediction.rollback": "deferred-observational",
    "prediction.bug-risk": "deferred-observational",
    "prediction.performance": "deferred-observational",
};
/**
 * Get the resolution strategy for a claim type.
 */
export function getResolutionStrategy(claimType) {
    return CLAIM_TYPE_RESOLUTION[claimType] ?? null;
}
/**
 * Check if a claim type has a registered resolution strategy.
 */
export function isValidClaimType(claimType) {
    return claimType in CLAIM_TYPE_RESOLUTION;
}
/**
 * Get all claim types for a given resolution strategy.
 */
export function getClaimTypesByStrategy(strategy) {
    return Object.entries(CLAIM_TYPE_RESOLUTION)
        .filter(([, s]) => s === strategy)
        .map(([type]) => type);
}
// =============================================================================
// Validation
// =============================================================================
/**
 * Validate a claimant + claim type combination.
 * Returns null if valid, error message if invalid.
 */
export function validateClaimRegistration(claimant, claimType) {
    if (!isRegisteredClaimant(claimant)) {
        return `Unregistered claimant: ${claimant}. Add to REGISTERED_CLAIMANTS first.`;
    }
    if (!isValidClaimType(claimType)) {
        return `Unregistered claim type: ${claimType}. Add to CLAIM_TYPE_RESOLUTION with resolution strategy.`;
    }
    return null;
}
