// ESM imports fixed for Node.js v22+
/**
 * API Error Response Schemas
 *
 * Zod schemas for API error response validation.
 *
 * @module @vreko/contracts/api/errors/schemas
 */
import { z } from "zod";
import { ApiErrorCodeSchema } from "./codes.js";
// =============================================================================
// ERROR RESPONSE SCHEMA
// =============================================================================
/**
 * Validation error detail for field-level errors
 */
export const ValidationErrorDetailSchema = z.object({
    field: z.string().describe("The field path that failed validation"),
    message: z.string().describe("Human-readable error message"),
    code: z.string().optional().describe("Zod error code"),
});
/**
 * Standard API error response format
 *
 * This format is used consistently across all API endpoints.
 */
export const ApiErrorResponseSchema = z.object({
    /** Human-readable error message (safe to display to users) */
    error: z.string(),
    /** Machine-readable error code for programmatic handling */
    code: ApiErrorCodeSchema,
    /** Optional detailed error information */
    details: z
        .union([
        z.array(ValidationErrorDetailSchema), // For validation errors
        z.record(z.string(), z.unknown()), // For other contextual data
    ])
        .optional(),
    /** Request ID for support correlation (from X-Request-Id header) */
    requestId: z.string().optional(),
    /** Timestamp when error occurred */
    timestamp: z.string().datetime().optional(),
});
