/**
 * CloudEvents Specification Types (v1.0.2)
 *
 * Implements the CloudEvents spec for structured event emission.
 * Used for audit logging, telemetry, and inter-service communication.
 *
 * @see https://cloudevents.io/
 * @module contracts/primitives/cloud-event
 */
import { z } from "zod";
/**
 * Vreko event types (reverse-DNS format)
 */
export const VrekoEventTypes = {
    // Tool lifecycle events
    TOOL_INVOCATION_STARTED: "dev.vreko.tool.invocation.started",
    TOOL_INVOCATION_COMPLETED: "dev.vreko.tool.invocation.completed",
    TOOL_INVOCATION_FAILED: "dev.vreko.tool.invocation.failed",
    TOOL_INVOCATION_DENIED: "dev.vreko.tool.invocation.denied",
    // Security events
    POLICY_EVALUATED: "dev.vreko.security.policy.evaluated",
    AUTH_REQUIRED: "dev.vreko.security.auth.required",
    RATE_LIMITED: "dev.vreko.security.rate.limited",
    THREAT_DETECTED: "dev.vreko.security.threat.detected",
    SECRETS_SCANNED: "dev.vreko.security.secrets.scanned",
    // Session events
    SESSION_STARTED: "dev.vreko.session.started",
    SESSION_ENDED: "dev.vreko.session.ended",
    SESSION_CHECKPOINTED: "dev.vreko.session.checkpointed",
    // Snapshot events
    SNAPSHOT_CREATED: "dev.vreko.snapshot.created",
    SNAPSHOT_RESTORED: "dev.vreko.snapshot.restored",
    // Learning events
    LEARNING_CAPTURED: "dev.vreko.learning.captured",
    LEARNING_PROMOTED: "dev.vreko.learning.promoted",
    VIOLATION_RECORDED: "dev.vreko.learning.violation.recorded",
    // Workspace events
    WORKSPACE_LINKED: "dev.vreko.workspace.linked",
    WORKSPACE_CONTEXT_UPDATED: "dev.vreko.workspace.context.updated",
    // Audit events
    AUDIT_LOG_CREATED: "dev.vreko.audit.log.created",
    EGRESS_CHECKED: "dev.vreko.audit.egress.checked",
};
/**
 * Zod schema for CloudEvent validation
 */
export const CloudEventSchema = z.object({
    id: z.string().min(1),
    source: z.string().min(1),
    specversion: z.literal("1.0"),
    type: z.string().min(1),
    datacontenttype: z.string().optional(),
    dataschema: z.string().url().optional(),
    subject: z.string().optional(),
    time: z.string().datetime().optional(),
    data: z.unknown().optional(),
    // Vreko extensions
    traceid: z.string().optional(),
    workspaceid: z.string().optional(),
    userid: z.string().optional(),
    sessionid: z.string().optional(),
    toolurn: z.string().optional(),
    riskclass: z.enum(["safe", "low", "medium", "high", "critical"]).optional(),
    sandboxed: z.boolean().optional(),
    privacysig: z.string().optional(),
});
/**
 * Create a CloudEvent with required fields
 */
export function createCloudEvent(params) {
    return {
        id: params.id,
        source: params.source,
        specversion: "1.0",
        type: params.type,
        datacontenttype: "application/json",
        time: new Date().toISOString(),
        subject: params.subject,
        data: params.data,
        ...params.extensions,
    };
}
/**
 * Create a CloudEvent from a ToolInvocation
 */
export function createToolInvocationEvent(params) {
    return createCloudEvent({
        id: params.traceId,
        source: params.source,
        type: params.type,
        subject: params.toolUrn,
        data: params.data,
        extensions: {
            traceid: params.traceId,
            workspaceid: params.workspaceId,
            sessionid: params.sessionId,
            userid: params.userId,
            toolurn: params.toolUrn,
            riskclass: params.riskClass,
            sandboxed: params.sandboxed,
        },
    });
}
/**
 * In-memory CloudEvent emitter (for development/testing)
 */
export function createInMemoryEventEmitter() {
    const handlers = new Map();
    return {
        async emit(event) {
            const typeHandlers = handlers.get(event.type);
            if (typeHandlers) {
                await Promise.all(Array.from(typeHandlers).map((handler) => handler(event)));
            }
            // Also emit to wildcard handlers
            const wildcardHandlers = handlers.get("*");
            if (wildcardHandlers) {
                await Promise.all(Array.from(wildcardHandlers).map((handler) => handler(event)));
            }
        },
        async emitBatch(events) {
            await Promise.all(events.map((event) => this.emit(event)));
        },
        subscribe(type, handler) {
            const types = Array.isArray(type) ? type : [type];
            for (const t of types) {
                if (!handlers.has(t)) {
                    handlers.set(t, new Set());
                }
                handlers.get(t)?.add(handler);
            }
            // Return unsubscribe function
            return () => {
                for (const t of types) {
                    handlers.get(t)?.delete(handler);
                }
            };
        },
    };
}
