// ESM imports fixed for Node.js v22+
import { z } from "zod";
import { AuthScope } from "./scopes.js";
// ---------------------------------------------------------------------------
// User metadata
// ---------------------------------------------------------------------------
export const UserMetadata = z.object({
    pioneer: z.boolean().default(false),
    pioneerCohort: z.number().int().optional(),
    referralCode: z.string().optional(),
    invitedBy: z.string().nullable().optional(),
});
// ---------------------------------------------------------------------------
// Organization (tenant)
// ---------------------------------------------------------------------------
export const OrgType = z.enum(["personal", "team"]);
export const OrgRole = z.enum(["owner", "admin", "member"]);
export const Organization = z.object({
    id: z.string().uuid(),
    name: z.string(),
    type: OrgType,
    tier: z.enum(["free", "pro", "team", "enterprise"]),
    stripeCustomerId: z.string().nullable(),
    stripeSubscriptionId: z.string().nullable(),
    metadata: z
        .object({
        saml: z
            .object({
            entryPoint: z.string().url(),
            issuer: z.string(),
            cert: z.string(),
        })
            .optional(),
    })
        .optional(),
    createdAt: z.string().datetime(),
});
// ---------------------------------------------------------------------------
// API key
// ---------------------------------------------------------------------------
export const ApiKey = z.object({
    id: z.string().uuid(),
    keyPreview: z.string(),
    name: z.string(),
    orgId: z.string().uuid(),
    createdBy: z.string().uuid(),
    scopes: z.array(AuthScope).default(["api"]),
    createdAt: z.string().datetime(),
    lastUsedAt: z.string().datetime().nullable(),
    revokedAt: z.string().datetime().nullable(),
});
// ---------------------------------------------------------------------------
// Auth identity (resolved by middleware)
// ---------------------------------------------------------------------------
export const AuthIdentity = z.object({
    userId: z.string().uuid(),
    orgId: z.string().uuid(),
    role: OrgRole,
    tier: z.enum(["free", "pro", "team", "enterprise"]),
    scopes: z.array(AuthScope),
    pioneer: z.boolean(),
    authenticatedVia: z.enum(["session", "api_key", "device_token"]),
});
// ---------------------------------------------------------------------------
// Device flow
// ---------------------------------------------------------------------------
export const DeviceCodeResponse = z.object({
    deviceCode: z.string(),
    userCode: z.string(),
    verificationUri: z.string().url(),
    expiresIn: z.number().int(),
    interval: z.number().int(),
});
export const DeviceTokenResponse = z.discriminatedUnion("status", [
    z.object({
        status: z.literal("pending"),
        error: z.literal("authorization_pending"),
    }),
    z.object({
        status: z.literal("success"),
        accessToken: z.string(),
        refreshToken: z.string(),
        expiresIn: z.number().int(),
        orgId: z.string().uuid(),
    }),
    z.object({
        status: z.literal("denied"),
        error: z.literal("access_denied"),
    }),
    z.object({
        status: z.literal("expired"),
        error: z.literal("expired_token"),
    }),
]);
// ---------------------------------------------------------------------------
// Role permissions matrix (canonical)
// ---------------------------------------------------------------------------
export const ROLE_PERMISSIONS = {
    owner: {
        console: true,
        apiKeyCreate: true,
        apiKeyRevokeAll: true,
        billing: true,
        teamInvite: true,
        teamRemove: true,
        teamChangeRoles: true,
    },
    admin: {
        console: true,
        apiKeyCreate: true,
        apiKeyRevokeAll: false,
        billing: false,
        teamInvite: true,
        teamRemove: true,
        teamChangeRoles: false,
    },
    member: {
        console: true,
        apiKeyCreate: true,
        apiKeyRevokeAll: false,
        billing: false,
        teamInvite: false,
        teamRemove: false,
        teamChangeRoles: false,
    },
};
