import { z } from "zod";
// =============================================================================
// AUTH CONTEXT CONTRACTS (Phase 1  -  Contracts Compliance)
// =============================================================================
/**
 * Minimal authentication context carried through API middleware and MCP tools.
 *
 * This is distinct from the full AuthUser/Session types in auth/session.ts which
 * are tied to Better Auth's session model. AuthContextSchema is the lightweight
 * version passed via oRPC context after the middleware extracts it.
 *
 * Role definitions:
 *   user   -  free tier authenticated user
 *   pro    -  paid individual subscriber
 *   team   -  team plan member
 *   admin  -  Vreko staff (internal tooling only)
 */
export const AuthContextSchema = z.object({
    userId: z.string(),
    email: z.string().email(),
    role: z.enum(["user", "pro", "team", "admin"]),
    workspaceId: z.string().optional(),
});
