/**
 * Snapshot Domain Spine Events - ADR-007 §3
 *
 * Spine events for snapshot lifecycle operations.
 * Event types use three-part naming: snapshot.<entity>.<action>
 *
 * @module @vreko/contracts/events/spine/domains/snapshot
 * @see ADR-007 Runtime Tier Boundaries and Export Spine Contract
 */
import { z } from "zod";
import { createSpineEventSchema } from "../envelope.js";
// =============================================================================
// Shared Snapshot Schemas
// =============================================================================
/**
 * Trigger source for snapshot operations
 */
export const snapshotTriggerSchema = z.enum([
    "manual", // User manually triggered
    "auto-save", // Automatic save on change
    "pre-command", // Before command execution
    "session-end", // End of session
    "shutdown", // System shutdown
]);
/**
 * Risk level for snapshots
 */
export const riskLevelSchema = z.enum(["low", "medium", "high", "critical"]);
/**
 * Snapshot risk information
 */
export const snapshotRiskSchema = z.object({
    score: z.number().min(0),
    level: riskLevelSchema,
});
// =============================================================================
// snapshot.blob.created
// =============================================================================
/**
 * Data payload for snapshot.blob.created event
 */
export const snapshotBlobCreatedDataSchema = z.object({
    /** Unique snapshot identifier */
    snapshotId: z.string().uuid(),
    /** SHA-256 hash of file content (never raw content) */
    contentHash: z.string().regex(/^[0-9a-f]{64}$/i),
    /** Size of snapshot in bytes */
    sizeBytes: z.number().int().nonnegative(),
    /** What triggered the snapshot creation */
    trigger: snapshotTriggerSchema,
    /** Risk assessment at time of snapshot */
    risk: snapshotRiskSchema.optional(),
    /** AI tool attribution confidence if detected */
    toolConfidence: z.number().min(0).max(1).optional(),
});
/**
 * Spine event schema for snapshot.blob.created
 *
 * Emitted when a new snapshot blob is created in the local store.
 * File paths are never included; only content hashes.
 */
export const snapshotBlobCreatedSchema = createSpineEventSchema(snapshotBlobCreatedDataSchema);
/**
 * Event type constant for type-safe references
 */
export const SNAPSHOT_BLOB_CREATED = "snapshot.blob.created";
// =============================================================================
// snapshot.blob.restored
// =============================================================================
/**
 * Data payload for snapshot.blob.restored event
 */
export const snapshotBlobRestoredDataSchema = z.object({
    /** Snapshot identifier that was restored */
    snapshotId: z.string().uuid(),
    /** Time when snapshot was originally created */
    originalCreatedAt: z.number().int().positive(),
    /** Trigger for the restore operation */
    trigger: z.enum(["manual", "rollback", "undo", "system"]),
    /** Time taken to restore in milliseconds */
    durationMs: z.number().int().nonnegative(),
});
/**
 * Spine event schema for snapshot.blob.restored
 *
 * Emitted when a snapshot blob is restored to active workspace.
 */
export const snapshotBlobRestoredSchema = createSpineEventSchema(snapshotBlobRestoredDataSchema);
/**
 * Event type constant
 */
export const SNAPSHOT_BLOB_RESTORED = "snapshot.blob.restored";
// =============================================================================
// snapshot.blob.deleted
// =============================================================================
/**
 * Data payload for snapshot.blob.deleted event
 */
export const snapshotBlobDeletedDataSchema = z.object({
    /** Array of snapshot identifiers that were deleted */
    snapshotIds: z.array(z.string().uuid()),
    /** Reason for deletion */
    reason: z.enum(["retention-policy", "user-request", "corrupted", "gc"]),
    /** Number of bytes freed */
    bytesFreed: z.number().int().nonnegative(),
});
/**
 * Spine event schema for snapshot.blob.deleted
 *
 * Emitted when snapshot blobs are permanently deleted.
 */
export const snapshotBlobDeletedSchema = createSpineEventSchema(snapshotBlobDeletedDataSchema);
/**
 * Event type constant
 */
export const SNAPSHOT_BLOB_DELETED = "snapshot.blob.deleted";
// =============================================================================
// snapshot.metadata.updated
// =============================================================================
/**
 * Data payload for snapshot.metadata.updated event
 */
export const snapshotMetadataUpdatedDataSchema = z.object({
    /** Snapshot identifier */
    snapshotId: z.string().uuid(),
    /** Fields that were updated */
    updatedFields: z.array(z.enum(["tags", "risk", "annotation", "protection"])),
    /** Previous risk level if risk was updated */
    previousRisk: riskLevelSchema.optional(),
    /** New risk level if risk was updated */
    newRisk: riskLevelSchema.optional(),
});
/**
 * Spine event schema for snapshot.metadata.updated
 *
 * Emitted when snapshot metadata (not content) is modified.
 */
export const snapshotMetadataUpdatedSchema = createSpineEventSchema(snapshotMetadataUpdatedDataSchema);
/**
 * Event type constant
 */
export const SNAPSHOT_METADATA_UPDATED = "snapshot.metadata.updated";
/**
 * All snapshot event type constants
 */
export const SNAPSHOT_EVENT_TYPES = [
    SNAPSHOT_BLOB_CREATED,
    SNAPSHOT_BLOB_RESTORED,
    SNAPSHOT_BLOB_DELETED,
    SNAPSHOT_METADATA_UPDATED,
];
/**
 * Map of event types to their schemas for validation
 */
export const SNAPSHOT_EVENT_SCHEMAS = {
    [SNAPSHOT_BLOB_CREATED]: snapshotBlobCreatedSchema,
    [SNAPSHOT_BLOB_RESTORED]: snapshotBlobRestoredSchema,
    [SNAPSHOT_BLOB_DELETED]: snapshotBlobDeletedSchema,
    [SNAPSHOT_METADATA_UPDATED]: snapshotMetadataUpdatedSchema,
};
