/**
 * Base Error Class
 *
 * Foundation error class that can be extended by different error systems.
 * Provides common error handling patterns used across Vreko.
 *
 * @module @vreko/contracts/errors/base
 */
// =============================================================================
// BASE ERROR CLASS
// =============================================================================
/**
 * Base error class with structured error information
 *
 * Extends Error to provide:
 * - Error codes for programmatic handling
 * - Contextual details for debugging
 * - Proper stack trace preservation
 *
 * @example
 * ```typescript
 * class MyError extends BaseError {
 *   constructor(message: string) {
 *     super('MY_ERROR', message, { category: 'custom' });
 *   }
 * }
 * ```
 */
export class BaseError extends Error {
    code;
    details;
    constructor(code, message, details) {
        super(message);
        this.name = "BaseError";
        this.code = code;
        this.details = details;
        // Maintains proper stack trace for where error was thrown
        Error.captureStackTrace?.(this, BaseError);
    }
    /**
     * Check if this error has a specific code
     */
    hasCode(code) {
        return this.code === code;
    }
    /**
     * Get error context as JSON-serializable object
     */
    toJSON() {
        return {
            name: this.name,
            code: this.code,
            message: this.message,
            ...(this.details && { details: this.details }),
        };
    }
}
// =============================================================================
// ERROR UTILITIES
// =============================================================================
/**
 * Safely extract error message from unknown error type
 *
 * Use this in catch blocks with `catch (error: unknown)`
 *
 * @param error - Unknown error object
 * @returns Error message string
 *
 * @example
 * ```typescript
 * try {
 *   await riskyOperation();
 * } catch (error: unknown) {
 *   const message = extractErrorMessage(error);
 *   logger.error(message);
 * }
 * ```
 */
export function extractErrorMessage(error) {
    if (error instanceof Error) {
        return error.message;
    }
    if (typeof error === "string") {
        return error;
    }
    if (error && typeof error === "object" && "message" in error) {
        return String(error.message);
    }
    return String(error);
}
/**
 * Safely check if error is an Error instance and has a specific code
 *
 * @param error - Unknown error object
 * @param code - Error code to check
 * @returns True if error has the specified code
 */
export function hasErrorCode(error, code) {
    return error instanceof Error && "code" in error && error.code === code;
}
/**
 * Extract error code from error object
 *
 * @param error - Error object
 * @returns Error code string or undefined
 */
export function extractErrorCode(error) {
    if (error.code) {
        return error.code;
    }
    // Extract from error name
    if (error.name && error.name !== "Error") {
        return error.name
            .toUpperCase()
            .replace(/ERROR$/, "")
            .replace(/\s+/g, "_");
    }
    return undefined;
}
/**
 * Check if error is a BaseError instance
 */
export function isBaseError(error) {
    return error instanceof BaseError;
}
// =============================================================================
// UNIFIED ERROR UTILITIES (Consolidated from SDK, VS Code, and Contracts)
// =============================================================================
/**
 * Convert unknown error to Error instance
 *
 * Unified implementation used across all Vreko packages.
 * Replaces duplicate implementations in:
 * - packages-oss/sdk/src/errors/index.ts
 * - apps/vscode/src/utils/error.ts
 *
 * @param error - Unknown error value
 * @returns Error instance
 *
 * @example
 * ```typescript
 * try {
 *   await riskyOperation();
 * } catch (error: unknown) {
 *   const err = toError(error);
 *   logger.error(err.message);
 * }
 * ```
 */
export function toError(error) {
    if (error instanceof Error) {
        return error;
    }
    if (typeof error === "string") {
        return new Error(error);
    }
    if (error && typeof error === "object") {
        if ("message" in error && typeof error.message === "string") {
            return new Error(error.message);
        }
        try {
            return new Error(JSON.stringify(error));
        }
        catch {
            return new Error(String(error));
        }
    }
    return new Error(String(error));
}
/**
 * Safely extract error message from unknown error type
 *
 * @deprecated Use extractErrorMessage() instead for consistency
 * @param error - Unknown error object
 * @returns Error message string
 */
export function getErrorMessage(error) {
    return extractErrorMessage(error);
}
/**
 * Safely extract error stack trace
 *
 * @param error - Unknown error value
 * @returns Stack trace string or undefined
 */
export function getErrorStack(error) {
    return toError(error).stack;
}
/**
 * Check if error has a specific code
 *
 * Unified replacement for isErrorWithCode() from VS Code
 *
 * @param error - Unknown error object
 * @param code - Error code to check
 * @returns True if error has the specified code
 */
export function isErrorWithCode(error, code) {
    return hasErrorCode(error, code);
}
/**
 * Ensure error is an Error instance with optional code wrapping
 *
 * @param error - Unknown error value
 * @param code - Optional error code to assign
 * @returns Error instance (possibly wrapped)
 */
export function ensureError(error, code) {
    const err = toError(error);
    if (code && !("code" in err)) {
        Object.defineProperty(err, "code", {
            value: code,
            writable: false,
            enumerable: true,
            configurable: true,
        });
    }
    return err;
}
