/**
 * Domain Error Base Classes
 *
 * Foundation error classes for type-safe error handling with neverthrow.
 * Each domain (snapshot, session, protection, validation, learning) extends
 * these base classes for domain-specific error types.
 *
 * @module @vreko/contracts/errors/domain/base
 */
// =============================================================================
// DOMAIN ERROR BASE CLASS
// =============================================================================
/**
 * Base class for all domain errors
 *
 * Provides structured error information compatible with neverthrow's Result type.
 * All domain-specific errors extend this class.
 *
 * @example
 * ```typescript
 * class SnapshotNotFoundError extends DomainError {
 *   constructor(snapshotId: string) {
 *     super(
 *       'SNAPSHOT_NOT_FOUND',
 *       `Snapshot not found: ${snapshotId}`,
 *       { snapshotId }
 *     );
 *   }
 * }
 * ```
 */
export class DomainError extends Error {
    /**
     * Machine-readable error code for programmatic handling
     */
    code;
    /**
     * Additional context for debugging and error reporting
     */
    details;
    /**
     * Timestamp when the error occurred
     */
    timestamp;
    constructor(code, message, details) {
        super(message);
        this.name = this.constructor.name;
        this.code = code;
        this.details = details;
        this.timestamp = Date.now();
        // Maintains proper stack trace for where error was thrown
        Error.captureStackTrace?.(this, this.constructor);
    }
    /**
     * Check if this error has a specific code
     */
    hasCode(code) {
        return this.code === code;
    }
    /**
     * Get error context as JSON-serializable object
     */
    toJSON() {
        return {
            name: this.name,
            code: this.code,
            message: this.message,
            timestamp: this.timestamp,
            ...(this.details && { details: this.details }),
        };
    }
}
// =============================================================================
// ERROR CATEGORIES
// =============================================================================
/**
 * Error category enumeration for classification
 */
export var ErrorCategory;
(function (ErrorCategory) {
    /** Resource not found errors */
    ErrorCategory["NOT_FOUND"] = "NOT_FOUND";
    /** Validation errors */
    ErrorCategory["VALIDATION"] = "VALIDATION";
    /** Permission/auth errors */
    ErrorCategory["PERMISSION"] = "PERMISSION";
    /** State/conflict errors */
    ErrorCategory["CONFLICT"] = "CONFLICT";
    /** External service errors */
    ErrorCategory["EXTERNAL"] = "EXTERNAL";
    /** Internal/system errors */
    ErrorCategory["INTERNAL"] = "INTERNAL";
})(ErrorCategory || (ErrorCategory = {}));
/**
 * Categorized domain error with category support
 */
export class CategorizedDomainError extends DomainError {
    category;
    constructor(code, message, category, details) {
        super(code, message, details);
        this.category = category;
    }
    toJSON() {
        return {
            ...super.toJSON(),
            category: this.category,
        };
    }
}
// =============================================================================
// COMMON ERROR TYPES
// =============================================================================
/**
 * Error for resource not found scenarios
 */
export class NotFoundError extends CategorizedDomainError {
    constructor(resourceType, resourceId, details) {
        super(`${resourceType.toUpperCase()}_NOT_FOUND`, `${resourceType} not found: ${resourceId}`, ErrorCategory.NOT_FOUND, { resourceType, resourceId, ...details });
    }
}
/**
 * Error for validation failures
 */
export class ValidationError extends CategorizedDomainError {
    validationErrors;
    constructor(message, validationErrors, details) {
        super("VALIDATION_ERROR", message, ErrorCategory.VALIDATION, { validationErrors, ...details });
        this.validationErrors = validationErrors;
    }
}
/**
 * Error for permission denied scenarios
 */
export class PermissionError extends CategorizedDomainError {
    constructor(action, resource, reason, details) {
        super("PERMISSION_DENIED", `Permission denied: cannot ${action} on ${resource}${reason ? ` - ${reason}` : ""}`, ErrorCategory.PERMISSION, { action, resource, reason, ...details });
    }
}
/**
 * Error for conflict scenarios (e.g., resource already exists)
 */
export class ConflictError extends CategorizedDomainError {
    constructor(message, conflictingResource, details) {
        super("CONFLICT", message, ErrorCategory.CONFLICT, { conflictingResource, ...details });
    }
}
/**
 * Error for external service failures
 */
export class ExternalServiceError extends CategorizedDomainError {
    constructor(serviceName, operation, originalError, details) {
        super("EXTERNAL_SERVICE_ERROR", `External service error: ${serviceName} failed during ${operation}`, ErrorCategory.EXTERNAL, {
            serviceName,
            operation,
            originalErrorMessage: originalError?.message,
            ...details,
        });
    }
}
