/**
 * Tool URN (Uniform Resource Name) - Phase 0 Primitive
 *
 * Provides stable, namespaced identifiers for tools across all surfaces
 * (API, MCP, OpenClaw, CLI). Replaces runtime `generateToolName()` with
 * design-time registry.
 *
 * URN Format: urn:${namespace}:${pluginId}:${capability}:${semver}
 *
 * Examples:
 * - urn:vreko:core:snapshot:1.0.0
 * - urn:openclaw:telegram:send-message:2.1.0
 * - urn:vreko:mcp:file-read:1.0.0
 *
 * @module primitives/tool-urn
 */
import { z } from "zod";
/**
 * Valid URN namespaces
 * - vreko: Core Vreko tools
 * - openclaw: OpenClaw channel plugins
 * - community: Third-party community tools
 * - enterprise: Enterprise-only tools
 */
export const URN_NAMESPACES = ["vreko", "openclaw", "community", "enterprise"];
/**
 * Semantic version schema (simplified for URN)
 */
export const SemverSchema = z
    .string()
    .regex(/^\d+\.\d+\.\d+(?:-[\w.]+)?$/, "Invalid semver format. Expected: MAJOR.MINOR.PATCH[-prerelease]");
/**
 * Tool URN schema with validation
 */
export const ToolURNSchema = z
    .string()
    .regex(/^urn:(vreko|openclaw|community|enterprise):[\w-]+:[\w-]+:\d+\.\d+\.\d+(?:-[\w.]+)?$/, "Invalid URN format. Expected: urn:{namespace}:{pluginId}:{capability}:{semver}")
    .brand();
/**
 * Parse a URN string into its components
 *
 * @param urn - URN string to parse
 * @returns Parsed URN components
 * @throws Error if URN is invalid
 *
 * @example
 * ```typescript
 * const parsed = parseURN("urn:vreko:core:snapshot:1.0.0");
 * // { namespace: "vreko", pluginId: "core", capability: "snapshot", version: "1.0.0" }
 * ```
 */
export function parseURN(urn) {
    const validated = ToolURNSchema.parse(urn);
    const parts = validated.split(":");
    if (parts.length !== 5) {
        throw new Error(`Invalid URN structure: expected 5 parts, got ${parts.length}`);
    }
    const [, namespace, pluginId, capability, version] = parts;
    const majorVersion = Number.parseInt(version.split(".")[0], 10);
    return {
        urn: validated,
        namespace: namespace,
        pluginId,
        capability,
        version,
        majorVersion,
    };
}
/**
 * Build a URN from components
 *
 * @param options - URN components
 * @returns Validated URN string
 *
 * @example
 * ```typescript
 * const urn = buildURN({
 *   namespace: "vreko",
 *   pluginId: "core",
 *   capability: "snapshot",
 *   version: "1.0.0"
 * });
 * // "urn:vreko:core:snapshot:1.0.0"
 * ```
 */
export function buildURN(options) {
    const { namespace, pluginId, capability, version } = options;
    // Validate individual components
    if (!URN_NAMESPACES.includes(namespace)) {
        throw new Error(`Invalid namespace: ${namespace}. Must be one of: ${URN_NAMESPACES.join(", ")}`);
    }
    if (!/^[\w-]+$/.test(pluginId)) {
        throw new Error(`Invalid pluginId: ${pluginId}. Must contain only alphanumeric, underscore, or hyphen`);
    }
    if (!/^[\w-]+$/.test(capability)) {
        throw new Error(`Invalid capability: ${capability}. Must contain only alphanumeric, underscore, or hyphen`);
    }
    SemverSchema.parse(version);
    const urn = `urn:${namespace}:${pluginId}:${capability}:${version}`;
    return ToolURNSchema.parse(urn);
}
/**
 * Check if a URN is valid
 *
 * @param urn - String to validate
 * @returns True if valid URN format
 */
export function isValidURN(urn) {
    const result = ToolURNSchema.safeParse(urn);
    return result.success;
}
/**
 * Check if two URNs are compatible (same major version)
 *
 * @param urn1 - First URN
 * @param urn2 - Second URN
 * @returns True if URNs have matching namespace, plugin, capability, and major version
 */
export function areURNsCompatible(urn1, urn2) {
    const parsed1 = parseURN(urn1);
    const parsed2 = parseURN(urn2);
    return (parsed1.namespace === parsed2.namespace &&
        parsed1.pluginId === parsed2.pluginId &&
        parsed1.capability === parsed2.capability &&
        parsed1.majorVersion === parsed2.majorVersion);
}
/**
 * Get the base URN without version (for registry lookups)
 *
 * @param urn - Full URN
 * @returns Base URN pattern
 *
 * @example
 * ```typescript
 * getBaseURN("urn:vreko:core:snapshot:1.0.0")
 * // "urn:vreko:core:snapshot"
 * ```
 */
export function getBaseURN(urn) {
    const parsed = parseURN(urn);
    return `urn:${parsed.namespace}:${parsed.pluginId}:${parsed.capability}`;
}
/**
 * Resolve a URN pattern to the latest compatible version
 * Used when a client requests a capability without a specific version
 *
 * @param basePattern - Base URN without version (e.g., "urn:vreko:core:snapshot")
 * @param registry - Available URNs in registry
 * @returns Latest compatible URN or null if not found
 */
export function resolveLatestURN(basePattern, registry) {
    const matching = registry
        .filter((urn) => urn.startsWith(basePattern))
        .map((urn) => parseURN(urn))
        .sort((a, b) => {
        // Sort by version descending (latest first)
        const [aMajor, aMinor, aPatch] = a.version.split(".").map(Number);
        const [bMajor, bMinor, bPatch] = b.version.split(".").map(Number);
        if (aMajor !== bMajor) {
            return bMajor - aMajor;
        }
        if (aMinor !== bMinor) {
            return bMinor - aMinor;
        }
        return bPatch - aPatch;
    });
    return matching[0]?.urn ?? null;
}
/**
 * Extract namespace from URN (fast path for filtering)
 *
 * @param urn - URN string
 * @returns Namespace or null if invalid
 */
export function extractNamespace(urn) {
    const match = urn.match(/^urn:(vreko|openclaw|community|enterprise):/);
    return match ? match[1] : null;
}
/**
 * Create a URN pattern matcher for filtering
 *
 * @param pattern - Pattern with optional wildcards
 * @returns Matcher function
 *
 * @example
 * ```typescript
 * const matcher = createURNMatcher("urn:vreko:*:*:*");
 * matcher("urn:vreko:core:snapshot:1.0.0") // true
 * matcher("urn:openclaw:telegram:send:1.0.0") // false
 * ```
 */
export function createURNMatcher(pattern) {
    // Convert pattern to regex
    const regexPattern = pattern
        .replace(/[.+?^${}()|[\]\\]/g, "\\$&") // Escape special chars
        .replace(/\*/g, "[\\w.-]+"); // Replace * with word chars including dots for version matching
    const regex = new RegExp(`^${regexPattern}$`);
    return (urn) => regex.test(urn);
}
