/**
 * Minimal logging interface for public packages
 *
 * This interface allows public packages (@vreko/sdk, @vreko/core, @vreko/mcp-server)
 * to log without depending on the private @vreko/infrastructure package.
 *
 * Browser-safe: No dynamic requires, no node:fs dependencies
 * Server packages can enhance this with infrastructure logger via DI using registerLoggerFactory()
 *
 * Private packages can use the full @vreko/infrastructure implementation,
 * which provides advanced features like structured logging, log levels, etc.
 */
// Global logger factory registry for server-side enhancement
let _loggerFactory = null;
/**
 * Register an enhanced logger factory (called by server packages)
 * This allows @vreko/infrastructure to enhance logging without
 * being a compile-time dependency.
 *
 * @example
 * ```typescript
 * // In @vreko/infrastructure/src/index.ts
 * import { registerLoggerFactory } from '@vreko/contracts'
 * registerLoggerFactory((options) => createPinoLogger(options))
 * ```
 */
export function registerLoggerFactory(factory) {
    _loggerFactory = factory;
}
/**
 * Get the registered logger factory, if any
 * @internal
 */
function getLoggerFactory() {
    return _loggerFactory;
}
/**
 * Log levels
 */
export var LogLevel;
(function (LogLevel) {
    LogLevel[LogLevel["DEBUG"] = 0] = "DEBUG";
    LogLevel[LogLevel["INFO"] = 1] = "INFO";
    LogLevel[LogLevel["WARN"] = 2] = "WARN";
    LogLevel[LogLevel["ERROR"] = 3] = "ERROR";
    LogLevel[LogLevel["SILENT"] = 4] = "SILENT";
})(LogLevel || (LogLevel = {}));
/**
 * Enhanced logger that uses registered factory when available,
 * otherwise falls back to minimal console-based implementation
 *
 * @example
 * ```typescript
 * import { createLogger } from '@vreko/contracts'
 *
 * const logger = createLogger({ name: 'sdk' })
 * logger.info('SDK initialized')
 * logger.error('Failed to create snapshot', { error: err })
 * ```
 */
export function createLogger(options) {
    // If a logger factory has been registered (by @vreko/infrastructure), use it
    const factory = getLoggerFactory();
    if (factory) {
        return factory(options);
    }
    // Fallback to minimal console implementation
    const { name, level = LogLevel.INFO, timestamps = false } = options;
    const _formatMessage = (levelStr, message) => {
        const prefix = timestamps ? `[${new Date().toISOString()}] ` : "";
        return `${prefix}[${name}] ${levelStr}: ${message}`;
    };
    const _formatMeta = (meta) => {
        if (!meta) {
            return "";
        }
        if (meta instanceof Error) {
            return `\n  Error: ${meta.message}\n  Stack: ${meta.stack}`;
        }
        try {
            return `
  ${JSON.stringify(meta, null, 2)}`;
        }
        catch {
            return "\n  [Circular or non-serializable metadata]";
        }
    };
    return {
        debug(messageOrObj, metaOrMsg) {
            if (level <= LogLevel.DEBUG) {
                if (typeof messageOrObj === "string" && (!metaOrMsg || typeof metaOrMsg === "object")) {
                    /* silent logger: no output */
                }
                else if (typeof messageOrObj === "object" && typeof metaOrMsg === "string") {
                    /* silent logger: no output */
                }
            }
        },
        info(messageOrObj, metaOrMsg) {
            if (level <= LogLevel.INFO) {
                if (typeof messageOrObj === "string" && (!metaOrMsg || typeof metaOrMsg === "object")) {
                    /* silent logger: no output */
                }
                else if (typeof messageOrObj === "object" && typeof metaOrMsg === "string") {
                    /* silent logger: no output */
                }
            }
        },
        warn(messageOrObj, metaOrMsg) {
            if (level <= LogLevel.WARN) {
                if (typeof messageOrObj === "string" && (!metaOrMsg || typeof metaOrMsg === "object")) {
                    /* silent logger: no output */
                }
                else if (typeof messageOrObj === "object" && typeof metaOrMsg === "string") {
                    /* silent logger: no output */
                }
            }
        },
        error(messageOrObj, metaOrMsg) {
            if (level <= LogLevel.ERROR) {
                if (typeof messageOrObj === "string" && (!metaOrMsg || typeof metaOrMsg !== "string")) {
                    /* silent logger: no output */
                }
                else if (typeof messageOrObj === "object" && typeof metaOrMsg === "string") {
                    /* silent logger: no output */
                }
            }
        },
    };
}
/**
 * No-op logger (silences all logs)
 *
 * Useful for testing or when logs should be completely disabled.
 */
export function createSilentLogger() {
    return {
        debug: () => {
            /* intentionally empty for silent logger */
        },
        info: () => {
            /* intentionally empty for silent logger */
        },
        warn: () => {
            /* intentionally empty for silent logger */
        },
        error: () => {
            /* intentionally empty for silent logger */
        },
    };
}
