/**
 * Verdict Claim Family
 *
 * Claims about judgment: "I judged this artifact to be in state X."
 *
 * Examples:
 * - Drift Detector claiming code drift is detected
 * - Risk scorer claiming a file is high-risk
 * - Code reviewer claiming a PR needs changes
 */
import { z } from "zod";
import { BaseClaim } from "../base.js";
// =============================================================================
// Verdict Status
// =============================================================================
/**
 * Verdict status values.
 */
export const VerdictStatus = z.enum(["pass", "fail", "needs-review", "drift-detected", "clean", "suspect"]);
// =============================================================================
// Verdict Claim Schema
// =============================================================================
/**
 * Verdict claim  -  asserts a judgment about an artifact.
 *
 * Confidence: optional [0,1] (used for calibration analysis)
 * Resolution: deferred-manual (evaluated when artifact state changes, e.g., PR merged)
 */
export const VerdictClaim = BaseClaim.extend({
    claimFamily: z.literal("verdict"),
    // Verdict-specific payload
    claim: z.object({
        status: VerdictStatus,
        details: z.string().optional(),
        criteria: z.array(z.string()).default([]),
        severity: z.enum(["info", "low", "medium", "high", "critical"]).optional(),
    }),
});
// =============================================================================
// Type Guards
// =============================================================================
/**
 * Check if a claim is a verdict claim.
 */
export function isVerdictClaim(claim) {
    return VerdictClaim.safeParse(claim).success;
}
/**
 * Validate and parse a verdict claim.
 */
export function parseVerdictClaim(claim) {
    const result = VerdictClaim.safeParse(claim);
    return result.success ? result.data : null;
}
