/**
 * Prediction Claim Family
 *
 * Claims about future outcomes: "I predict outcome Y about subject Z."
 *
 * Examples:
 * - Intelligence predicting a file will have rollbacks in next 30 days
 * - Risk scorer predicting a commit will introduce bugs
 * - Fragility detector predicting a component will fail
 */
import { z } from "zod";
import { BaseClaim } from "../base.js";
// =============================================================================
// Prediction Outcome Types
// =============================================================================
/**
 * Types of outcomes that can be predicted.
 */
export const PredictedOutcomeType = z.enum([
    "rollback",
    "bug-introduced",
    "performance-degradation",
    "security-issue",
    "drift",
    "failure",
    "success",
]);
// =============================================================================
// Prediction Time Window
// =============================================================================
/**
 * Time window for the prediction.
 */
export const PredictionWindow = z.object({
    days: z.number().int().positive(),
    since: z.number().int().positive().optional(), // Unix timestamp
});
// =============================================================================
// Prediction Claim Schema
// =============================================================================
/**
 * Prediction claim  -  asserts a future outcome.
 *
 * Confidence: REQUIRED [0,1] (prediction is probabilistic)
 * Resolution: deferred-observational (evaluated by observing actual outcomes)
 */
export const PredictionClaim = BaseClaim.extend({
    claimFamily: z.literal("prediction"),
    // Predictions require confidence per spec
    confidence: z.number().min(0).max(1),
    // Prediction-specific payload
    claim: z.object({
        outcomeType: PredictedOutcomeType,
        window: PredictionWindow,
        rationale: z.string().optional(),
        modelVersion: z.string().optional(), // Version of prediction model
    }),
});
// =============================================================================
// Type Guards
// =============================================================================
/**
 * Check if a claim is a prediction claim.
 */
export function isPredictionClaim(claim) {
    return PredictionClaim.safeParse(claim).success;
}
/**
 * Validate and parse a prediction claim.
 */
export function parsePredictionClaim(claim) {
    const result = PredictionClaim.safeParse(claim);
    return result.success ? result.data : null;
}
