/**
 * Spine Event Attribution - ADR-007 §3.2
 *
 * Discriminated union for attributing spine events to tools, users, systems,
 * or unknown sources. This enables privacy-preserving attribution tracking
 * while maintaining tier-appropriate data collection.
 *
 * @module @vreko/contracts/events/spine/attribution
 * @see ADR-007 Runtime Tier Boundaries and Export Spine Contract
 */
import { z } from "zod";
// =============================================================================
// Tool URN Pattern
// =============================================================================
/**
 * URN format for AI tool identification
 * Pattern: urn:ai-tool:<vendor>:<version>
 * Examples:
 *   - urn:ai-tool:claude-code:1.0
 *   - urn:ai-tool:github-copilot:1.0
 *   - urn:ai-tool:cursor:0.40
 */
const toolUrnPattern = /^urn:ai-tool:[a-z0-9-]+:\d+\.\d+$/;
/**
 * Zod schema for AI tool URN validation
 */
export const toolUrnSchema = z
    .string()
    .regex(toolUrnPattern, "Invalid tool URN format. Expected: urn:ai-tool:<vendor>:<version>")
    .max(64, "Tool URN must be ≤64 characters");
// =============================================================================
// Attribution Sources
// =============================================================================
/**
 * Sources for AI tool attribution (§3.2)
 */
export const attributionSourceSchema = z.enum([
    "fingerprint", // Tool signature detected in content
    "session-correlation", // Correlated with known AI session
    "temporal", // Timing patterns suggest AI involvement
    "mcp-direct", // Direct MCP protocol attribution
]);
// =============================================================================
// Attribution Discriminated Union (§3.2)
// =============================================================================
/**
 * AI tool attribution
 */
export const toolAttributionSchema = z.object({
    kind: z.literal("tool"),
    /** Tool URN (e.g., urn:ai-tool:claude-code:1.0) */
    toolUrn: toolUrnSchema,
    /** Confidence score 0.0-1.0 */
    confidence: z.number().min(0).max(1),
    /** Attribution source method */
    source: attributionSourceSchema,
});
/**
 * User attribution (user authored without AI mediation)
 */
export const userAttributionSchema = z.object({
    kind: z.literal("user"),
    /** User authored the change without AI mediation */
    description: z.literal("user authored the change without AI mediation").optional(),
});
/**
 * System attribution (automated/scheduled operations)
 */
export const systemAttributionSchema = z.object({
    kind: z.literal("system"),
    /** System operation source */
    source: z.enum(["scheduled", "startup", "shutdown", "gc"]),
});
/**
 * Unknown attribution (insufficient signal)
 */
export const unknownAttributionSchema = z.object({
    kind: z.literal("unknown"),
    /** Signal was insufficient to attribute; emitted rather than dropped */
    description: z.literal("signal was insufficient to attribute").optional(),
});
// =============================================================================
// Combined Attribution Schema
// =============================================================================
/**
 * Attribution discriminated union for all spine events (§3.2).
 *
 * This union enables type-safe handling of different attribution kinds
 * using TypeScript's discriminated union narrowing.
 *
 * @example
 * ```typescript
 * function handleAttribution(attribution: Attribution) {
 *   switch (attribution.kind) {
 *     case "tool":
 *       return processToolAttribution(attribution.toolUrn, attribution.confidence);
 *     case "user":
 *       return processUserAttribution();
 *     case "system":
 *       return processSystemAttribution(attribution.source);
 *     case "unknown":
 *       return processUnknownAttribution();
 *   }
 * }
 * ```
 */
export const attributionSchema = z.discriminatedUnion("kind", [
    toolAttributionSchema,
    userAttributionSchema,
    systemAttributionSchema,
    unknownAttributionSchema,
]);
// =============================================================================
// Attribution Factory Functions
// =============================================================================
/**
 * Creates tool attribution.
 *
 * @param toolUrn - Tool URN (e.g., "urn:ai-tool:claude-code:1.0")
 * @param confidence - Attribution confidence 0.0-1.0
 * @param source - Attribution source method
 * @returns Validated tool attribution
 */
export function createToolAttribution(toolUrn, confidence, source) {
    return toolAttributionSchema.parse({
        kind: "tool",
        toolUrn,
        confidence,
        source,
    });
}
/**
 * Creates user attribution.
 *
 * @returns Validated user attribution
 */
export function createUserAttribution() {
    return userAttributionSchema.parse({
        kind: "user",
    });
}
/**
 * Creates system attribution.
 *
 * @param source - System operation source
 * @returns Validated system attribution
 */
export function createSystemAttribution(source) {
    return systemAttributionSchema.parse({
        kind: "system",
        source,
    });
}
/**
 * Creates unknown attribution.
 *
 * @returns Validated unknown attribution
 */
export function createUnknownAttribution() {
    return unknownAttributionSchema.parse({
        kind: "unknown",
    });
}
// =============================================================================
// Attribution Confidence Levels (§3.2)
// =============================================================================
/**
 * Standard confidence thresholds for attribution
 */
export const AttributionConfidence = {
    /** Low confidence - may need manual review */
    LOW: 0.5,
    /** Medium confidence - likely correct */
    MEDIUM: 0.7,
    /** High confidence - reliable for automated decisions */
    HIGH: 0.85,
    /** Very high confidence - suitable for critical decisions */
    VERY_HIGH: 0.95,
};
/**
 * Checks if confidence meets threshold.
 *
 * @param confidence - Attribution confidence value
 * @param threshold - Threshold to check against
 * @returns True if confidence meets or exceeds threshold
 */
export function meetsConfidenceThreshold(confidence, threshold) {
    return confidence >= threshold;
}
// =============================================================================
// Attribution Validation
// =============================================================================
/**
 * Validates any attribution type against the discriminated union schema.
 *
 * @param attribution - Attribution to validate
 * @returns Validated attribution or throws ZodError
 */
export function validateAttribution(attribution) {
    return attributionSchema.parse(attribution);
}
/**
 * Safe attribution validation that returns result or error.
 *
 * @param attribution - Attribution to validate
 * @returns Object with success flag and result or error
 */
export function safeValidateAttribution(attribution) {
    const result = attributionSchema.safeParse(attribution);
    if (result.success) {
        return { success: true, data: result.data };
    }
    return { success: false, error: result.error };
}
