/**
 * Canonical Pioneer activation event names.
 *
 * IMPORTANT: PostHog dashboard funnel "Pioneer Activation" must use
 * these exact event names. Drift between this constant and the funnel
 * results in zero-event funnels.
 *
 * Order matches the seven-step activation funnel:
 *   invite_code_redeemed → cli_installed → extension_installed →
 *   first_session → first_snapshot → first_ceremony →
 *   first_intelligence_file_card
 */
export const PIONEER_EVENTS = {
    INVITE_CODE_REDEEMED: "invite_code_redeemed",
    CLI_INSTALLED: "cli_installed",
    EXTENSION_INSTALLED: "extension_installed",
    FIRST_SESSION: "first_session",
    FIRST_SNAPSHOT: "first_snapshot",
    FIRST_CEREMONY: "first_ceremony",
    FIRST_INTELLIGENCE_FILE_CARD: "first_intelligence_file_card",
    FIRST_RECOVERY: "first_recovery",
};
