/**
 * Learning Domain Spine Events - ADR-007 §3
 *
 * Spine events for pattern learning and accumulation.
 * Event types use three-part naming: learning.<entity>.<action>
 *
 * @module @vreko/contracts/events/spine/domains/learning
 * @see ADR-007 Runtime Tier Boundaries and Export Spine Contract
 */
import { z } from "zod";
import { createSpineEventSchema } from "../envelope.js";
// =============================================================================
// Shared Learning Schemas
// =============================================================================
/**
 * Learning pattern types
 */
export const learningTypeSchema = z.enum([
    "recovery", // Recovery patterns
    "workflow", // Workflow patterns
    "risk", // Risk-related patterns
    "attribution", // Attribution patterns
    "tool-preference", // Tool preference patterns
]);
/**
 * Learning confidence levels
 */
export const learningConfidenceSchema = z.enum([
    "hypothesis", // Initial observation
    "emerging", // Multiple observations
    "established", // Consistent pattern
    "validated", // Validated through outcomes
]);
// =============================================================================
// learning.pattern.recorded
// =============================================================================
/**
 * Data payload for learning.pattern.recorded event
 */
export const learningPatternRecordedDataSchema = z.object({
    /** Pattern identifier */
    patternId: z.string().uuid(),
    /** Pattern type category */
    type: learningTypeSchema,
    /** Human-readable pattern description */
    description: z.string().min(1).max(1000),
    /** Pattern confidence level */
    confidence: learningConfidenceSchema,
    /** Occurrence count for this pattern */
    occurrenceCount: z.number().int().nonnegative(),
    /** First observed timestamp */
    firstObservedAt: z.number().int().positive(),
    /** Pattern features (hashed/anonymized) */
    featureHash: z.string().regex(/^[0-9a-f]{64}$/i),
    /** Whether pattern has been validated through outcomes */
    isValidated: z.boolean(),
});
/**
 * Spine event schema for learning.pattern.recorded
 *
 * Emitted when a new learning pattern is recorded.
 */
export const learningPatternRecordedSchema = createSpineEventSchema(learningPatternRecordedDataSchema);
/**
 * Event type constant
 */
export const LEARNING_PATTERN_RECORDED = "learning.pattern.recorded";
// =============================================================================
// learning.pattern.promoted
// =============================================================================
/**
 * Data payload for learning.pattern.promoted event
 */
export const learningPatternPromotedDataSchema = z.object({
    /** Pattern identifier */
    patternId: z.string().uuid(),
    /** Previous confidence level */
    previousConfidence: learningConfidenceSchema,
    /** New confidence level */
    newConfidence: learningConfidenceSchema,
    /** Number of occurrences at promotion time */
    occurrenceCount: z.number().int().positive(),
    /** Outcome ratio (successes / total) */
    outcomeRatio: z.number().min(0).max(1),
    /** Promotion timestamp */
    promotedAt: z.number().int().positive(),
});
/**
 * Spine event schema for learning.pattern.promoted
 *
 * Emitted when a pattern confidence is promoted.
 */
export const learningPatternPromotedSchema = createSpineEventSchema(learningPatternPromotedDataSchema);
/**
 * Event type constant
 */
export const LEARNING_PATTERN_PROMOTED = "learning.pattern.promoted";
// =============================================================================
// learning.pattern.pruned
// =============================================================================
/**
 * Data payload for learning.pattern.pruned event
 */
export const learningPatternPrunedDataSchema = z.object({
    /** Number of patterns pruned */
    count: z.number().int().nonnegative(),
    /** Pruning reason */
    reason: z.enum([
        "stale", // Not observed recently
        "low-confidence", // Never reached threshold
        "invalidated", // Contradicted by outcomes
        "redundant", // Duplicate of another pattern
    ]),
    /** Oldest pattern age at pruning in milliseconds */
    oldestPatternAgeMs: z.number().int().nonnegative(),
    /** Pruning timestamp */
    prunedAt: z.number().int().positive(),
});
/**
 * Spine event schema for learning.pattern.pruned
 *
 * Emitted when patterns are pruned from learning store.
 */
export const learningPatternPrunedSchema = createSpineEventSchema(learningPatternPrunedDataSchema);
/**
 * Event type constant
 */
export const LEARNING_PATTERN_PRUNED = "learning.pattern.pruned";
// =============================================================================
// learning.annotation.added
// =============================================================================
/**
 * Data payload for learning.annotation.added event
 */
export const learningAnnotationAddedDataSchema = z.object({
    /** Annotation identifier */
    annotationId: z.string().uuid(),
    /** Tag/category for the annotation */
    tag: z.string().min(1).max(100),
    /** Risk signal direction */
    riskSignal: z.object({
        direction: z.enum(["increasing", "decreasing", "stable"]),
        magnitude: z.number().min(0).max(1),
    }),
    /** Related snapshot hash */
    snapshotHash: z.string().regex(/^[0-9a-f]{64}$/i),
    /** Annotation timestamp */
    annotatedAt: z.number().int().positive(),
    /** Session ID if part of tracked session */
    sessionId: z.string().uuid().optional(),
});
/**
 * Spine event schema for learning.annotation.added
 *
 * Emitted when a learning annotation is added.
 */
export const learningAnnotationAddedSchema = createSpineEventSchema(learningAnnotationAddedDataSchema);
/**
 * Event type constant
 */
export const LEARNING_ANNOTATION_ADDED = "learning.annotation.added";
/**
 * All learning event type constants
 */
export const LEARNING_EVENT_TYPES = [
    LEARNING_PATTERN_RECORDED,
    LEARNING_PATTERN_PROMOTED,
    LEARNING_PATTERN_PRUNED,
    LEARNING_ANNOTATION_ADDED,
];
/**
 * Map of event types to their schemas for validation
 */
export const LEARNING_EVENT_SCHEMAS = {
    [LEARNING_PATTERN_RECORDED]: learningPatternRecordedSchema,
    [LEARNING_PATTERN_PROMOTED]: learningPatternPromotedSchema,
    [LEARNING_PATTERN_PRUNED]: learningPatternPrunedSchema,
    [LEARNING_ANNOTATION_ADDED]: learningAnnotationAddedSchema,
};
