import { z } from "zod";
/**
 * Protection levels for files
 * - watch: Silent auto-snapshot on save (green)
 * - warn: Show notification before save (yellow/orange)
 * - block: Require explicit snapshot or override (red)
 */
export const ProtectionLevelSchema = z.enum(["watch", "warn", "block"]);
/**
 * UI metadata for protection levels
 */
export const ProtectionLevelMetadataSchema = z.object({
    level: ProtectionLevelSchema,
    icon: z.string(),
    label: z.string(),
    description: z.string(),
    color: z.string(),
    themeColor: z.string().optional(),
});
/**
 * Protection level configurations with UI metadata
 */
export const PROTECTION_LEVELS = {
    watch: {
        level: "watch",
        icon: "🟢",
        label: "Watch",
        description: "Silent auto-snapshot on save",
        color: "#10B981",
        themeColor: "charts.green",
    },
    warn: {
        level: "warn",
        icon: "🟡",
        label: "Warn",
        description: "Notify before save with options",
        color: "#FF6B35",
        themeColor: "charts.orange",
    },
    block: {
        level: "block",
        icon: "🔴",
        label: "Block",
        description: "Require snapshot or explicit override",
        color: "#EF4444",
        themeColor: "charts.red",
    },
};
/**
 * Protected file entry
 */
export const ProtectedFileSchema = z.object({
    path: z.string(),
    level: ProtectionLevelSchema,
    reason: z.string().optional(),
    addedAt: z.date(),
    pattern: z.string().optional(), // If added via pattern match
});
/**
 * Pattern rule for automatic protection
 */
export const PatternRuleSchema = z.object({
    pattern: z.string(),
    level: ProtectionLevelSchema,
    reason: z.string().optional(),
    enabled: z.boolean().default(true),
});
/**
 * Protection configuration
 */
export const ProtectionConfigSchema = z.object({
    patterns: z.array(PatternRuleSchema).default([]),
    defaultLevel: ProtectionLevelSchema.default("watch"),
    enabled: z.boolean().default(true),
    autoProtectConfigs: z.boolean().default(true),
});
/**
 * Protection manager options
 */
export const ProtectionManagerOptionsSchema = z.object({
    config: ProtectionConfigSchema.optional(),
    persistRegistry: z.boolean().default(true),
    registryPath: z.string().optional(),
});
/**
 * Protection check result
 */
export const ProtectionCheckResultSchema = z.object({
    isProtected: z.boolean(),
    level: ProtectionLevelSchema.optional(),
    reason: z.string().optional(),
    file: ProtectedFileSchema.optional(),
});
// =============================================================================
// Default Protection Patterns
// =============================================================================
/**
 * CRITICAL PATTERNS - Files where accidental changes cause IMMEDIATE PRODUCTION IMPACT
 * These are the patterns that should be protected by default
 * Total: ~15-20 patterns matching ~27 files in typical project
 */
export const DEFAULT_CRITICAL_PATTERNS = Object.freeze([
    // Dependency locks - wrong versions break builds
    {
        pattern: "**/package-lock.json",
        level: "block",
        reason: "Lock file - wrong version breaks reproducible Node.js builds",
    },
    {
        pattern: "**/yarn.lock",
        level: "block",
        reason: "Lock file - ensures reproducible Yarn installs",
    },
    {
        pattern: "**/pnpm-lock.yaml",
        level: "block",
        reason: "Lock file - critical for pnpm monorepos",
    },
    {
        pattern: "**/poetry.lock",
        level: "block",
        reason: "Lock file - Python dependency lock",
    },
    {
        pattern: "**/Cargo.lock",
        level: "block",
        reason: "Lock file - Rust dependency lock",
    },
    {
        pattern: "**/go.sum",
        level: "block",
        reason: "Lock file - Go module checksums",
    },
    {
        pattern: "**/Gemfile.lock",
        level: "block",
        reason: "Lock file - Ruby gem dependencies",
    },
    {
        pattern: "**/composer.lock",
        level: "block",
        reason: "Lock file - PHP composer dependencies",
    },
    // Environment & Secrets - exposing causes immediate security breaches
    {
        pattern: "**/.env*",
        level: "block",
        reason: "Sensitive environment variables and secrets",
    },
    // Core configuration files - wrong changes break builds
    {
        pattern: "package.json",
        level: "warn",
        reason: "Core Node.js configuration - dependencies and scripts",
    },
    {
        pattern: "tsconfig.json",
        level: "warn",
        reason: "TypeScript compiler configuration",
    },
    // Infrastructure - controls deployment and infrastructure
    {
        pattern: "Dockerfile",
        level: "warn",
        reason: "Container image definition",
    },
    {
        pattern: "docker-compose.yml",
        level: "warn",
        reason: "Multi-container orchestration",
    },
    {
        pattern: "**/docker-compose.yaml",
        level: "warn",
        reason: "Multi-container orchestration (yaml variant)",
    },
    {
        pattern: "**/*.tf",
        level: "warn",
        reason: "Terraform infrastructure definitions",
    },
    {
        pattern: ".github/workflows/*.yml",
        level: "warn",
        reason: "GitHub Actions CI/CD workflows",
    },
    {
        pattern: ".github/workflows/*.yaml",
        level: "warn",
        reason: "GitHub Actions CI/CD workflows (yaml variant)",
    },
]);
