import { z } from "zod";
// Persisted to ~/.vreko/daemon-state.json
// Owned exclusively by the daemon. CLI never reads or writes this file.
export const DaemonStateSchema = z.object({
    version: z.literal("1").default("1"),
    lastIdentityValidatedAt: z.coerce.date().nullable().default(null),
    startCount: z.number().int().default(0), // useful for debugging restart loops
    lastStartedAt: z.coerce.date().nullable().default(null),
});
