/**
 * Tier Definitions - Single Source of Truth for Alpha
 *
 * Alpha Scope: Free and Pro tiers are ACTIVE
 * Team and Enterprise are designed stubs (feature flag gated)
 */
/**
 * Environment variable to bypass tier restrictions (dev/testing)
 * Set VREKO_BYPASS_TIER_RESTRICTIONS=true to grant Pro capabilities to all users
 */
export function isTierBypassEnabled() {
    return process.env.VREKO_BYPASS_TIER_RESTRICTIONS === "true";
}
/**
 * Get the effective tier accounting for bypass mode
 * Returns 'pro' if bypass is enabled, otherwise returns the actual tier
 */
export function getEffectiveTier(actualTier) {
    if (isTierBypassEnabled()) {
        return "pro";
    }
    return actualTier;
}
/**
 * Active tiers for Alpha release
 * Used by docs PlanSwitcher and feature gating
 */
export const ALPHA_ACTIVE_TIERS = ["free", "pro"];
/**
 * Feature flag: Team/Enterprise features disabled in Alpha
 * Hardcoded to false - will be environment variable post-Alpha
 */
export const ENABLE_TEAM_FEATURES = false;
/**
 * Tier capabilities matrix (all tiers defined for future use)
 */
export const TIER_CAPABILITIES = {
    free: {
        seats: 1,
        cloudBackup: false,
        backendMCP: false,
        maxSnapshots: -1, // unlimited local
        storageMB: 0, // local only
        retentionDays: 7, // local retention
    },
    pro: {
        seats: 1,
        cloudBackup: true,
        backendMCP: true,
        maxSnapshots: -1, // unlimited
        storageMB: 5 * 1024, // 5GB
        retentionDays: 30,
    },
    team: {
        seats: -1, // unlimited seats
        cloudBackup: true,
        backendMCP: true,
        maxSnapshots: -1, // unlimited
        storageMB: 25 * 1024, // 25GB per user
        retentionDays: 365, // 1 year
    },
    enterprise: {
        seats: -1, // unlimited
        cloudBackup: true,
        backendMCP: true,
        maxSnapshots: -1, // unlimited
        storageMB: 100 * 1024, // 100GB+
        retentionDays: -1, // custom
    },
};
/**
 * Check if tier is active in Alpha
 */
export function isAlphaActiveTier(tier) {
    return ALPHA_ACTIVE_TIERS.includes(tier);
}
/**
 * Get tier capabilities with validation
 * Respects VREKO_BYPASS_TIER_RESTRICTIONS env var
 */
export function getTierCapabilities(tier) {
    // Apply tier bypass if enabled
    const effectiveTier = getEffectiveTier(tier);
    const capabilities = TIER_CAPABILITIES[effectiveTier];
    if (!capabilities) {
        throw new Error(`Invalid tier: ${effectiveTier}`);
    }
    // Alpha: Warn if accessing inactive tier
    if (!isAlphaActiveTier(effectiveTier)) {
        /* future: emit warning for inactive tier access */
    }
    return capabilities;
}
/**
 * Check if tier has specific capability
 * Respects VREKO_BYPASS_TIER_RESTRICTIONS env var
 */
export function hasTierCapability(tier, capability) {
    // getTierCapabilities already applies bypass
    const caps = getTierCapabilities(tier);
    return caps[capability];
}
