/**
 * Attribution Claim Family
 *
 * Claims about causation: "I assert this change was caused by tool X."
 *
 * Examples:
 * - Tool-identity claiming a change was AI-authored
 * - Intelligence system attributing a bug to a specific tool
 * - Drift Detector attributing drift to a particular pattern
 */
import { z } from "zod";
import { BaseClaim } from "../base.js";
// =============================================================================
// Attribution Source
// =============================================================================
/**
 * Attribution source kinds.
 */
export const AttributionSource = z.enum(["ai-tool", "human", "automation", "import", "unknown"]);
// =============================================================================
// Attribution Claim Schema
// =============================================================================
/**
 * Attribution claim  -  asserts what caused a change.
 *
 * Confidence: REQUIRED [0,1] (matches ADR-007 V2 attribution schema)
 * Resolution: deferred-observational (evaluated by observing outcomes of attributed changes)
 */
export const AttributionClaim = BaseClaim.extend({
    claimFamily: z.literal("attribution"),
    // Attribution requires confidence per spec
    confidence: z.number().min(0).max(1),
    // Attribution-specific payload
    claim: z.object({
        source: AttributionSource,
        toolUrn: z.string().optional(), // e.g., "urn:tool:cursor"
        confidenceRationale: z.string().optional(), // Why this confidence level
        indicators: z.array(z.string()).default([]), // Evidence indicators detected
    }),
});
// =============================================================================
// Type Guards
// =============================================================================
/**
 * Check if a claim is an attribution claim.
 */
export function isAttributionClaim(claim) {
    return AttributionClaim.safeParse(claim).success;
}
/**
 * Validate and parse an attribution claim.
 */
export function parseAttributionClaim(claim) {
    const result = AttributionClaim.safeParse(claim);
    return result.success ? result.data : null;
}
