/**
 * Spine Event Envelope - ADR-007 §3.1
 *
 * Required envelope fields for every spine event transmitted from Tier 2 → Tier 3.
 * All spine events must include this envelope to ensure privacy, versioning,
 * and attribution integrity.
 *
 * @module @vreko/contracts/events/spine/envelope
 * @see ADR-007 Runtime Tier Boundaries and Export Spine Contract
 */
import { z } from "zod";
import { attributionSchema } from "./attribution.js";
// =============================================================================
// UUIDv7 Validation Helper
// =============================================================================
/**
 * Validates UUIDv7 format (used for eventId ordering + dedup)
 * UUIDv7 format: 8-4-4-4-12 with specific bit patterns for timestamp
 */
const uuidv7Pattern = /^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
/**
 * Zod schema for UUIDv7 validation
 */
export const uuidv7Schema = z
    .string()
    .regex(uuidv7Pattern, "Invalid UUIDv7 format. Expected: xxxxxxxx-xxxx-7xxx-8xxx-xxxxxxxxxxxx");
// =============================================================================
// SHA-256 Hash Validation
// =============================================================================
/**
 * SHA-256 produces 64 hex characters
 */
const sha256Pattern = /^[0-9a-f]{64}$/i;
/**
 * Zod schema for SHA-256 hash validation
 * Used for workspaceHash, filePathHash, userHash, orgHash
 */
export const sha256Schema = z.string().regex(sha256Pattern, "Invalid SHA-256 hash format. Expected: 64 hex characters");
// =============================================================================
// Event Type Naming Convention
// =============================================================================
/**
 * Domain.Entity.Action pattern validation
 * Examples: snapshot.blob.created, session.lifecycle.ended
 */
const eventTypePattern = /^[a-z][a-z0-9-]*\.[a-z][a-z0-9-]*\.[a-z][a-z0-9-]*$/;
/**
 * Zod schema for event type validation (§3.3)
 */
export const eventTypeSchema = z
    .string()
    .regex(eventTypePattern, "Invalid event type format. Expected: domain.entity.action (e.g., snapshot.blob.created)")
    .max(64, "Event type must be ≤64 characters");
// =============================================================================
// Event Priority Levels
// =============================================================================
/**
 * Event priority for batching decisions (§3.1, S2)
 */
export const eventPrioritySchema = z.enum(["immediate", "normal", "batch"]);
// =============================================================================
// Spine Envelope Schema (§3.1)
// =============================================================================
/**
 * Required envelope schema for all spine events.
 *
 * Invariants:
 * - M5: Every spine event carries this envelope
 * - M7: workspaceHash replaces raw workspace path
 * - M9: schemaVersion increments on breaking changes
 */
export const spineEnvelopeSchema = z.object({
    /** UUIDv7 for ordering + deduplication */
    eventId: uuidv7Schema,
    /** Integer schema version; increments on breaking change (M9) */
    schemaVersion: z.number().int().positive(),
    /** Domain.Entity.Action naming convention (§3.3) */
    eventType: eventTypeSchema,
    /** Unix timestamp in milliseconds (daemon-local clock) */
    occurredAt: z.number().int().positive(),
    /** SHA-256 of workspace path (M7) */
    workspaceHash: sha256Schema,
    /** Attribution discriminated union (§3.2) */
    attribution: attributionSchema,
});
// =============================================================================
// Optional Spine Fields (§3.4)
// =============================================================================
/**
 * Optional fields schema for spine events.
 * These extend the envelope based on tier and event type.
 */
export const spineOptionalFieldsSchema = z.object({
    /** Session identifier when operation is session-bound (S1) */
    sessionId: z.string().uuid().optional(),
    /** SHA-256 of userId; present only for Pro+ (M7) */
    userHash: sha256Schema.optional(),
    /** SHA-256 of orgId; present only for Team+ (M7) */
    orgHash: sha256Schema.optional(),
    /** SHA-256 of file path; never raw path (M7, N3) */
    filePathHash: sha256Schema.optional(),
});
/**
 * Schema builder for complete spine events with typed data.
 *
 * @param dataSchema - Zod schema for the event-specific data
 * @returns Complete spine event schema
 *
 * @example
 * ```typescript
 * const snapshotCreatedSchema = createSpineEventSchema(z.object({
 *   snapshotHash: z.string(),
 *   sizeBytes: z.number().int(),
 * }));
 * ```
 */
export function createSpineEventSchema(dataSchema) {
    return spineEnvelopeSchema.merge(spineOptionalFieldsSchema).merge(z.object({
        data: dataSchema,
    }));
}
// =============================================================================
// Envelope Factory
// =============================================================================
/**
 * Creates a spine envelope with the required fields.
 *
 * @param params - Envelope parameters
 * @returns Validated spine envelope
 */
export function createSpineEnvelope(params) {
    return spineEnvelopeSchema.parse({
        occurredAt: Date.now(),
        ...params,
    });
}
// =============================================================================
// Validation Helpers
// =============================================================================
/**
 * Validates a complete spine event against its schema.
 *
 * @param schema - Zod schema for the specific spine event type
 * @param event - Event to validate
 * @returns Validated event or throws ZodError
 */
export function validateSpineEvent(schema, event) {
    return schema.parse(event);
}
/**
 * Safe validation that returns result or error instead of throwing.
 *
 * @param schema - Zod schema for the specific spine event type
 * @param event - Event to validate
 * @returns Object with success flag and result or error
 */
export function safeValidateSpineEvent(schema, event) {
    const result = schema.safeParse(event);
    if (result.success) {
        return { success: true, data: result.data };
    }
    return { success: false, error: result.error };
}
