/**
 * File Lease Primitives
 *
 * Types and utilities for multi-agent file coordination.
 * Prevents concurrent modifications to the same files by different agents.
 *
 * The lease system ensures:
 * 1. Only one agent can modify a file at a time
 * 2. Leases have TTL to prevent deadlocks
 * 3. Leases can be extended if work takes longer
 * 4. Conflicts are detected before execution begins
 *
 * @module primitives/file-lease
 */
import { z } from "zod";
import { AGENT_RUNTIMES } from "./tool-invocation.js";
/**
 * Lease acquisition result
 */
export const LeaseResultSchema = z.object({
    /** Whether the lease was acquired */
    acquired: z.boolean(),
    /** Lease ID if acquired */
    leaseId: z.string().optional(),
    /** Reason if not acquired */
    reason: z.string().optional(),
    /** Conflicting leases if acquisition failed */
    conflicts: z
        .array(z.object({
        leaseId: z.string(),
        files: z.array(z.string()),
        heldBy: z.object({
            agentRuntime: z.enum(AGENT_RUNTIMES),
            sessionId: z.string(),
        }),
        expiresAt: z.coerce.date(),
    }))
        .optional(),
});
/**
 * Conflict detection result
 */
export const ConflictResultSchema = z.object({
    /** Whether there are conflicts */
    hasConflicts: z.boolean(),
    /** Conflicting files grouped by lease */
    conflicts: z.array(z.object({
        leaseId: z.string(),
        files: z.array(z.string()),
        heldBy: z.object({
            agentRuntime: z.enum(AGENT_RUNTIMES),
            sessionId: z.string(),
        }),
        expiresAt: z.coerce.date(),
        /** Whether this conflict is blocking (cannot proceed) */
        blocking: z.boolean(),
    })),
    /** Files that are safe to modify */
    safeFiles: z.array(z.string()),
    /** Files that are blocked */
    blockedFiles: z.array(z.string()),
});
/**
 * File lease record
 */
export const FileLeaseSchema = z.object({
    /** Unique lease identifier */
    leaseId: z.string(),
    /** Workspace this lease belongs to */
    workspaceId: z.string(),
    /** Files covered by this lease */
    files: z.array(z.string()),
    /** Agent that holds this lease */
    agentRuntime: z.enum(AGENT_RUNTIMES),
    /** Session that holds this lease */
    sessionId: z.string(),
    /** Trace ID for correlation */
    traceId: z.string().optional(),
    /** When the lease was acquired */
    acquiredAt: z.coerce.date(),
    /** When the lease expires */
    expiresAt: z.coerce.date(),
    /** Time-to-live in milliseconds */
    ttlMs: z.number().positive(),
    /** Whether the lease is still active */
    active: z.boolean().default(true),
    /** Number of times the lease has been extended */
    extensionCount: z.number().default(0),
});
/**
 * Default lease TTL (30 seconds)
 * Should be long enough for most operations but short enough to recover from crashes
 */
export const DEFAULT_LEASE_TTL_MS = 30_000;
/**
 * Maximum lease TTL (5 minutes)
 * Prevents indefinite locks
 */
export const MAX_LEASE_TTL_MS = 300_000;
/**
 * Maximum lease extensions allowed
 * Prevents infinite extension loops
 */
export const MAX_LEASE_EXTENSIONS = 10;
/**
 * Generate a unique lease ID
 */
export function generateLeaseId() {
    return `lease_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;
}
/**
 * Check if a lease has expired
 */
export function isLeaseExpired(lease) {
    return !lease.active || new Date() > lease.expiresAt;
}
/**
 * Calculate remaining TTL for a lease
 */
export function getRemainingTtl(lease) {
    const remaining = lease.expiresAt.getTime() - Date.now();
    return Math.max(0, remaining);
}
/**
 * Normalize file paths for comparison
 * Removes trailing slashes, normalizes separators
 */
export function normalizeFilePath(path) {
    return path.replace(/\\/g, "/").replace(/\/+$/, "").toLowerCase();
}
/**
 * Check if two file sets overlap
 */
export function filesOverlap(files1, files2) {
    const normalized1 = new Set(files1.map(normalizeFilePath));
    const normalized2 = files2.map(normalizeFilePath);
    return normalized2.filter((f) => normalized1.has(f));
}
