/**
 * File Domain Spine Events - ADR-007 §3
 *
 * Spine events for file watch and modification tracking.
 * Event types use three-part naming: file.<entity>.<action>
 *
 * @module @vreko/contracts/events/spine/domains/file
 * @see ADR-007 Runtime Tier Boundaries and Export Spine Contract
 */
import { z } from "zod";
import { createSpineEventSchema } from "../envelope.js";
// =============================================================================
// Shared File Schemas
// =============================================================================
/**
 * File modification operation types
 */
export const fileOperationSchema = z.enum([
    "create", // File created
    "modify", // File modified
    "delete", // File deleted
    "rename", // File renamed
]);
/**
 * File extension categories
 */
export const fileCategorySchema = z.enum([
    "source-code", // .ts, .js, .py, etc.
    "configuration", // .json, .yaml, .toml, etc.
    "documentation", // .md, .txt, etc.
    "test", // .test.ts, .spec.ts, etc.
    "asset", // .png, .svg, etc.
    "other", // Uncategorized
]);
// =============================================================================
// file.watch.modified
// =============================================================================
/**
 * Data payload for file.watch.modified event
 */
export const fileWatchModifiedDataSchema = z.object({
    /** SHA-256 hash of file path (never raw path per M7, N3) */
    filePathHash: z.string().regex(/^[0-9a-f]{64}$/i),
    /** File extension category */
    category: fileCategorySchema,
    /** Operation type */
    operation: fileOperationSchema,
    /** Size change in bytes (positive for growth, negative for shrinkage) */
    sizeChangeBytes: z.number().int(),
    /** Lines changed (if applicable) */
    linesChanged: z.number().int().optional(),
    /** Whether change is attributed to AI tool */
    aiAttributed: z.boolean(),
    /** Tool confidence if AI attributed */
    toolConfidence: z.number().min(0).max(1).optional(),
    /** Time since last modification in milliseconds */
    timeSinceLastModifyMs: z.number().int().nonnegative().optional(),
});
/**
 * Spine event schema for file.watch.modified
 *
 * Emitted when a watched file is modified.
 */
export const fileWatchModifiedSchema = createSpineEventSchema(fileWatchModifiedDataSchema);
/**
 * Event type constant
 */
export const FILE_WATCH_MODIFIED = "file.watch.modified";
// =============================================================================
// file.watch.batch
// =============================================================================
/**
 * Data payload for file.watch.batch event
 *
 * Batched file events for efficiency
 */
export const fileWatchBatchDataSchema = z.object({
    /** Number of files in batch */
    fileCount: z.number().int().positive().max(100),
    /** Operations summary */
    operations: z.object({
        create: z.number().int().nonnegative(),
        modify: z.number().int().nonnegative(),
        delete: z.number().int().nonnegative(),
        rename: z.number().int().nonnegative(),
    }),
    /** Categories summary */
    categories: z.object({
        "source-code": z.number().int().nonnegative(),
        configuration: z.number().int().nonnegative(),
        documentation: z.number().int().nonnegative(),
        test: z.number().int().nonnegative(),
        asset: z.number().int().nonnegative(),
        other: z.number().int().nonnegative(),
    }),
    /** Batch time window in milliseconds */
    windowMs: z.number().int().positive(),
    /** Whether any changes are AI attributed */
    aiAttributed: z.boolean(),
});
/**
 * Spine event schema for file.watch.batch
 *
 * Emitted when multiple file changes are batched.
 */
export const fileWatchBatchSchema = createSpineEventSchema(fileWatchBatchDataSchema);
/**
 * Event type constant
 */
export const FILE_WATCH_BATCH = "file.watch.batch";
// =============================================================================
// file.protection.changed
// =============================================================================
/**
 * Data payload for file.protection.changed event
 */
export const fileProtectionChangedDataSchema = z.object({
    /** SHA-256 hash of file path */
    filePathHash: z.string().regex(/^[0-9a-f]{64}$/i),
    /** New protection level */
    newLevel: z.enum(["watch", "warn", "block"]),
    /** Previous protection level */
    previousLevel: z.enum(["watch", "warn", "block"]).optional(),
    /** Source of protection change */
    source: z.enum([
        "auto-risk", // Automatic based on risk
        "manual-user", // User manually set
        "config-rule", // Configuration rule matched
        "session-context", // Session context change
    ]),
    /** Risk score at time of change */
    riskScore: z.number().min(0).optional(),
    /** Session ID if part of tracked session */
    sessionId: z.string().uuid().optional(),
});
/**
 * Spine event schema for file.protection.changed
 *
 * Emitted when file protection level changes.
 */
export const fileProtectionChangedSchema = createSpineEventSchema(fileProtectionChangedDataSchema);
/**
 * Event type constant
 */
export const FILE_PROTECTION_CHANGED = "file.protection.changed";
/**
 * All file event type constants
 */
export const FILE_EVENT_TYPES = [FILE_WATCH_MODIFIED, FILE_WATCH_BATCH, FILE_PROTECTION_CHANGED];
/**
 * Map of event types to their schemas for validation
 */
export const FILE_EVENT_SCHEMAS = {
    [FILE_WATCH_MODIFIED]: fileWatchModifiedSchema,
    [FILE_WATCH_BATCH]: fileWatchBatchSchema,
    [FILE_PROTECTION_CHANGED]: fileProtectionChangedSchema,
};
