import { z } from "zod";
// =============================================================================
// RISK PRIMITIVES (Phase 1  -  Contracts Compliance)
// =============================================================================
/**
 * Risk level classification.
 *
 * Mirrors the RiskLevel enum from local-service/schemas/primitives.ts but
 * exported here as `RiskLevelSchema` for use by SessionHealthSchema and other
 * cross-surface contracts that import from @vreko/contracts directly.
 */
export const RiskLevelSchema = z.enum(["low", "medium", "high", "critical"]);
/**
 * Scalar risk score on a 0–10 scale.
 *
 * This is the canonical runtime validator for numeric risk values stored in
 * the database (snapshots.riskScore, analysis_events.riskScore, etc.).
 * The richer object form with factors + severity lives in schemas.ts as
 * RiskScoreDetailSchema; use that when you need the full breakdown.
 *
 * Scale reference:
 *   low      0 – 2.9
 *   medium   3.0 – 4.9
 *   high     5.0 – 6.9
 *   critical 7.0 – 10.0
 */
export const RiskScoreSchema = z.number().min(0).max(10);
