/**
 * InstrumentationProvider Interface
 *
 * Core abstraction for distributed tracing and observability.
 * Enables vendor-neutral instrumentation across Vreko services.
 *
 * @example
 * ```typescript
 * const provider = new OTelInstrumentationProvider({
 *   serviceName: 'vreko-api',
 *   collectorUrl: 'http://localhost:4318',
 * });
 *
 * await provider.withSpan('create_snapshot', async (span) => {
 *   span.setAttribute('snapshot.id', id);
 *   const result = await createSnapshot(files);
 *   return result;
 * });
 * ```
 */
/**
 * No-op implementation for testing or disabled instrumentation
 */
export class NoOpInstrumentationProvider {
    static noopSpan = {
        setAttribute: () => {
            /* no-op */
        },
        setAttributes: () => {
            /* no-op */
        },
        addEvent: () => {
            /* no-op */
        },
        setStatus: () => {
            /* no-op */
        },
        recordException: () => {
            /* no-op */
        },
        end: () => {
            /* no-op */
        },
        isRecording: () => false,
    };
    startSpan(_name, _options) {
        return NoOpInstrumentationProvider.noopSpan;
    }
    async withSpan(_name, fn, _options) {
        return await fn(NoOpInstrumentationProvider.noopSpan);
    }
    injectContext(_carrier) {
        // No-op
    }
    extractContext(_carrier) {
        return null;
    }
    recordMetric(_name, _value, _attributes) {
        // No-op
    }
    recordEvent(_name, _attributes) {
        // No-op
    }
    async shutdown() {
        // No-op
    }
}
