// ESM imports fixed for Node.js v22+
/**
 * ToolInvocation - Phase 0 Unified Envelope Primitive
 *
 * Single envelope type for ALL tool invocations across all surfaces:
 * - API routes
 * - MCP server
 * - OpenClaw channels
 * - CLI commands
 * - VS Code extension
 *
 * This replaces scattered adapter/handler patterns with ONE translation point.
 *
 * Design Principles (from feedback review):
 * - ENVELOPE FIRST: Define primitive before handlers/adapters
 * - REDUCTIVE: Single type, not multiple translation layers
 * - VERIFY > ASSERT: Types enforce constraints, runtime validates
 *
 * @module primitives/tool-invocation
 */
import { z } from "zod";
import { ToolURNSchema } from "./tool-urn.js";
/**
 * Agent runtime identifiers
 * Tracks which AI agent initiated the tool call
 */
export const AGENT_RUNTIMES = [
    "claude-code",
    "cursor",
    "copilot",
    "openclaw",
    "windsurf",
    "cline",
    "aider",
    "continue",
    "unknown",
];
/**
 * Sandbox isolation levels
 * Determines execution environment constraints
 */
export const SANDBOX_LEVELS = ["none", "basic", "strict", "isolated"];
/**
 * Risk classification for tools
 * Determines required security gates and approval flows
 */
export const RISK_CLASSES = ["safe", "low", "medium", "high", "critical"];
/**
 * Channel identifiers for multi-channel support
 */
export const CHANNELS = [
    "api",
    "mcp",
    "vscode",
    "cli",
    "web",
    "whatsapp",
    "telegram",
    "discord",
    "slack",
    "teams",
    "matrix",
];
/**
 * Session context - who is making the request
 */
export const SessionContextSchema = z.object({
    /** Channel through which request was made */
    channel: z.enum(CHANNELS),
    /** Workspace identifier (local path hash or cloud workspace ID) */
    workspaceId: z.string().min(1),
    /** Session ID for request correlation */
    sessionId: z.string().uuid(),
    /** OpenClaw session ID if bridged */
    openclawSessionId: z.string().optional(),
    /** Channel-specific user identifier */
    channelUserId: z.string().optional(),
});
/**
 * Identity context - entitlements and permissions
 */
export const IdentityContextSchema = z.object({
    /** User ID (authenticated) */
    userId: z.string().uuid().optional(),
    /** Anonymous identifier for unauthenticated requests */
    anonymousId: z.string().optional(),
    /** Current subscription tier */
    tier: z.enum(["free", "pro", "team", "enterprise"]).default("free"),
    /** Enabled features for this user */
    features: z.array(z.string()).default([]),
    /** Pre-resolved entitlements (optional, can be fetched) */
    entitlements: z
        .object({
        tier: z.enum(["free", "pro", "team", "enterprise"]),
        features: z.array(z.string()),
        limits: z.record(z.string(), z.number().nullable()),
    })
        .optional(),
    /** API key identifier (if using API key auth) */
    apiKeyId: z.string().optional(),
});
/**
 * Tool specification - what tool is being invoked
 */
export const ToolSpecSchema = z.object({
    /** Tool URN (canonical identifier) */
    urn: ToolURNSchema,
    /** Tool risk classification */
    riskClass: z.enum(RISK_CLASSES),
    /** Required permissions to invoke this tool */
    requiredPermissions: z.array(z.string()).default([]),
    /** Required features (entitlement check) */
    requiredFeatures: z.array(z.string()).default([]),
    /** Minimum tier required */
    minTier: z.enum(["free", "pro", "team", "enterprise"]).optional(),
});
/**
 * Execution context - how to execute the tool
 */
export const ExecutionContextSchema = z.object({
    /** Agent runtime that initiated the call */
    agentRuntime: z.enum(AGENT_RUNTIMES).default("unknown"),
    /** Required sandbox level */
    sandboxLevel: z.enum(SANDBOX_LEVELS).default("basic"),
    /** Timeout in milliseconds */
    timeoutMs: z.number().positive().default(30000),
    /** Whether to auto-snapshot before execution */
    snapshotBefore: z.boolean().default(false),
    /** Maximum concurrent executions allowed */
    maxConcurrent: z.number().positive().default(1),
    /** Retry configuration */
    retry: z
        .object({
        maxAttempts: z.number().min(1).max(5).default(1),
        backoffMs: z.number().min(100).max(30000).default(1000),
    })
        .optional(),
});
/**
 * ToolInvocation - THE unified envelope for all tool calls
 *
 * This is the SINGLE primitive that flows through the entire ExecutionPipeline.
 * All adapters (API, MCP, OpenClaw) translate TO this type, never from it.
 */
export const ToolInvocationSchema = z.object({
    /** Unique trace ID for request correlation and audit */
    traceId: z.string().uuid(),
    /** Timestamp when invocation was created */
    createdAt: z.coerce.date().default(() => new Date()),
    /** Session context - channel and workspace */
    session: SessionContextSchema,
    /** Identity context - who and what permissions */
    identity: IdentityContextSchema,
    /** Tool specification - what tool and risk class */
    tool: ToolSpecSchema,
    /** Tool arguments (validated against tool's input schema) */
    args: z.record(z.string(), z.unknown()).default({}),
    /** Execution context - how to execute */
    context: ExecutionContextSchema,
    /**
     * Metadata for observability and debugging
     * Not used in execution logic, only for tracing
     */
    metadata: z
        .object({
        /** Source surface that created this invocation */
        source: z.string().optional(),
        /** Parent trace ID for nested calls */
        parentTraceId: z.string().uuid().optional(),
        /** Custom labels for filtering */
        labels: z.record(z.string(), z.string()).optional(),
        /** Original request payload hash (for audit) */
        requestHash: z.string().optional(),
    })
        .optional(),
});
/**
 * Pipeline step result - output from each pipeline step
 */
export const PipelineStepResultSchema = z.object({
    /** Step name */
    step: z.string(),
    /** Whether step passed */
    passed: z.boolean(),
    /** Duration in milliseconds */
    durationMs: z.number(),
    /** Error if step failed */
    error: z
        .object({
        code: z.string(),
        message: z.string(),
        details: z.unknown().optional(),
    })
        .optional(),
    /** Step-specific data */
    data: z.unknown().optional(),
});
/**
 * Execution result - final output from pipeline
 */
export const ExecutionResultSchema = z.object({
    /** Trace ID from invocation */
    traceId: z.string().uuid(),
    /** Whether execution succeeded */
    success: z.boolean(),
    /** Result data (if successful) */
    result: z.unknown().optional(),
    /** Error details (if failed) */
    error: z
        .object({
        code: z.string(),
        message: z.string(),
        step: z.string().optional(),
        details: z.unknown().optional(),
    })
        .optional(),
    /** Pipeline step results */
    steps: z.array(PipelineStepResultSchema),
    /** Total execution duration */
    durationMs: z.number(),
    /** Snapshot ID if created */
    snapshotId: z.string().optional(),
    /** Audit log ID */
    auditId: z.string().optional(),
});
/**
 * Create a ToolInvocation with defaults
 *
 * @param input - Partial invocation input
 * @returns Validated ToolInvocation
 *
 * @example
 * ```typescript
 * const invocation = createToolInvocation({
 *   traceId: crypto.randomUUID(),
 *   session: { channel: "mcp", workspaceId: "ws_123", sessionId: "..." },
 *   identity: { tier: "pro" },
 *   tool: { urn: "urn:vreko:core:snapshot:1.0.0", riskClass: "low" },
 *   args: { reason: "manual" },
 *   context: { agentRuntime: "claude-code" },
 * });
 * ```
 */
export function createToolInvocation(input) {
    return ToolInvocationSchema.parse(input);
}
/**
 * Validate a ToolInvocation (safe parse)
 *
 * @param input - Input to validate
 * @returns Result with success flag and data/error
 */
export function validateToolInvocation(input) {
    return ToolInvocationSchema.safeParse(input);
}
/**
 * Create minimal invocation for internal use
 * Requires only essential fields, uses safe defaults
 */
export function createMinimalInvocation(urn, args, options = {}) {
    return createToolInvocation({
        traceId: crypto.randomUUID(),
        session: {
            channel: options.channel ?? "api",
            workspaceId: options.workspaceId ?? "local",
            sessionId: crypto.randomUUID(),
        },
        identity: {
            tier: options.tier ?? "free",
        },
        tool: {
            urn,
            riskClass: "low", // Default, will be overridden by registry
        },
        args,
        context: {
            agentRuntime: options.agentRuntime ?? "unknown",
        },
    });
}
/**
 * Extract key identifiers from invocation for logging
 */
export function extractInvocationIds(invocation) {
    return {
        traceId: invocation.traceId,
        sessionId: invocation.session.sessionId,
        workspaceId: invocation.session.workspaceId,
        toolUrn: invocation.tool.urn,
        channel: invocation.session.channel,
    };
}
