// =============================================================================
// EFFECTIVE SCOPES
// =============================================================================
// =============================================================================
// ZOD SCHEMA
// =============================================================================
import { z } from "zod";
export const OrgModeSchema = z.enum(["none", "shared", "ring_fenced"]);
export const EffectiveScopesSchema = z.object({
    personal: z.boolean(),
    global: z.boolean(),
    org: z
        .object({
        orgId: z.string(),
        mode: OrgModeSchema,
    })
        .nullable(),
});
