import { z } from "zod";
/**
 * Authentication scope boundaries (ADR-005):
 * - console: Console UI, settings, team management, billing, API key CRUD
 * - api: V2 REST API endpoints, credit consumption
 * - API keys ONLY carry 'api' scope. Never 'console'.
 * - Console sessions ONLY carry 'console' scope.
 * - Team members may have both scopes via separate credentials.
 */
export const AuthScope = z.enum(["console", "api"]);
