import { z } from "zod";
export const MAX_WORKSPACES = 100; // Cap to prevent unbounded growth
export const WorkspaceRegistrationSchema = z.object({
    id: z.string(), // SHA256 of canonical path  -  existing convention
    path: z.string(),
    alias: z.string().optional(),
    ownership: z.enum(["personal", "team"]),
    teamId: z.string().optional(),
    createdAt: z.coerce.date(),
    lastSeenAt: z.coerce.date(),
    stackSummary: z.string().optional(), // cached display string, e.g. "TS monorepo · Cursor"
});
export const WorkspaceProfileSchema = z.object({
    version: z.literal("1").default("1"),
    detectedAt: z.coerce.date(),
    repoType: z.enum(["monorepo", "single", "multi-package", "unknown"]),
    primaryLanguage: z.string(),
    buildSystem: z.enum(["turborepo", "nx", "lerna", "none", "unknown"]),
    packageManager: z.enum(["pnpm", "npm", "yarn", "bun", "unknown"]),
    detectedAiTools: z.array(z.enum(["cursor", "copilot", "claude-code", "windsurf", "unknown"])),
    estimatedFileCount: z.number().int(),
    estimatedContributors: z.number().int(),
    hasCI: z.boolean(),
    hasTests: z.boolean(),
    // SEMANTIC DISTINCTION:
    // - null  = CTI has not run yet (default, unanalyzed)
    // - []    = CTI ran, no critical paths found (analysis complete, no results)
    // This distinction drives onboarding flow and CTI scheduling decisions.
    criticalPaths: z.array(z.string()).nullable().default(null),
    detectionFailed: z.boolean().default(false), // true if detection pass threw; triggers retry
    detectionError: z.string().optional(), // error message for debugging
});
