import { z } from "zod";
// =============================================================================
// AI TOOL & DETECTION TYPES (Phase 1  -  Contracts Compliance)
// =============================================================================
/**
 * Canonical enum of AI coding assistants that Vreko can detect.
 *
 * This is the cross-surface canonical list used by the detection pipeline.
 * Note: the local-service/schemas/ai-config.ts AITool enum covers agent-config
 * file formats (cursor, claude-code, cline…); this enum covers editor/IDE
 * plugin detection (copilot, codeium, tabnine, cody, continue, aider…).
 */
export const AIToolSchema = z.enum([
    "cursor",
    "copilot",
    "claude",
    "windsurf",
    "codeium",
    "tabnine",
    "cody",
    "continue",
    "aider",
]);
/**
 * Result of running the AI detection heuristic against a set of change events.
 *
 * This is the simple, flat version used by external API consumers.
 * The richer discriminated-union form (detected: true | false) lives in
 * local-service/schemas/entities.ts as AIDetectionResult for IPC transport.
 */
export const AIDetectionResultSchema = z.object({
    detected: z.boolean(),
    confidence: z.number().min(0).max(1),
    tool: AIToolSchema.nullable(),
    patterns: z.array(z.string()),
    evidence: z.array(z.string()).optional(),
});
