import { z } from "zod";
// Use DaemonTier to avoid conflict with primitives/tool-invocation.ts Tier export
export const DaemonTierSchema = z.enum(["free", "pro", "team", "enterprise"]);
// DaemonIdentityContext - daemon-specific identity state (avoids conflict with tool-invocation.ts)
export const DaemonIdentityContextSchema = z.object({
    userId: z.string().nullable(),
    email: z.string().email().nullable(),
    tier: DaemonTierSchema.default("free"),
    pioneer: z.boolean().default(false),
    cohort: z.number().int().nullable(),
    keyPreview: z.string().nullable(),
    // NOTE: 'cli-token' covers device auth flow; 'api-key' is raw key from env
    authenticatedVia: z.enum(["github", "google", "api-key", "cli-token"]).nullable(),
    tokenExpiresAt: z.coerce.date().nullable(),
    lastValidatedAt: z.coerce.date().nullable(),
    isStale: z.boolean(), // computed at read time: Date.now() - lastValidatedAt > 24h; never persisted
});
export const DAEMON_TIER_ORDER = {
    free: 0,
    pro: 1,
    team: 2,
    enterprise: 3,
};
export function isDaemonAtLeastTier(identity, minimum) {
    return DAEMON_TIER_ORDER[identity.tier] >= DAEMON_TIER_ORDER[minimum];
}
// Sentinel for unauthenticated state  -  never null, always a valid object
export const ANONYMOUS_DAEMON_IDENTITY = {
    userId: null,
    email: null,
    tier: "free",
    pioneer: false,
    cohort: null,
    keyPreview: null,
    authenticatedVia: null,
    tokenExpiresAt: null,
    lastValidatedAt: null,
    isStale: true,
};
