// ESM imports fixed for Node.js v22+
// packages/contracts/src/boundary/index.ts
//
// Trust-boundary schemas. Every place where data crosses a process, network, or
// storage layer and was previously coerced with `as T` validates here instead.
//
// Invariant (mirrors §2.3): a boundary deserializer does not accept untyped input.
// The schema is required by signature, not by convention, so a future call site
// cannot route around it.
import { z } from "zod";
import { JsonRpcMessageSchema } from "../local-service/protocol.js";
// ─────────────────────────────────────────────────────────────────────────────
// TIER 0 — IPC receiver (dire)
//
// The daemon server already guards inbound with JsonRpcMessageSchema. This is the
// read-path mirror: the client must not trust a line off the socket just because
// the daemon sent it. A deformed frame here propagates into whichever thin client
// (extension, CLI, MCP) ingested it and surfaces far from the cause.
//
// VERIFY BEFORE MERGE: grep the actual client type name and shape:
//   grep -rn "IpcConnectionEvent" packages/local-service-client/src
// The connection-event variants below are the documented set; reconcile the
// literal tags and payloads against the real union before locking.
// ─────────────────────────────────────────────────────────────────────────────
export const IpcConnectionEventSchema = z.discriminatedUnion("type", [
    z.object({ type: z.literal("connected"), pid: z.number().int().optional() }),
    z.object({ type: z.literal("disconnected"), reason: z.string().optional() }),
    z.object({
        type: z.literal("error"),
        code: z.string().optional(),
        message: z.string(),
    }),
    // JSON-RPC traffic (responses + notifications) arrives on the same stream.
    z.object({ type: z.literal("message"), payload: JsonRpcMessageSchema }),
]);
/**
 * Parse a single newline-delimited frame from the daemon socket.
 *
 * Returns a discriminated result rather than throwing: a single corrupt frame
 * must not kill the receiver loop. The caller logs `{ ok: false }` and drops the
 * frame, exactly as the MCP cache services should skip bad JSONL lines.
 */
export function parseIpcFrame(line) {
    let json;
    try {
        json = JSON.parse(line);
    }
    catch (e) {
        return { ok: false, error: `malformed JSON: ${e.message}`, raw: line };
    }
    const parsed = IpcConnectionEventSchema.safeParse(json);
    if (!parsed.success) {
        return { ok: false, error: parsed.error.message, raw: line };
    }
    return { ok: true, event: parsed.data };
}
// ─────────────────────────────────────────────────────────────────────────────
// TIER 1 — CLI base API client (highest structural ROI)
//
// The win is the signature, not any one schema: requestJson now *requires* a
// schema, so every CLI call site inherits validation by compilation. There is no
// opt-out path. Infra cold starts / gateway 502s that return non-JSON HTML are
// caught here as a typed error instead of a thrown SyntaxError deep in a command.
// ─────────────────────────────────────────────────────────────────────────────
export class BoundaryError extends Error {
    kind;
    status;
    constructor(message, kind, status) {
        super(message);
        this.kind = kind;
        this.status = status;
        this.name = "BoundaryError";
    }
}
/**
 * Drop-in for the existing `(await res.json()) as T`. Pass the schema; get back a
 * validated T or a typed BoundaryError. Wire this as the only deserialize path in
 * api-client.ts so callers cannot reach the raw body.
 */
export async function requestJson(response, schema) {
    if (!response.ok) {
        throw new BoundaryError(`HTTP ${response.status} from ${response.url}`, "http", response.status);
    }
    const text = await response.text();
    let json;
    try {
        json = JSON.parse(text);
    }
    catch {
        // The 502-HTML-load-balancer case. Truncate so a full HTML page does not
        // land in logs / Sentry breadcrumbs.
        throw new BoundaryError(`expected JSON, got non-JSON body (first 120 chars): ${text.slice(0, 120)}`, "non-json", response.status);
    }
    const parsed = schema.safeParse(json);
    if (!parsed.success) {
        throw new BoundaryError(parsed.error.message, "schema-mismatch", response.status);
    }
    return parsed.data;
}
// Device auth payloads (Tier 1, item 3). The tiered-license edge cases live in
// the token payload, so license fields are explicit and optional rather than
// passed through.
export const DeviceCodeResponseSchema = z.object({
    device_code: z.string(),
    user_code: z.string(),
    verification_uri: z.string().url(),
    verification_uri_complete: z.string().url().optional(),
    expires_in: z.number().int().positive(),
    interval: z.number().int().positive().default(5),
});
export const TokenResponseSchema = z.object({
    access_token: z.string(),
    token_type: z.string(),
    refresh_token: z.string().optional(),
    expires_in: z.number().int().positive().optional(),
    // Tiered-license fields: present on some backends, absent on others. Explicit
    // so a missing tier is `undefined`, not a crash on property access.
    license_tier: z.enum(["pro", "team", "trial"]).optional(),
    seats: z.number().int().optional(),
});
