/**
 * API Error Codes
 *
 * Standard error codes organized by category for the Vreko API.
 *
 * @module @vreko/contracts/api/errors/codes
 */
import { z } from "zod";
// =============================================================================
// ERROR CODE TAXONOMY
// =============================================================================
/**
 * API Error Code Categories:
 *
 * AUTH_*         - Authentication and authorization errors
 * VALIDATION_*   - Input validation and schema errors
 * RESOURCE_*     - Resource lifecycle errors (CRUD)
 * RATE_*         - Rate limiting and throttling
 * PAYMENT_*      - Billing and subscription errors
 * INTEGRATION_*  - External service errors
 * INTERNAL_*     - Server-side errors
 */
/**
 * Standard API error codes organized by category
 */
export const ApiErrorCodeSchema = z.enum([
    // Authentication (401)
    "AUTH_REQUIRED",
    "AUTH_INVALID_TOKEN",
    "AUTH_EXPIRED_TOKEN",
    "AUTH_INVALID_API_KEY",
    "AUTH_REVOKED_KEY",
    // Authorization (403)
    "FORBIDDEN",
    "PERMISSION_DENIED",
    "PLAN_LIMIT_EXCEEDED",
    "FEATURE_NOT_AVAILABLE",
    "TRIAL_EXPIRED",
    // Validation (400)
    "VALIDATION_ERROR",
    "VALIDATION_MISSING_FIELD",
    "VALIDATION_INVALID_FORMAT",
    "VALIDATION_CONSTRAINT_VIOLATION",
    // Resource Errors (404, 409, 410)
    "RESOURCE_NOT_FOUND",
    "RESOURCE_ALREADY_EXISTS",
    "RESOURCE_DELETED",
    "RESOURCE_CONFLICT",
    "RESOURCE_LOCKED",
    // Rate Limiting (429)
    "RATE_LIMIT_EXCEEDED",
    "RATE_LIMIT_API_KEY",
    "RATE_LIMIT_USER",
    "RATE_LIMIT_IP",
    // Payment/Billing (402)
    "PAYMENT_REQUIRED",
    "PAYMENT_FAILED",
    "SUBSCRIPTION_EXPIRED",
    "SUBSCRIPTION_CANCELLED",
    // External Integration Errors (502, 503)
    "INTEGRATION_UNAVAILABLE",
    "INTEGRATION_TIMEOUT",
    "INTEGRATION_ERROR",
    // Security (400, 403)
    "SECURITY_CSRF_INVALID",
    "SECURITY_CAPTCHA_REQUIRED",
    "SECURITY_CAPTCHA_FAILED",
    "SECURITY_PRIVACY_VIOLATION",
    // Server Errors (500, 503)
    "INTERNAL_ERROR",
    "SERVICE_UNAVAILABLE",
    "DATABASE_ERROR",
    "CONFIGURATION_ERROR",
    // Request Errors (400, 413, 415)
    "BAD_REQUEST",
    "PAYLOAD_TOO_LARGE",
    "UNSUPPORTED_MEDIA_TYPE",
    "METHOD_NOT_ALLOWED",
]);
