/**
 * CalculationTrace Schema
 *
 * Zod schema for fragility score calculation transparency.
 * PRIVACY: Aggregated metrics only  -  no file paths, no user content.
 * The implicit rollback breakdown is the novel detection mechanism.
 *
 * @module @vreko/contracts/calculation-trace
 */
import { z } from "zod";
/**
 * PRIVACY: Aggregated count  -  no individual user identifiers.
 */
const ImplicitRollbackBucketSchema = z
    .object({
    count: z.number().int().min(0),
    weightedSum: z.number().min(0),
})
    .strict();
/**
 * Rollback rate breakdown with explicit AI-attribution separation.
 * This is the novel detection mechanism: implicit AI-attributed rollbacks
 * are distinguished from unattributed implicit rollbacks.
 * PRIVACY: All fields are aggregated counts  -  no file or session identifiers.
 */
export const RollbackRateTraceSchema = z
    .object({
    /** Explicit rollbacks (user-initiated restore). */
    explicit: z.number().int().min(0),
    /** Implicit rollbacks attributed to AI-generated code. */
    implicitAIAttributed: ImplicitRollbackBucketSchema,
    /** Implicit rollbacks not attributed to AI-generated code. */
    implicitUnattributed: ImplicitRollbackBucketSchema,
    /** Total file modifications in the observation window. */
    totalModifications: z.number().int().min(0),
    /** Computed rate: (explicit + weighted implicit) / totalModifications. */
    computedRate: z.number().min(0).max(1),
})
    .strict();
/**
 * Per-pillar fragility contribution.
 * PRIVACY: weight and contribution are dimensionless scalars  -  no user data.
 */
const FragilityPillarTraceSchema = z
    .object({
    pillar: z.enum(["churn", "rollback", "ai_fraction", "time_since_commit", "file_count"]),
    weight: z.number().min(0).max(1),
    rawValue: z.number(),
    contribution: z.number().min(0).max(1),
})
    .strict();
/**
 * Fragility score broken down by pillar.
 * PRIVACY: Aggregated workspace metrics only.
 */
export const FragilityTraceSchema = z
    .object({
    pillars: z.array(FragilityPillarTraceSchema).min(1),
    /** Weighted sum across all pillars before clamping. */
    rawScore: z.number(),
    /** Final fragility score after clamping to [0, 1]. */
    computedScore: z.number().min(0).max(1),
})
    .strict();
/**
 * Trust score calculation trace.
 * PRIVACY: All fields are aggregated  -  no individual session or file data.
 */
export const TrustScoreTraceSchema = z
    .object({
    /** Agent rollback rate for this workspace. */
    agentRollbackRate: z.number().min(0).max(1),
    /** Fleet-wide average rollback rate for comparison. */
    workspaceAvgRollbackRate: z.number().min(0).max(1),
    /** Number of observations used to compute the rate. */
    observationCount: z.number().int().min(0),
    /** Bayesian prior weight (lower = more observations = less prior pull). */
    priorWeight: z.number().min(0).max(1),
    /** Final trust score after Bayesian smoothing. */
    computedScore: z.number().min(0).max(1),
})
    .strict();
/**
 * Full calculation trace for a fragility score decision.
 *
 * Enables platform leads and auditors to inspect exactly how a score was
 * computed without exposing raw user data.
 *
 * PRIVACY: No file paths, no code content, no session IDs.
 * Only aggregated scalar metrics and their weights.
 */
export const CalculationTraceSchema = z
    .object({
    /** ISO 8601 timestamp of the calculation. */
    calculatedAt: z.string().datetime(),
    /** Opaque workspace identifier (sha256-derived, never raw path). */
    workspaceId: z.string(),
    /** Fragility pillar breakdown. */
    fragility: FragilityTraceSchema,
    /** Rollback rate decomposition  -  the novel AI-attribution signal. */
    rollbackRate: RollbackRateTraceSchema,
    /** Trust score Bayesian trace. */
    trustScore: TrustScoreTraceSchema,
})
    .strict(); // reject unknown fields  -  prevents accidental content leakage
